var _dusk_blockade_nodes: Dictionary = {}
var _dusk_vehicle_nodes: Dictionary = {}
func _sync_dusk_vehicles() -> void:
	var state = _battle_state()
	_sync_blockade_barriers(state)
	if not _is_dusk_street() or state == null:
		for n in _dusk_vehicle_nodes.values():
			if is_instance_valid(n): n.queue_free()
		_dusk_vehicle_nodes.clear()
		return
	for id in state.vehicles:
		var vehicle = state.get_vehicle(id)
		if vehicle == null or not vehicle.has_battle_position: continue
		var corners = BattleVehicleBodyService.world_corners(vehicle)
		if corners.size() != 4: continue
		var bounds := Rect2(corners[0],Vector2.ZERO)
		for corner in corners: bounds = bounds.expand(corner)
		var node = _dusk_vehicle_nodes.get(id)
		if node == null:
			node = preload("res://gameplay/fleet_vehicle_art.gd").new()
			node.prop = ["arrival_car",bounds,"car",""]
			dynamic_unit_root.add_child(node)
			_dusk_vehicle_nodes[id] = node
		node.model_id = vehicle.vehicle_type_id
		node.facing = vehicle.facing_direction
		var next_position := Vector2(vehicle.battle_position.x*8,vehicle.battle_position.y*6)
		var changed: bool = node.prop.is_empty() or node.position != next_position
		node.prop = ["arrival_car",bounds,"car",""]
		node.position = next_position
		if changed: node.queue_redraw()

var _dusk_zoom: float = 1.2
var _dusk_pan: Vector2 = Vector2.ZERO
func _unhandled_input(event: InputEvent) -> void:
	if not _is_dusk_street() or not visible or _camera == null:
		return
	if event is InputEventMouseButton and event.pressed:
		if event.button_index == MOUSE_BUTTON_WHEEL_UP or event.button_index == MOUSE_BUTTON_WHEEL_DOWN:
			var factor: float = 1.15 if event.button_index == MOUSE_BUTTON_WHEEL_UP else 1.0/1.15
			_dusk_zoom = clampf(_dusk_zoom*factor,0.65 if _is_river_bridge() else 0.8,4.0 if _is_river_bridge() else 2.5)
			_frame_camera()
			get_viewport().set_input_as_handled()
	if event is InputEventMouseMotion and event.button_mask & MOUSE_BUTTON_MASK_MIDDLE:
		_dusk_pan -= event.relative / _camera.zoom
		_frame_camera()
		get_viewport().set_input_as_handled()
	if event is InputEventKey and event.pressed and event.keycode == KEY_HOME:
		_dusk_zoom = 1.0
		_dusk_pan = Vector2.ZERO
		_frame_camera()
		get_viewport().set_input_as_handled()

func _sync_blockade_barriers(state) -> void:
	var wanted={}
	if _is_dusk_street() and state!=null and state.battlefield_geometry!=null:
		for id in state.battlefield_geometry.obstacles:
			if str(id).begins_with("roadwarden_screen_"):wanted[id]=state.battlefield_geometry.obstacles[id]
	for id in _dusk_blockade_nodes.keys():
		if not wanted.has(id):
			if is_instance_valid(_dusk_blockade_nodes[id]):_dusk_blockade_nodes[id].queue_free()
			_dusk_blockade_nodes.erase(id)
	for id in wanted:
		if not _dusk_blockade_nodes.has(id):
			var node=preload("res://gameplay/blockade_barrier_art.gd").new()
			var center=wanted[id].bounds.get_center();node.position=Vector2(center.x*8,center.y*6)
			dynamic_unit_root.add_child(node);_dusk_blockade_nodes[id]=node



func _draw_player_order_overlays(battle_state: BattleState) -> void:
	if orders_controller == null or battle_state.battle_phase != "active":
		return
	var canvas = _paint_canvas()
	_draw_command_cues(canvas)
	# Selection uses the emblem glow; only brief command placement cues are drawn.


func _draw_command_cues(canvas: CanvasItem) -> void:
	var c = orders_controller
	var now = Time.get_ticks_msec()
	var command = c.pending_command_id
	var x: float = c.line_x
	var spans: Array = c.line_spans
	var alpha = .45
	if command not in ["push", "fall_back"]:
		if not c.confirmation.is_empty():
			var age = (now - int(c.confirmation.time)) / 1000.0
			if age < .55:
				command = c.confirmation.command
				x = c.confirmation.x
				spans = c.confirmation.spans
				alpha = .60 * (1.0 - smoothstep(.10, .55, age))
			else:
				c.confirmation = {}
	if command in ["push", "fall_back"]:
		var ink = Color("#80bc92") if command == "push" else Color("#ce7f7c")
		ink.a = alpha
		var width = 8.0 / maxf(_camera.zoom.x, .1)
		for span in spans:
			canvas.draw_line(_to_view(Vector2(x, span.x)), _to_view(Vector2(x, span.y)), ink, width, true)
	for i in range(c.hold_pulses.size()-1, -1, -1):
		var pulse = c.hold_pulses[i]
		var age = (now - int(pulse.time)) / 1000.0
		if age >= .55:
			c.hold_pulses.remove_at(i)
			continue
		var ink = Color("#a8adb1")
		ink.a = .45 * (1.0 - age / .55)
		canvas.draw_arc(_to_view(pulse.at), 5.0 + age * 3.0, 0, TAU, 24, ink, 1.5 / maxf(_camera.zoom.x, .1), true)

