static func evaluate_all(
	battle_state: BattleState,
	participant: BattleParticipant,
	hostile: BattleParticipant,
	require_reachable: bool,
	require_weapon_range: bool,
	max_move_distance: float = INF
) -> Array[BattleCombatCoverEvaluation]:
	var evaluations: Array[BattleCombatCoverEvaluation] = []
	if battle_state == null or participant == null or battle_state.battlefield_geometry == null:
		return evaluations
	for slot_id: String in battle_state.battlefield_geometry.get_sorted_cover_slot_ids():
		var slot: BattleCoverSlot = battle_state.battlefield_geometry.get_cover_slot(slot_id)
		if slot == null:
			continue
		evaluations.append(
			evaluate_slot(
				battle_state,
				participant,
				slot,
				hostile,
				require_reachable,
				require_weapon_range,
				max_move_distance
			)
		)
	return evaluations


static func evaluate_slot(
	battle_state: BattleState,
	participant: BattleParticipant,
	slot: BattleCoverSlot,
	hostile: BattleParticipant,
	require_reachable: bool,
	require_weapon_range: bool,
	max_move_distance: float = INF,
	prepared_protection: BattleCoverProtectionResult = null
) -> BattleCombatCoverEvaluation:
	var evaluation: BattleCombatCoverEvaluation = BattleCombatCoverEvaluation.new()
	if slot != null:
		evaluation.slot_id = slot.cover_slot_id
	if participant == null or slot == null or not slot.is_valid():
		return evaluation
	evaluation.legal = _slot_is_legal_for_participant(participant, slot)
	evaluation.move_distance = INF
	if _is_positioned(participant) and BattlefieldGeometry.is_finite_point(slot.position):
		evaluation.move_distance = participant.battle_position.distance_to(slot.position)
	var within_seek: bool = true
	if is_finite(max_move_distance):
		within_seek = (
			is_finite(evaluation.move_distance)
			and (
				evaluation.move_distance < max_move_distance
				or is_equal_approx(evaluation.move_distance, max_move_distance)
			)
		)
	if hostile != null and _is_positioned(hostile):
		var protection: BattleCoverProtectionResult = prepared_protection
		if protection == null:
			protection = BattleCoverProtectionService.query_slot_protection(slot,hostile.battle_position)
		if protection != null and protection.has_applicable_cover:
			evaluation.protection_factor = protection.protection_factor
			evaluation.alignment_dot = protection.alignment_dot
	evaluation.has_useful_direction = is_useful_protection_factor(evaluation.protection_factor)
	if hostile != null and _is_positioned(hostile) and battle_state != null:
		var los: BattleLineOfSightResult = BattleLineOfSightService.check_segment(
			battle_state,
			slot.position,
			hostile.battle_position
		)
		if los != null and los.success:
			evaluation.has_line_of_sight = los.has_line_of_sight
			evaluation.blocking_obstacle_id = los.blocking_obstacle_id
		evaluation.in_weapon_max_range = _slot_is_within_weapon_max_range(
			slot,
			hostile,
			_participant_weapon_type_id(participant)
		)
	var cheap_usable: bool = (
		evaluation.legal
		and within_seek
		and evaluation.has_useful_direction
		and evaluation.has_line_of_sight
		and (evaluation.in_weapon_max_range if require_weapon_range else true)
	)
	evaluation.reachable = false
	if cheap_usable:
		if (
			is_finite(evaluation.move_distance)
			and evaluation.move_distance <= BattleCoverService.COVER_OCCUPANCY_EPSILON
		):
			evaluation.reachable = true
		elif require_reachable:
			evaluation.reachable = _slot_is_reachable(battle_state, participant, slot)
		else:
			evaluation.reachable = true
	evaluation.combat_usable = cheap_usable and evaluation.reachable
	return evaluation


static func first_reachable_ranked_slot(
	battle_state: BattleState,
	participant: BattleParticipant,
	ranked: Array[BattleCombatCoverEvaluation],
	skip_self_occupied: bool
) -> BattleCoverSlot:
	if battle_state == null or participant == null or battle_state.battlefield_geometry == null:
		return null
	for evaluation: BattleCombatCoverEvaluation in ranked:
		if evaluation == null or evaluation.slot_id.is_empty():
			continue
		var slot: BattleCoverSlot = battle_state.battlefield_geometry.get_cover_slot(evaluation.slot_id)
		if slot == null or not slot.is_valid():
			continue
		if skip_self_occupied and slot.occupied_by_participant_id == participant.participant_id:
			continue
		if _slot_is_reachable(battle_state, participant, slot):
			return slot
	return null


static func _insert_ranked(
	ranked: Array[BattleCombatCoverEvaluation],
	candidate: BattleCombatCoverEvaluation,
	prefer_band: bool
) -> void:
	var index: int = 0
	while index < ranked.size() and not _rank_less(candidate, ranked[index], prefer_band):
		index += 1
	ranked.insert(index, candidate)


static func _insert_closing_ranked(
	ranked: Array[BattleCombatCoverEvaluation],
	candidate: BattleCombatCoverEvaluation
) -> void:
	var index: int = 0
	while index < ranked.size() and not _closing_rank_less(candidate, ranked[index]):
		index += 1
	ranked.insert(index, candidate)


static func _insert_near_first_ranked(
	ranked: Array[BattleCombatCoverEvaluation],
	candidate: BattleCombatCoverEvaluation
) -> void:
	var index: int = 0
	while index < ranked.size() and not _near_first_rank_less(candidate, ranked[index]):
		index += 1
	ranked.insert(index, candidate)


static func _insert_staging_ranked(
	ranked: Array[BattleCombatCoverEvaluation],
	candidate: BattleCombatCoverEvaluation
) -> void:
	var index: int = 0
	while index < ranked.size() and not _staging_rank_less(candidate, ranked[index]):
		index += 1
	ranked.insert(index, candidate)


static func _rank_less(
	left: BattleCombatCoverEvaluation,
	right: BattleCombatCoverEvaluation,
	prefer_band: bool
) -> bool:
	if prefer_band:
		if left.in_band != right.in_band:
			return left.in_band and not right.in_band
		if not is_equal_approx(left.band_error, right.band_error):
			return left.band_error < right.band_error
	if not is_equal_approx(left.protection_factor, right.protection_factor):
		return left.protection_factor > right.protection_factor
	if not is_equal_approx(left.move_distance, right.move_distance):
		return left.move_distance < right.move_distance
	return left.slot_id < right.slot_id


static func _closing_rank_less(left: BattleCombatCoverEvaluation, right: BattleCombatCoverEvaluation) -> bool:
	if not is_equal_approx(left.protection_factor, right.protection_factor):
		return left.protection_factor > right.protection_factor
	if not is_equal_approx(left.closing_progress, right.closing_progress):
		return left.closing_progress > right.closing_progress
	if not is_equal_approx(left.move_distance, right.move_distance):
		return left.move_distance < right.move_distance
	return left.slot_id < right.slot_id


static func _near_first_rank_less(
	left: BattleCombatCoverEvaluation,
	right: BattleCombatCoverEvaluation
) -> bool:
	if not is_equal_approx(left.move_distance, right.move_distance):
		return left.move_distance < right.move_distance
	if not is_equal_approx(left.protection_factor, right.protection_factor):
		return left.protection_factor > right.protection_factor
	return left.slot_id < right.slot_id


static func _staging_rank_less(
	left: BattleCombatCoverEvaluation,
	right: BattleCombatCoverEvaluation
) -> bool:
	if not is_equal_approx(left.move_distance, right.move_distance):
		return left.move_distance < right.move_distance
	if not is_equal_approx(left.closing_progress, right.closing_progress):
		return left.closing_progress > right.closing_progress
	if not is_equal_approx(left.protection_factor, right.protection_factor):
		return left.protection_factor > right.protection_factor
	return left.slot_id < right.slot_id


static func _insert_object_cover_ranked(
	ranked: Array[BattleCombatCoverEvaluation],
	candidate: BattleCombatCoverEvaluation,
	has_threat: bool
) -> void:
	var index: int = 0
	while index < ranked.size() and not _object_cover_rank_less(candidate, ranked[index], has_threat):
		index += 1
	ranked.insert(index, candidate)


static func _object_cover_rank_less(
	left: BattleCombatCoverEvaluation,
	right: BattleCombatCoverEvaluation,
	has_threat: bool
) -> bool:
	if has_threat:
		if left.has_useful_direction != right.has_useful_direction:
			return left.has_useful_direction and not right.has_useful_direction
		if not is_equal_approx(left.protection_factor, right.protection_factor):
			return left.protection_factor > right.protection_factor
		if left.has_line_of_sight != right.has_line_of_sight:
			return left.has_line_of_sight and not right.has_line_of_sight
	if not is_equal_approx(left.move_distance, right.move_distance):
		return left.move_distance < right.move_distance
	return left.slot_id < right.slot_id


static func _living_hostile_by_id(
	battle_state: BattleState,
	participant: BattleParticipant,
	hostile_id: String
) -> BattleParticipant:
	if battle_state == null or participant == null or hostile_id.is_empty():
		return null
	if not battle_state.has_participant(hostile_id):
		return null
	var hostile: BattleParticipant = battle_state.get_participant(hostile_id)
	if hostile == null or not hostile.is_alive:
		return null
	if hostile.side_id == participant.side_id:
		return null
	if not _is_positioned(hostile):
		return null
	return hostile


static func _nearest_living_hostile(
	battle_state: BattleState,
	participant: BattleParticipant
) -> BattleParticipant:
	if battle_state == null or participant == null or not _is_positioned(participant):
		return null
	var best: BattleParticipant = null
	var best_distance: float = INF
	var ids: Array[String] = []
	for participant_id: String in battle_state.participants:
		ids.append(participant_id)
	ids.sort()
	for participant_id: String in ids:
		var hostile: BattleParticipant = _living_hostile_by_id(
			battle_state,
			participant,
			participant_id
		)
		if hostile == null:
			continue
		var distance: float = participant.battle_position.distance_squared_to(hostile.battle_position)
		if not is_finite(distance):
			continue
		if best == null or distance < best_distance:
			best = hostile
			best_distance = distance
	return best


static func _slot_is_legal_for_participant(participant: BattleParticipant, slot: BattleCoverSlot) -> bool:
	if participant == null or slot == null or not slot.is_valid():
		return false
	if slot.occupied_by_participant_id != "" and slot.occupied_by_participant_id != participant.participant_id:
		return false
	if slot.occupied_by_participant_id == participant.participant_id:
		return true
	if slot.reserved_by_participant_id != "" and slot.reserved_by_participant_id != participant.participant_id:
		return false
	return true


static func _slot_is_reachable(
	battle_state: BattleState,
	participant: BattleParticipant,
	slot: BattleCoverSlot
) -> bool:
	if participant == null or slot == null or battle_state == null:
		return false
	if not _is_positioned(participant):
		return false
	if participant.battle_position.distance_to(slot.position) <= BattleCoverService.COVER_OCCUPANCY_EPSILON:
		return true
	return BattleNavigationService.is_reachable(
		battle_state,
		participant.battle_position,
		slot.position
	)


static func _slot_is_within_weapon_max_range(
	slot: BattleCoverSlot,
	hostile: BattleParticipant,
	weapon_type_id: String
) -> bool:
	if slot == null or not slot.is_valid() or hostile == null or not _is_positioned(hostile):
		return false
	var definition: BattleWeaponDefinition = BattleWeaponCatalog.get_definition(weapon_type_id)
	if definition == null or not definition.is_valid():
		return false
	var slot_range: float = slot.position.distance_to(hostile.battle_position)
	if not is_finite(slot_range):
		return false
	return slot_range <= definition.max_range or is_equal_approx(slot_range, definition.max_range)


static func _participant_weapon_type_id(participant: BattleParticipant) -> String:
	if participant == null:
		return ""
	if participant.weapon_state != null and not participant.weapon_state.weapon_type_id.is_empty():
		return participant.weapon_state.weapon_type_id
	return participant.weapon_type


static func _is_positioned(participant: BattleParticipant) -> bool:
	if participant == null:
		return false
	if not participant.has_battle_position:
		return false
	return BattlefieldGeometry.is_finite_point(participant.battle_position)


static func _evaluate_rank_candidates(
	battle_state: BattleState,
	participant: BattleParticipant,
	hostile: BattleParticipant,
	require_reachable: bool,
	require_weapon_range: bool,
	max_move_distance: float = INF
) -> Array[BattleCombatCoverEvaluation]:
	var evaluations: Array[BattleCombatCoverEvaluation] = []
	if battle_state == null or participant == null or battle_state.battlefield_geometry == null:
		return evaluations
	var range_limit: float = INF
	if require_weapon_range:
		var definition: BattleWeaponDefinition = BattleWeaponCatalog.get_definition(_participant_weapon_type_id(participant))
		if definition == null or not definition.is_valid() or hostile == null or not _is_positioned(hostile):
			return evaluations
		range_limit = definition.max_range
	for slot_id: String in battle_state.battlefield_geometry.get_cover_slot_ids_in_radius(participant.battle_position, max_move_distance):
		var slot: BattleCoverSlot = battle_state.battlefield_geometry.get_cover_slot(slot_id)
		if require_weapon_range:
			if slot == null:
				continue
			var distance: float = slot.position.distance_to(hostile.battle_position)
			if not is_finite(distance) or (distance > range_limit and not is_equal_approx(distance,range_limit)):
				continue
		var prepared: BattleCoverProtectionResult = _rank_candidate_protection(participant,slot,hostile,max_move_distance)
		if prepared == null:
			continue
		evaluations.append(
			evaluate_slot(
				battle_state,
				participant,
				slot,
				hostile,
				require_reachable,
				require_weapon_range,
				max_move_distance,
				prepared
			)
		)
	return evaluations


# These are necessary conditions already enforced by each ranking function.
# Keep evaluate_slot/evaluate_all complete for callers inspecting rejected slots.
static func _rank_candidate_allowed(
	participant: BattleParticipant, slot: BattleCoverSlot,
	hostile: BattleParticipant, max_move_distance: float
) -> bool:
	return _rank_candidate_protection(participant,slot,hostile,max_move_distance) != null

static func _rank_candidate_protection(
	participant: BattleParticipant, slot: BattleCoverSlot,
	hostile: BattleParticipant, max_move_distance: float
) -> BattleCoverProtectionResult:
	if participant == null or slot == null or not slot.is_valid():return null
	if not _slot_is_legal_for_participant(participant,slot):return null
	if is_finite(max_move_distance):
		if not _is_positioned(participant):return null
		var distance: float = participant.battle_position.distance_to(slot.position)
		if not is_finite(distance) or (distance > max_move_distance and not is_equal_approx(distance,max_move_distance)):return null
	if hostile == null or not _is_positioned(hostile):return null
	# A slot facing away cannot meet the positive useful-cover threshold.
	# This rejects it before allocating a protection result.
	if slot.facing_direction.dot(hostile.battle_position-slot.position) < 0.0:
		return null
	var protection: BattleCoverProtectionResult = BattleCoverProtectionService.query_slot_protection(slot,hostile.battle_position)
	return protection if protection != null and protection.has_applicable_cover and is_useful_protection_factor(protection.protection_factor) else null

battle/combat/battle_combat_presentation:
class_name BattleCombatPresentationQuery
extends RefCounted

# Query-only combat presentation. Reads authoritative battle data.
# Does not mutate simulation, fire control, or combat behavior.

const BattleState := preload("res://battle/core/battle_state.gd")
const BattleParticipant := preload("res://battle/core/battle_participant.gd")
const BattleFireControlService := preload("res://battle/combat/battle_fire_control_service.gd")
const BattleFireControlResult := preload("res://battle/combat/battle_fire_control_result.gd")

const STATE_NONE := ""
const STATE_DEAD := "DEAD"
const STATE_WND := "WND"
const STATE_MOV := "MOV"
const STATE_COVER := "COVER"
const STATE_HOLD := "HOLD"
const STATE_RLD := "RLD"
const STATE_NO_LOS := "NO LOS"
const STATE_RANGE := "RANGE"
const STATE_AIM := "AIM"
const STATE_WAIT := "WAIT"

const MOVE_SEEK_COVER := "seek_cover"
const MOVE_SEEK_ROLE_COVER := "seek_role_cover"
const MOVE_CLOSE := "close"
const MOVE_DEFEND_REPOSITION := "defend_reposition"

const RELOCATING_SPEED_EPSILON := 0.05


static func compact_state(battle_state: BattleState, participant: BattleParticipant) -> String:
	if participant == null:
		return STATE_NONE
	if not participant.is_alive:
		return STATE_DEAD
	if _is_relocating(participant):
		if _is_seeking_cover(participant):
			return STATE_COVER
		return STATE_MOV
	if _is_reloading(participant):
		return STATE_RLD
	if participant.has_occupied_cover_slot():
		return STATE_HOLD
	var rejection: String = _fire_rejection(battle_state, participant)
	if rejection == "line_of_sight_blocked":
		return STATE_NO_LOS
	if rejection == "out_of_range":
		return STATE_RANGE
	if participant.has_acquire_reaction() or participant.has_sniper_aim():
		return STATE_AIM
	if participant.is_wounded:
		return STATE_WND
	if rejection == "cooldown" or _is_cooling_down(participant):
		return STATE_WAIT
	return STATE_NONE


static func _is_relocating(participant: BattleParticipant) -> bool:
	if participant == null:
		return false
	if _is_usable_vector(participant.velocity) and participant.velocity.length() > RELOCATING_SPEED_EPSILON:
		return true
	if participant.has_active_navigation_path():
		return true
	return false


static func _is_seeking_cover(participant: BattleParticipant) -> bool:
	if participant == null:
		return false
	match participant.combat_move_mode:
		MOVE_SEEK_COVER, MOVE_SEEK_ROLE_COVER, MOVE_CLOSE, MOVE_DEFEND_REPOSITION:
			return true
		_:
			return false


static func _is_reloading(participant: BattleParticipant) -> bool:
	if participant == null or participant.weapon_state == null:
		return false
	if participant.weapon_state.is_reloading:
		return true
	return participant.weapon_state.ammo_in_magazine <= 0


static func _is_cooling_down(participant: BattleParticipant) -> bool:
	if participant == null or participant.weapon_state == null:
		return false
	return participant.weapon_state.is_cooling_down()


static func _fire_rejection(battle_state: BattleState, participant: BattleParticipant) -> String:
	if battle_state == null or participant == null:
		return ""
	if battle_state.battle_phase != "active":
		return ""
	if not participant.has_target_participant or participant.target_participant_id.is_empty():
		return ""
	var result: BattleFireControlResult = BattleFireControlService.evaluate_participant_target_eligibility(
		battle_state,
		participant.participant_id,
		participant.target_participant_id
	)
	if result == null or not result.success or result.can_fire:
		return ""
	return result.rejection_code


static func _is_usable_vector(value: Vector2) -> bool:
	return is_finite(value.x) and is_finite(value.y)

battle/combat/battle_combat_pressure_beh:
class_name BattleCombatPressureBehaviorPolicy
extends RefCounted

const BattleState := preload("res://battle/core/battle_state.gd")
const BattleParticipant := preload("res://battle/core/battle_participant.gd")
const BattleCombatPressureCatalog := preload("res://battle/combat/battle_combat_pressure_catalog.gd")
const BattleCombatPressureSnapshot := preload("res://battle/combat/battle_combat_pressure_snapshot.gd")
const BattleCombatPressureService := preload("res://battle/combat/battle_combat_pressure_service.gd")
const BattleCombatPressureBehaviorPolicyResult := preload(
	"res://battle/combat/battle_combat_pressure_behavior_policy_result.gd"
)

# Pressure-to-behavior policy. Does not mutate state, consume RNG, or refresh pressure.


static func evaluate(
	battle_state: BattleState,
	participant: BattleParticipant
) -> BattleCombatPressureBehaviorPolicyResult:
	var result: BattleCombatPressureBehaviorPolicyResult = BattleCombatPressureBehaviorPolicyResult.new()
	result.suppress_aggressive_autonomous_movement = false
	if battle_state == null or participant == null:
		return result
	if not participant.is_alive:
		return result
	if participant.is_wounded:
		return result
	var snapshot: BattleCombatPressureSnapshot = BattleCombatPressureService.get_snapshot(
		battle_state,
		participant.participant_id
	)
	if snapshot == null:
		return result
	if snapshot.participant_id != participant.participant_id:
		return result
	if not is_finite(snapshot.total_pressure):
		return result
	var threshold: float = BattleCombatPressureCatalog.HIGH_PRESSURE_AGGRESSION_THRESHOLD
	if not is_finite(threshold):
		return result
	if (
		snapshot.total_pressure > threshold
		or is_equal_approx(snapshot.total_pressure, threshold)
	):
		result.suppress_aggressive_autonomous_movement = true
	return result

battle/combat/battle_combat_pressure_ser:
class_name BattleCombatPressureService
extends RefCounted

const BattleState := preload("res://battle/core/battle_state.gd")
const BattleParticipant := preload("res://battle/core/battle_participant.gd")
const BattleCombatPressureCatalog := preload("res://battle/combat/battle_combat_pressure_catalog.gd")
const BattleCombatPressureSnapshot := preload("res://battle/combat/battle_combat_pressure_snapshot.gd")
const BattleCombatPressureResult := preload("res://battle/combat/battle_combat_pressure_result.gd")

# Deterministic observational pressure. Does not mutate combat behavior or RNG.


static func refresh(battle_state: BattleState) -> BattleCombatPressureResult:
	if battle_state == null:
		return BattleCombatPressureResult.failed(
			"null_battle_state",
			"Battle combat pressure failed: battle_state is null."
		)
	var participant_ids: Array[String] = _sorted_participant_ids(battle_state)
	var candidates: Array[BattleParticipant] = _positioned_pressure_candidates(battle_state, participant_ids)
	var next_snapshots: Dictionary[String, BattleCombatPressureSnapshot] = {}
	var participants_considered: int = 0
	var snapshots_updated: int = 0
	for participant_id: String in participant_ids:
		var participant: BattleParticipant = battle_state.get_participant(participant_id)
		if participant == null:
			continue
		participants_considered += 1
		var snapshot: BattleCombatPressureSnapshot = _evaluate_participant(battle_state, participant_id, candidates)
		if snapshot == null:
			continue
		next_snapshots[participant_id] = snapshot
		snapshots_updated += 1
	battle_state.combat_pressure_snapshots = next_snapshots
	return BattleCombatPressureResult.succeeded(participants_considered, snapshots_updated)


static func evaluate_participant(
	battle_state: BattleState,
	participant_id: String
) -> BattleCombatPressureSnapshot:
	return _evaluate_participant(battle_state, participant_id, _positioned_pressure_candidates(battle_state, _sorted_participant_ids(battle_state)))


# The roster is stable during this synchronous observation pass. Validate and
# order candidates once; all positions, life/wound state and sides are live.
static func _positioned_pressure_candidates(battle_state: BattleState, ids: Array[String]) -> Array[BattleParticipant]:
	var candidates: Array[BattleParticipant] = []
	if battle_state == null:
		return candidates
	for id: String in ids:
		var candidate: BattleParticipant = battle_state.get_participant(id)
		if not _is_positioned(candidate):
			continue
		if candidate.side_id.is_empty() or not battle_state.has_side(candidate.side_id):
			continue
		candidates.append(candidate)
	return candidates


static func _evaluate_participant(
	battle_state: BattleState,
	participant_id: String,
	candidates: Array[BattleParticipant]
) -> BattleCombatPressureSnapshot:
	if battle_state == null or participant_id.is_empty():
		return null
	if not battle_state.has_participant(participant_id):
		return null
	var source: BattleParticipant = battle_state.get_participant(participant_id)
	if not _is_pressure_subject(battle_state, source):
		return null
	var nearby_dead_allies: int = 0
	var nearby_wounded_allies: int = 0
	var nearby_living_allies: int = 0
	var nearby_hostiles: int = 0
	var isolation_ally_present: bool = false
	var support_living_allies: int = 0
	var hostile_proximity_sum: float = 0.0
	var hostile_bearings: Array[Vector2] = []
	var pressure_radius: float = BattleCombatPressureCatalog.PRESSURE_RADIUS
	var isolation_radius: float = BattleCombatPressureCatalog.ISOLATION_RADIUS
	var support_radius: float = BattleCombatPressureCatalog.FRIENDLY_SUPPORT_RADIUS
	var pressure_radius_sq: float = pressure_radius * pressure_radius
	var isolation_radius_sq: float = isolation_radius * isolation_radius
	var support_radius_sq: float = support_radius * support_radius
	var pressure_usable: bool = is_finite(pressure_radius) and pressure_radius >= 0.0 and is_finite(pressure_radius_sq)
	var isolation_usable: bool = is_finite(isolation_radius) and isolation_radius >= 0.0 and is_finite(isolation_radius_sq)
	var support_usable: bool = is_finite(support_radius) and support_radius >= 0.0 and is_finite(support_radius_sq)
	for candidate: BattleParticipant in candidates:
		if candidate.participant_id == source.participant_id:
			continue
		var distance_sq: float = source.battle_position.distance_squared_to(candidate.battle_position)
		if not is_finite(distance_sq):
			continue
		var within_pressure: bool = pressure_usable and distance_sq <= pressure_radius_sq
		if source.side_id == candidate.side_id:
			if not candidate.is_alive:
				if within_pressure:
					nearby_dead_allies += 1
				continue
			if within_pressure:
				nearby_living_allies += 1
				if candidate.is_wounded:
					nearby_wounded_allies += 1
			if isolation_usable and distance_sq <= isolation_radius_sq:
				isolation_ally_present = true
			if support_usable and distance_sq <= support_radius_sq:
				support_living_allies += 1
			continue
		if not candidate.is_alive or not within_pressure:
			continue
		nearby_hostiles += 1
		var distance: float = source.battle_position.distance_to(candidate.battle_position)
		if is_finite(distance) and is_finite(pressure_radius) and pressure_radius > 0.0:
			var proximity: float = 1.0 - (distance / pressure_radius)
			hostile_proximity_sum += _clamp_unit(proximity)
		var offset: Vector2 = candidate.battle_position - source.battle_position
		if _is_finite_vector(offset) and not offset.is_equal_approx(Vector2.ZERO):
			var bearing: Vector2 = offset.normalized()
			if _is_finite_vector(bearing) and not bearing.is_equal_approx(Vector2.ZERO):
				hostile_bearings.append(bearing)
	var casualty_pressure: float = _normalized_count(
		nearby_dead_allies,
		BattleCombatPressureCatalog.CASUALTY_COUNT_NORMALIZE
	)
	var wounded_pressure: float = _normalized_count(
		nearby_wounded_allies,
		BattleCombatPressureCatalog.WOUNDED_COUNT_NORMALIZE
	)
	var hostile_pressure: float = _normalized_sum(
		hostile_proximity_sum,
		BattleCombatPressureCatalog.HOSTILE_PROXIMITY_NORMALIZE
	)
	var isolation_pressure: float = 0.0
	if not isolation_ally_present:
		isolation_pressure = 1.0
	var multi_direction_pressure: float = 0.0
	if _has_multi_direction_threat(hostile_bearings):
		multi_direction_pressure = 1.0
	var friendly_support: float = _normalized_count(
		support_living_allies,
		BattleCombatPressureCatalog.FRIENDLY_SUPPORT_COUNT_NORMALIZE
	)
	var total_pressure: float = (
		casualty_pressure * BattleCombatPressureCatalog.CASUALTY_WEIGHT
		+ wounded_pressure * BattleCombatPressureCatalog.WOUNDED_WEIGHT
		+ hostile_pressure * BattleCombatPressureCatalog.HOSTILE_PROXIMITY_WEIGHT
		+ isolation_pressure * BattleCombatPressureCatalog.ISOLATION_WEIGHT
		+ multi_direction_pressure * BattleCombatPressureCatalog.MULTI_DIRECTION_WEIGHT
		- friendly_support * BattleCombatPressureCatalog.FRIENDLY_SUPPORT_MITIGATION
	)
	var snapshot: BattleCombatPressureSnapshot = BattleCombatPressureSnapshot.new()
	snapshot.participant_id = source.participant_id
	snapshot.nearby_dead_allies = nearby_dead_allies
	snapshot.nearby_wounded_allies = nearby_wounded_allies
	snapshot.nearby_living_allies = nearby_living_allies
	snapshot.nearby_hostiles = nearby_hostiles
	snapshot.casualty_pressure = casualty_pressure
	snapshot.wounded_pressure = wounded_pressure
	snapshot.hostile_pressure = hostile_pressure
	snapshot.isolation_pressure = isolation_pressure
	snapshot.multi_direction_pressure = multi_direction_pressure
	snapshot.friendly_support = friendly_support
	snapshot.total_pressure = _clamp_unit(total_pressure)
	return snapshot


static func get_snapshot(
	battle_state: BattleState,
	participant_id: String
) -> BattleCombatPressureSnapshot:
	if battle_state == null or participant_id.is_empty():
		return null
	return battle_state.get_combat_pressure_snapshot(participant_id)


static func get_total_pressure(battle_state: BattleState, participant_id: String) -> float:
	var snapshot: BattleCombatPressureSnapshot = get_snapshot(battle_state, participant_id)
	if snapshot == null:
		return 0.0
	if not is_finite(snapshot.total_pressure):
		return 0.0
	return _clamp_unit(snapshot.total_pressure)


static func _sorted_participant_ids(battle_state: BattleState) -> Array[String]:
	var ids: Array[String] = []
	if battle_state == null:
		return ids
	for participant_id: String in battle_state.participants:
		ids.append(participant_id)
	ids.sort()
	return ids


static func _is_pressure_subject(battle_state: BattleState, participant: BattleParticipant) -> bool:
	if participant == null:
		return false
	if not participant.is_alive:
		return false
	if not _is_positioned(participant):
		return false
	if participant.side_id.is_empty():
		return false
	if battle_state == null or not battle_state.has_side(participant.side_id):
		return false
	return true


static func _is_positioned(participant: BattleParticipant) -> bool:
	if participant == null:
		return false
	if not participant.has_battle_position:
		return false
	return _is_finite_vector(participant.battle_position)


static func _is_finite_vector(value: Vector2) -> bool:
	return is_finite(value.x) and is_finite(value.y)


static func _are_tactical_allies(
	battle_state: BattleState,
	left: BattleParticipant,
	right: BattleParticipant
) -> bool:
	if left == null or right == null:
		return false
	if left.side_id.is_empty() or right.side_id.is_empty():
		return false
	if battle_state == null:
		return false
	if not battle_state.has_side(left.side_id) or not battle_state.has_side(right.side_id):
		return false
	return left.side_id == right.side_id


static func _are_tactical_hostiles(
	battle_state: BattleState,
	left: BattleParticipant,
	right: BattleParticipant
) -> bool:
	if left == null or right == null:
		return false
	if left.side_id.is_empty() or right.side_id.is_empty():
		return false
	if battle_state == null:
		return false
	if not battle_state.has_side(left.side_id) or not battle_state.has_side(right.side_id):
		return false
	return left.side_id != right.side_id


static func _is_within_radius(from_position: Vector2, to_position: Vector2, radius: float) -> bool:
	if not _is_finite_vector(from_position) or not _is_finite_vector(to_position):
		return false
	if not is_finite(radius) or radius < 0.0:
		return false
	var distance_sq: float = from_position.distance_squared_to(to_position)
	if not is_finite(distance_sq):
		return false
	var radius_sq: float = radius * radius
	if not is_finite(radius_sq):
		return false
	return distance_sq <= radius_sq


static func _normalized_count(count: int, divisor: float) -> float:
	if count <= 0:
		return 0.0
	if not is_finite(divisor) or divisor <= 0.0:
		return 0.0
	return _clamp_unit(float(count) / divisor)


static func _normalized_sum(sum_value: float, divisor: float) -> float:
	if not is_finite(sum_value) or sum_value <= 0.0:
		return 0.0
	if not is_finite(divisor) or divisor <= 0.0:
		return 0.0
	return _clamp_unit(sum_value / divisor)


static func _has_multi_direction_threat(bearings: Array[Vector2]) -> bool:
	if bearings.size() < 2:
		return false
	for i: int in range(bearings.size()):
		var left: Vector2 = bearings[i]
		for j: int in range(i + 1, bearings.size()):
			var right: Vector2 = bearings[j]
			var alignment: float = left.dot(right)
			if not is_finite(alignment):
				continue
			if alignment <= 0.0 or is_equal_approx(alignment, 0.0):
				return true
	return false


static func _clamp_unit(value: float) -> float:
	if not is_finite(value):
		return 0.0
	return clampf(value, 0.0, 1.0)

battle/combat/battle_cover_combat_effect:
class_name BattleCoverCombatEffectService
extends RefCounted

const BattleCombatBehaviorCatalog := preload("res://battle/combat/battle_combat_behavior_catalog.gd")
const BattleCoverCombatEffectResult := preload("res://battle/combat/battle_cover_combat_effect_result.gd")

# Deterministic pre-cover → post-cover resolution-roll transform.
# cover_multiplier = 1.0 - (MAX_COVER_ROLL_REDUCTION * protection_factor)
# post_cover_roll = pre_cover_roll * cover_multiplier
# Does not draw RNG, mutate state, or decide fire eligibility.


static func apply(pre_cover_roll: float, protection_factor: float) -> BattleCoverCombatEffectResult:
	var result: BattleCoverCombatEffectResult = BattleCoverCombatEffectResult.new()
	var factor: float = 0.0
	if is_finite(protection_factor):
		factor = clampf(protection_factor, 0.0, 1.0)
	var reduction: float = BattleCombatBehaviorCatalog.MAX_COVER_ROLL_REDUCTION
	if not is_finite(reduction) or reduction < 0.0:
		reduction = 0.0
	else:
		reduction = clampf(reduction, 0.0, 1.0)
	var multiplier: float = 1.0 - (reduction * factor)
	if not is_finite(multiplier):
		multiplier = 1.0
	else:
		multiplier = clampf(multiplier, 0.0, 1.0)
	var post_cover_roll: float = pre_cover_roll
	if is_finite(pre_cover_roll):
		post_cover_roll = pre_cover_roll * multiplier
		if not is_finite(post_cover_roll):
			post_cover_roll = pre_cover_roll
	result.pre_cover_roll = pre_cover_roll
	result.protection_factor = factor
	result.cover_multiplier = multiplier
	result.post_cover_roll = post_cover_roll
	return result

battle/combat/battle_cover_posture_servi:
class_name BattleCoverPostureService
extends RefCounted

# Battle-local occupied-cover posture. Combat authority, not presentation.
# Geometry LOS stays geometry LOS. Tucked protection is a fire-eligibility rule
# against the target's currently occupied cover slot and this shooter's direction.

const BattleState := preload("res://battle/core/battle_state.gd")
const BattleParticipant := preload("res://battle/core/battle_participant.gd")
const BattlefieldGeometry := preload("res://battle/geometry/battlefield_geometry.gd")
const BattleCoverSlot := preload("res://battle/geometry/battle_cover_slot.gd")
const BattleCoverProtectionService := preload("res://battle/geometry/battle_cover_protection_service.gd")
const BattleCoverProtectionResult := preload("res://battle/geometry/battle_cover_protection_result.gd")
const BattleFireControlService := preload("res://battle/combat/battle_fire_control_service.gd")
const BattleCombatBehaviorCatalog := preload("res://battle/combat/battle_combat_behavior_catalog.gd")

const POSTURE_NONE := "none"
const POSTURE_TUCKED := "tucked"
const POSTURE_EXPOSED := "exposed"

const PHASE_IDLE := ""
const PHASE_EXPOSING := "exposing"
const PHASE_HOLDING := "holding"
const PHASE_TUCKING := "tucking"


static func clear(participant: BattleParticipant) -> void:
	if participant == null:
		return
	participant.cover_posture = POSTURE_NONE
	participant.cover_posture_phase = PHASE_IDLE
	participant.cover_posture_timer_seconds = 0.0


static func enter_tucked(participant: BattleParticipant) -> void:
	if participant == null:
		return
	participant.cover_posture = POSTURE_TUCKED
	participant.cover_posture_phase = PHASE_IDLE
	participant.cover_posture_timer_seconds = 0.0


static func ensure_occupied_posture(participant: BattleParticipant) -> void:
	if participant == null:
		return
	if participant.cover_posture == POSTURE_TUCKED or participant.cover_posture == POSTURE_EXPOSED:
		return
	enter_tucked(participant)


static func force_exposed(participant: BattleParticipant) -> void:
	if participant == null:
		return
	participant.cover_posture = POSTURE_EXPOSED
	participant.cover_posture_phase = PHASE_HOLDING
	participant.cover_posture_timer_seconds = BattleCombatBehaviorCatalog.COVER_EXPOSED_WINDOW_SECONDS


static func is_tucked(participant: BattleParticipant) -> bool:
	return participant != null and participant.cover_posture == POSTURE_TUCKED


static func is_exposed(participant: BattleParticipant) -> bool:
	return participant != null and participant.cover_posture == POSTURE_EXPOSED


static func is_source_blocked_by_tuck(participant: BattleParticipant) -> bool:
	return is_tucked(participant)


static func is_target_tucked_protected(
	battle_state: BattleState,
	source: BattleParticipant,
	target: BattleParticipant
) -> bool:
	if battle_state == null or source == null or target == null:
		return false
	if not is_tucked(target):
		return false
	if battle_state.battlefield_geometry == null:
		return false
	if not source.has_battle_position:
		return false
	var protection: BattleCoverProtectionResult = BattleCoverProtectionService.query_protection(
		battle_state.battlefield_geometry,
		target,
		source.battle_position
	)
	if protection == null or not protection.has_applicable_cover:
		return false
	if not is_finite(protection.protection_factor):
		return false
	return (
		protection.protection_factor
		>= BattleCombatBehaviorCatalog.COVER_TUCKED_SHOT_BLOCK_FACTOR
	)


static func update_for_combat(
	battle_state: BattleState,
	participant: BattleParticipant,
	delta_seconds: float,
	allow_begin_expose: bool
) -> void:
	if participant == null:
		return
	if not participant.is_alive or not BattleCoverService.occupancy_is_valid(battle_state, participant):
		clear(participant)
		return
	ensure_occupied_posture(participant)
	if allow_begin_expose:
		_begin_expose_if_needed(battle_state, participant)
	_advance_timers(participant, delta_seconds)


static func _begin_expose_if_needed(
	battle_state: BattleState,
	participant: BattleParticipant
) -> void:
	if participant == null:
		return
	if participant.cover_posture != POSTURE_TUCKED:
		return
	if participant.cover_posture_phase != PHASE_IDLE:
		return
	if participant.has_acquire_reaction() or participant.has_sniper_aim():
		return
	if not participant.has_target_participant or participant.target_participant_id.is_empty():
		return
	# Readiness to peek differs from permission to shoot. A hidden opponent
	# must not make both sides wait forever for the other to expose first.
	var opportunity = BattleFireControlService.evaluate_participant_target_eligibility(
		battle_state, participant.participant_id, participant.target_participant_id, true
	)
	if opportunity == null or not opportunity.success:
		return
	if not opportunity.can_fire and opportunity.rejection_code != "target_tucked_protected":
		return
	participant.cover_posture = POSTURE_TUCKED
	participant.cover_posture_phase = PHASE_EXPOSING
	participant.cover_posture_timer_seconds = BattleCombatBehaviorCatalog.COVER_TUCK_TO_EXPOSE_SECONDS


static func _advance_timers(participant: BattleParticipant, delta_seconds: float) -> void:
	if participant == null:
		return
	if not is_finite(participant.cover_posture_timer_seconds):
		participant.cover_posture_timer_seconds = 0.0
	if not is_finite(delta_seconds) or delta_seconds <= 0.0:
		return
	if participant.cover_posture_phase == PHASE_IDLE:
		return
	participant.cover_posture_timer_seconds = maxf(
		participant.cover_posture_timer_seconds - delta_seconds,
		0.0
	)
	if participant.cover_posture_timer_seconds > 0.0:
		return
	match participant.cover_posture_phase:
		PHASE_EXPOSING:
			participant.cover_posture = POSTURE_EXPOSED
			participant.cover_posture_phase = PHASE_HOLDING
			participant.cover_posture_timer_seconds = (
				BattleCombatBehaviorCatalog.COVER_EXPOSED_WINDOW_SECONDS
			)
		PHASE_HOLDING:
			participant.cover_posture = POSTURE_TUCKED
			participant.cover_posture_phase = PHASE_TUCKING
			participant.cover_posture_timer_seconds = (
				BattleCombatBehaviorCatalog.COVER_EXPOSE_TO_TUCK_SECONDS
			)
		PHASE_TUCKING:
			enter_tucked(participant)
		_:
			enter_tucked(participant)

battle/combat/battle_defend_position_ser:
class_name BattleDefendPositionService
extends RefCounted

# Query-only local Defend Position search. Behavior owns reservation and navigation.
# Reuses BattleCombatCoverEvaluationService ranking. Does not chase.

const BattleState := preload("res://battle/core/battle_state.gd")
const BattleParticipant := preload("res://battle/core/battle_participant.gd")
const BattlefieldGeometry := preload("res://battle/geometry/battlefield_geometry.gd")
const BattleObstacle := preload("res://battle/geometry/battle_obstacle.gd")
const BattleCoverSlot := preload("res://battle/geometry/battle_cover_slot.gd")
const BattleCoverService := preload("res://battle/geometry/battle_cover_service.gd")
const BattleLineOfSightService := preload("res://battle/combat/battle_line_of_sight_service.gd")
const BattleLineOfSightResult := preload("res://battle/combat/battle_line_of_sight_result.gd")
const BattleNavigationService := preload("res://battle/navigation/battle_navigation_service.gd")
const BattleNavigationResult := preload("res://battle/navigation/battle_navigation_result.gd")
const BattleCombatCoverEvaluation := preload("res://battle/combat/battle_combat_cover_evaluation.gd")
const BattleCombatCoverEvaluationService := preload(
	"res://battle/combat/battle_combat_cover_evaluation_service.gd"
)
const BattleCombatBehaviorCatalog := preload("res://battle/combat/battle_combat_behavior_catalog.gd")
const BattleWeaponCatalog := preload("res://battle/combat/battle_weapon_catalog.gd")
const BattleWeaponDefinition := preload("res://battle/combat/battle_weapon_definition.gd")


static func defend_anchor(participant: BattleParticipant) -> Vector2:
	if participant == null:
		return Vector2.INF
	if participant.has_defend_position_anchor and BattlefieldGeometry.is_finite_point(
		participant.defend_position_anchor
	):
		return participant.defend_position_anchor
	if participant.has_battle_position and BattlefieldGeometry.is_finite_point(participant.battle_position):
		return participant.battle_position
	return Vector2.INF


static func is_within_defend_radius(origin: Vector2, point: Vector2) -> bool:
	if not BattlefieldGeometry.is_finite_point(origin) or not BattlefieldGeometry.is_finite_point(point):
		return false
	var distance: float = origin.distance_to(point)
	if not is_finite(distance):
		return false
	var radius: float = BattleCombatBehaviorCatalog.DEFEND_POSITION_RADIUS
	return distance < radius or is_equal_approx(distance, radius)


static func select_best_local_cover_slot(
	battle_state: BattleState,
	participant: BattleParticipant,
	hostile: BattleParticipant
) -> BattleCoverSlot:
	var origin: Vector2 = defend_anchor(participant)
	if not BattlefieldGeometry.is_finite_point(origin):
		return null
	# If even the nearest point in the allowed radius cannot reach the target,
	# the existing range-filtered cover search is necessarily empty.
	if hostile != null and _is_positioned(hostile):
		var weapon: BattleWeaponDefinition = BattleWeaponCatalog.for_participant(participant)
		if weapon != null and weapon.is_valid() and participant.battle_position.distance_to(hostile.battle_position) > weapon.max_range:
			var minimum_range: float = origin.distance_to(hostile.battle_position) - BattleCombatBehaviorCatalog.DEFEND_POSITION_RADIUS
			if minimum_range > weapon.max_range and not is_equal_approx(minimum_range, weapon.max_range):
				return null
	var ranked: Array[BattleCombatCoverEvaluation] = (
		BattleCombatCoverEvaluationService.rank_combat_usable_within_radius(
			battle_state,
			participant,
			hostile,
			true,
			origin,
			BattleCombatBehaviorCatalog.DEFEND_POSITION_RADIUS
		)
	)
	if ranked.is_empty():
		ranked = BattleCombatCoverEvaluationService.rank_combat_usable_within_radius(
			battle_state,
			participant,
			hostile,
			false,
			origin,
			BattleCombatBehaviorCatalog.DEFEND_POSITION_RADIUS
		)
	if hostile != null:
		var weapon = BattleWeaponCatalog.for_participant(participant)
		var current_range: float = participant.battle_position.distance_to(hostile.battle_position)
		if weapon != null and current_range > weapon.max_range:
			ranked = ranked.filter(func(e): return battle_state.battlefield_geometry.get_cover_slot(e.slot_id).position.distance_to(hostile.battle_position) <= weapon.max_range)
	return BattleCombatCoverEvaluationService.first_reachable_ranked_slot(
		battle_state,
		participant,
		ranked,
		true
	)


static func select_best_local_los_point(
	battle_state: BattleState,
	participant: BattleParticipant,
	hostile: BattleParticipant
) -> Vector2:
	if participant == null or hostile == null or not _is_positioned(participant) or not _is_positioned(hostile):
		return Vector2.INF
	var origin: Vector2 = defend_anchor(participant)
	if not BattlefieldGeometry.is_finite_point(origin):
		return Vector2.INF
	var candidates: Array[Dictionary] = []
	var order := 0
	var radii: Array[float] = _sample_radii()
	var directions: int = BattleCombatBehaviorCatalog.DEFEND_POSITION_SAMPLE_DIRECTIONS
	for radius: float in radii:
		var dir := 0
		while dir < directions:
			order += 1
			var angle: float = (float(dir) * TAU) / float(directions)
			var point: Vector2 = origin + Vector2.from_angle(angle) * radius
			dir += 1
			if not _sample_is_legal(battle_state, participant, hostile, origin, point, false):
				continue
			var move_distance: float = participant.battle_position.distance_to(point)
			var anchor_distance: float = point.distance_to(origin)
			if not is_finite(move_distance) or not is_finite(anchor_distance):
				continue
			candidates.append({
				"point": point,
				"move": move_distance,
				"anchor": anchor_distance,
				"order": order,
			})
	candidates.sort_custom(_compare_defend_samples)
	var best: Vector2 = Vector2.INF
	for candidate: Dictionary in candidates:
		var point: Vector2 = candidate["point"]
		if participant.battle_position.distance_to(point) <= BattleCoverService.COVER_OCCUPANCY_EPSILON:
			best = point
			break
		if BattleNavigationService.is_reachable(battle_state, participant.battle_position, point):
			best = point
			break
	return best


static func destination_still_valid(
	battle_state: BattleState,
	participant: BattleParticipant,
	hostile: BattleParticipant,
	destination: Vector2,
	require_reachable: bool = true
) -> bool:
	if participant == null or not _is_positioned(participant):
		return false
	var origin: Vector2 = defend_anchor(participant)
	return _sample_is_legal(
		battle_state,
		participant,
		hostile,
		origin,
		destination,
		require_reachable
	)


static func _sample_radii() -> Array[float]:
	var radii: Array[float] = [
		BattleCombatBehaviorCatalog.DEFEND_POSITION_SAMPLE_RADIUS_A,
		BattleCombatBehaviorCatalog.DEFEND_POSITION_SAMPLE_RADIUS_B,
		BattleCombatBehaviorCatalog.DEFEND_POSITION_SAMPLE_RADIUS_C,
		BattleCombatBehaviorCatalog.DEFEND_POSITION_SAMPLE_RADIUS_D,
	]
	return radii


static func _compare_defend_samples(left: Dictionary, right: Dictionary) -> bool:
	return _sample_ranks_better(
		float(left.get("move", INF)),
		float(left.get("anchor", INF)),
		int(left.get("order", 2147483647)),
		float(right.get("move", INF)),
		float(right.get("anchor", INF)),
		int(right.get("order", 2147483647))
	)


static func _sample_ranks_better(
	move_distance: float,
	anchor_distance: float,
	order: int,
	best_move: float,
	best_anchor: float,
	best_order: int
) -> bool:
	if not is_equal_approx(move_distance, best_move):
		return move_distance < best_move
	if not is_equal_approx(anchor_distance, best_anchor):
		return anchor_distance < best_anchor
	return order < best_order


static func _sample_is_legal(
	battle_state: BattleState,
	participant: BattleParticipant,
	hostile: BattleParticipant,
	origin: Vector2,
	point: Vector2,
	require_reachable: bool = true
) -> bool:
	if not BattlefieldGeometry.is_finite_point(point):
		return false
	if participant != null and point.is_equal_approx(participant.battle_position):
		return false
	if not is_within_defend_radius(origin, point):
		return false
	if not _point_is_in_weapon_max_range(participant, point, hostile):
		return false
	if not _is_valid_destination(battle_state, point):
		return false
	if not _point_has_los_to_hostile(battle_state, point, hostile):
		return false
	if participant == null or not _is_positioned(participant):
		return false
	if participant.battle_position.distance_to(point) <= BattleCoverService.COVER_OCCUPANCY_EPSILON:
		return true
	if not require_reachable:
		return true
	return BattleNavigationService.is_reachable(
		battle_state,
		participant.battle_position,
		point
	)


static func _point_has_los_to_hostile(
	battle_state: BattleState,
	point: Vector2,
	hostile: BattleParticipant
) -> bool:
	if hostile == null or not _is_positioned(hostile):
		return false
	var los: BattleLineOfSightResult = BattleLineOfSightService.check_segment(
		battle_state,
		point,
		hostile.battle_position
	)
	return los != null and los.success and los.has_line_of_sight


static func _point_is_in_weapon_max_range(
	participant: BattleParticipant,
	point: Vector2,
	hostile: BattleParticipant
) -> bool:
	if participant == null or hostile == null or not _is_positioned(hostile):
		return false
	if not BattlefieldGeometry.is_finite_point(point):
		return false
	var weapon_type_id: String = participant.weapon_type
	if participant.weapon_state != null and not participant.weapon_state.weapon_type_id.is_empty():
		weapon_type_id = participant.weapon_state.weapon_type_id
	var definition: BattleWeaponDefinition = BattleWeaponCatalog.for_participant(participant)
	if definition == null or not definition.is_valid():
		return false
	var distance: float = point.distance_to(hostile.battle_position)
	if not is_finite(distance):
		return false
	return distance < definition.max_range or is_equal_approx(distance, definition.max_range)


static func _is_valid_destination(battle_state: BattleState, point: Vector2) -> bool:
	if battle_state == null or battle_state.battlefield_geometry == null:
		return false
	if not BattlefieldGeometry.is_finite_point(point):
		return false
	var geometry: BattlefieldGeometry = battle_state.battlefield_geometry
	if not geometry.contains_point(point):
		return false
	for obstacle_id: String in geometry.get_obstacle_ids_at_point(point):
		var obstacle: BattleObstacle = geometry.get_obstacle(obstacle_id)
		if obstacle == null or not obstacle.blocks_movement:
			continue
		if obstacle.contains_point(point):
			return false
	return true


static func _is_positioned(participant: BattleParticipant) -> bool:
	if participant == null:
		return false
	if not participant.has_battle_position:
		return false
	return BattlefieldGeometry.is_finite_point(participant.battle_position)

battle/combat/battle_fire_control_servic:
class_name BattleFireControlService
extends RefCounted

const BattleState := preload("res://battle/core/battle_state.gd")
const BattleParticipant := preload("res://battle/core/battle_participant.gd")
const BattleWeaponCatalog := preload("res://battle/combat/battle_weapon_catalog.gd")
const BattleWeaponDefinition := preload("res://battle/combat/battle_weapon_definition.gd")
const BattleWeaponState := preload("res://battle/combat/battle_weapon_state.gd")
const BattleFireControlResult := preload("res://battle/combat/battle_fire_control_result.gd")
const BattleLineOfSightService := preload("res://battle/combat/battle_line_of_sight_service.gd")
const BattleLineOfSightResult := preload("res://battle/combat/battle_line_of_sight_result.gd")
const BattleCoverProtectionService := preload("res://battle/geometry/battle_cover_protection_service.gd")
const BattleCoverProtectionResult := preload("res://battle/geometry/battle_cover_protection_result.gd")
const BattleCombatBehaviorCatalog := preload("res://battle/combat/battle_combat_behavior_catalog.gd")


static func initialize_weapon_state(participant: BattleParticipant) -> bool:
	if participant == null:
		return false
	var state: BattleWeaponState = BattleWeaponCatalog.state_for_participant(participant)
	participant.weapon_state = state
	return state != null


static func advance_weapon_state(
	battle_state: BattleState,
	delta_seconds: float
) -> BattleFireControlResult:
	if battle_state == null:
		return BattleFireControlResult.failed(
			"null_battle_state",
			"Battle fire control failed: battle_state is null."
		)
	if battle_state.battle_phase != "active":
		return BattleFireControlResult.failed(
			"battle_not_active",
			"Battle fire control failed: battle phase is '%s', not active." % battle_state.battle_phase
		)
	if not is_finite(delta_seconds) or delta_seconds < 0.0:
		return BattleFireControlResult.failed(
			"invalid_delta",
			"Battle fire control failed: delta_seconds is invalid."
		)
	if battle_state.battlefield_geometry == null:
		return BattleFireControlResult.failed(
			"missing_battlefield_geometry",
			"Battle fire control failed: battlefield geometry is missing."
		)
	if not battle_state.has_valid_geometry():
		return BattleFireControlResult.failed(
			"invalid_battlefield_geometry",
			"Battle fire control failed: battlefield geometry is invalid."
		)
	var participant_ids: Array[String] = _sorted_participant_ids(battle_state)
	var participants_considered: int = 0
	for participant_id: String in participant_ids:
		var participant: BattleParticipant = battle_state.get_participant(participant_id)
		if participant == null:
			continue
		participants_considered += 1
		if delta_seconds > 0.0:
			_advance_participant_weapon(participant, delta_seconds)
			_advance_wound_reaction(participant, delta_seconds)
			_advance_acquire_reaction(participant, delta_seconds)
			_advance_sniper_aim(participant, delta_seconds)
	return BattleFireControlResult.succeeded(participants_considered)


static func evaluate_fire_eligibility(battle_state: BattleState) -> BattleFireControlResult:
	if battle_state == null:
		return BattleFireControlResult.failed(
			"null_battle_state",
			"Battle fire control failed: battle_state is null."
		)
	if battle_state.battle_phase != "active":
		return BattleFireControlResult.failed(
			"battle_not_active",
			"Battle fire control failed: battle phase is '%s', not active." % battle_state.battle_phase
		)
	if battle_state.battlefield_geometry == null:
		return BattleFireControlResult.failed(
			"missing_battlefield_geometry",
			"Battle fire control failed: battlefield geometry is missing."
		)
	if not battle_state.has_valid_geometry():
		return BattleFireControlResult.failed(
			"invalid_battlefield_geometry",
			"Battle fire control failed: battlefield geometry is invalid."
		)
	var participant_ids: Array[String] = _sorted_participant_ids(battle_state)
	var participants_considered: int = 0
	var participants_with_targets: int = 0
	var participants_eligible_to_fire: int = 0
	var participants_blocked_by_los: int = 0
	var participants_blocked_by_range: int = 0
	var participants_blocked_by_cooldown: int = 0
	var participants_reloading: int = 0
	var participants_empty: int = 0
	for participant_id: String in participant_ids:
		var participant: BattleParticipant = battle_state.get_participant(participant_id)
		if participant == null:
			continue
		participants_considered += 1
		if participant.has_target_participant:
			participants_with_targets += 1
		var block_reason: String = _fire_block_reason(battle_state, participant)
		match block_reason:
			"":
				participants_eligible_to_fire += 1
			"reloading":
				participants_reloading += 1
			"empty":
				participants_empty += 1
			"cooldown":
				participants_blocked_by_cooldown += 1
			"range":
				participants_blocked_by_range += 1
			"los":
				participants_blocked_by_los += 1
			_:
				pass
	return BattleFireControlResult.succeeded(
		participants_considered,
		participants_with_targets,
		participants_eligible_to_fire,
		participants_blocked_by_los,
		participants_blocked_by_range,
		participants_blocked_by_cooldown,
		participants_reloading,
		participants_empty
	)


static func evaluate_participant_target_eligibility(
	battle_state: BattleState,
	source_participant_id: String,
	target_participant_id: String,
	ignore_source_cover_posture: bool = false
) -> BattleFireControlResult:
	if battle_state == null:
		return BattleFireControlResult.failed(
			"null_battle_state",
			"Battle fire control failed: battle_state is null."
		)
	if battle_state.battle_phase != "active":
		return BattleFireControlResult.failed(
			"battle_not_active",
			"Battle fire control failed: battle phase is '%s', not active." % battle_state.battle_phase
		)
	if battle_state.battlefield_geometry == null:
		return BattleFireControlResult.failed(
			"missing_battlefield_geometry",
			"Battle fire control failed: battlefield geometry is missing."
		)
	if not battle_state.has_valid_geometry():
		return BattleFireControlResult.failed(
			"invalid_battlefield_geometry",
			"Battle fire control failed: battlefield geometry is invalid."
		)
	if source_participant_id.is_empty() or not battle_state.has_participant(source_participant_id):
		return BattleFireControlResult.pair_rejected(
			"source_not_found",
			source_participant_id,
			target_participant_id
		)
	if target_participant_id.is_empty() or not battle_state.has_participant(target_participant_id):
		return BattleFireControlResult.pair_rejected(
			"target_not_found",
			source_participant_id,
			target_participant_id
		)
	var source: BattleParticipant = battle_state.get_participant(source_participant_id)
	var target: BattleParticipant = battle_state.get_participant(target_participant_id)
	var rejection_code: String = _pair_rejection_code(
		battle_state,
		source,
		target,
		ignore_source_cover_posture
	)
	if rejection_code.is_empty():
		return BattleFireControlResult.pair_eligible(source_participant_id, target_participant_id)
	return BattleFireControlResult.pair_rejected(
		rejection_code,
		source_participant_id,
		target_participant_id
	)


static func would_fire_if_source_cover_exposed(
	battle_state: BattleState,
	source_participant_id: String,
	target_participant_id: String
) -> bool:
	var eligibility: BattleFireControlResult = evaluate_participant_target_eligibility(
		battle_state,
		source_participant_id,
		target_participant_id,
		true
	)
	return eligibility != null and eligibility.success and eligibility.can_fire


# Explicit shot commit for a future attack-resolution layer.
# Runtime does not call this. It does not query LOS, range, or targets.
# fire_rate_multiplier scales shots/sec. Healthy shots pass 1.0 and keep base cadence.
static func commit_shot(
	participant: BattleParticipant,
	definition: BattleWeaponDefinition,
	fire_rate_multiplier: float = 1.0
) -> bool:
	if participant == null or definition == null:
		return false
	if not definition.is_valid():
		return false
	var state: BattleWeaponState = participant.weapon_state
	if state == null:
		return false
	if state.weapon_type_id != definition.weapon_type_id:
		return false
	if state.is_reloading:
		return false
	if state.ammo_in_magazine <= 0:
		return false
	if not is_finite(state.cooldown_remaining_seconds) or state.cooldown_remaining_seconds > 0.0:
		return false
	var cooldown_seconds: float = effective_cooldown_seconds(definition, fire_rate_multiplier)
	if not is_finite(cooldown_seconds) or cooldown_seconds < 0.0:
		return false
	state.last_fired_hand = state.next_firing_hand if not participant.specialist_id.is_empty() and not participant.is_wounded else 0
	if not participant.specialist_id.is_empty(): state.next_firing_hand = 1 - state.last_fired_hand
	state.ammo_in_magazine -= 1
	state.cooldown_remaining_seconds = cooldown_seconds
	return true


static func effective_cooldown_seconds(
	definition: BattleWeaponDefinition,
	fire_rate_multiplier: float = 1.0
) -> float:
	if definition == null or not definition.is_valid():
		return INF
	if not is_finite(fire_rate_multiplier) or fire_rate_multiplier <= 0.0:
		return INF
	return definition.cooldown_seconds() / fire_rate_multiplier


static func _advance_participant_weapon(
	participant: BattleParticipant,
	delta_seconds: float
) -> void:
	var state: BattleWeaponState = participant.weapon_state
	if state == null:
		return
	var equipped: BattleWeaponDefinition = BattleWeaponCatalog.for_participant(participant)
	if equipped != null: participant.weapon_recoil = maxf(0.0, participant.weapon_recoil - equipped.recoil_recovery * delta_seconds)
	if state.ammo_in_magazine < 0:
		state.ammo_in_magazine = 0
	if not is_finite(state.cooldown_remaining_seconds) or not is_finite(state.reload_remaining_seconds):
		return
	if state.cooldown_remaining_seconds < 0.0:
		state.cooldown_remaining_seconds = 0.0
	if state.reload_remaining_seconds < 0.0:
		state.reload_remaining_seconds = 0.0
	var definition: BattleWeaponDefinition = equipped
	if definition != null and state.ammo_in_magazine == 0 and not state.is_reloading:
		_start_reload(state, definition)
	if state.is_reloading:
		state.reload_remaining_seconds = maxf(state.reload_remaining_seconds - delta_seconds, 0.0)
		if state.reload_remaining_seconds == 0.0:
			state.is_reloading = false
			_refill_magazine_to_capacity(state, definition)
	state.cooldown_remaining_seconds = maxf(state.cooldown_remaining_seconds - delta_seconds, 0.0)


static func _advance_wound_reaction(participant: BattleParticipant, delta_seconds: float) -> void:
	if participant == null:
		return
	if not is_finite(participant.wound_reaction_remaining_seconds):
		participant.wound_reaction_remaining_seconds = 0.0
		return
	if participant.wound_reaction_remaining_seconds <= 0.0:
		participant.wound_reaction_remaining_seconds = 0.0
		return
	participant.wound_reaction_remaining_seconds = maxf(
		participant.wound_reaction_remaining_seconds - delta_seconds,
		0.0
	)


static func _start_reload(state: BattleWeaponState, definition: BattleWeaponDefinition) -> void:
	if state == null or definition == null:
		return
	if definition.reload_seconds == 0.0:
		_refill_magazine_to_capacity(state, definition)
		state.is_reloading = false
		state.reload_remaining_seconds = 0.0
		return
	state.is_reloading = true
	state.reload_remaining_seconds = definition.reload_seconds


# Temporary magazine-only abstraction: a completed reload refills to capacity
# because reserve ammunition is not modeled yet. Replace this helper when
# reserve ammo exists. Eligibility should keep reading ammo_in_magazine.
static func _refill_magazine_to_capacity(
	state: BattleWeaponState,
	definition: BattleWeaponDefinition
) -> void:
	if state == null or definition == null:
		return
	state.ammo_in_magazine = definition.magazine_capacity
	state.next_firing_hand = 0


static func _fire_block_reason(
	battle_state: BattleState,
	participant: BattleParticipant
) -> String:
	if participant == null:
		return "not_ready"
	if not participant.has_target_participant or participant.target_participant_id.is_empty():
		return "not_ready"
	if not battle_state.has_participant(participant.target_participant_id):
		return "not_ready"
	var target: BattleParticipant = battle_state.get_participant(participant.target_participant_id)
	return _aggregate_block_reason(_pair_rejection_code(battle_state, participant, target))


static func _aggregate_block_reason(rejection_code: String) -> String:
	match rejection_code:
		"":
			return ""
		"reloading":
			return "reloading"
		"empty_magazine":
			return "empty"
		"cooldown":
			return "cooldown"
		"out_of_range":
			return "range"
		"line_of_sight_blocked":
			return "los"
		"wound_reaction":
			return "not_ready"
		"acquire_reaction":
			return "not_ready"
		"sniper_aim":
			return "not_ready"
		"cover_tucked":
			return "not_ready"
		"target_tucked_protected":
			return "not_ready"
		_:
			return "not_ready"


static func _pair_rejection_code(
	battle_state: BattleState,
	source: BattleParticipant,
	target: BattleParticipant,
	ignore_source_cover_posture: bool = false
) -> String:
	var source_rejection: String = _source_rejection_code(
		battle_state,
		source,
		ignore_source_cover_posture
	)
	if not source_rejection.is_empty():
		return source_rejection
	var target_rejection: String = _target_rejection_code(battle_state, source, target)
	if not target_rejection.is_empty():
		return target_rejection
	var state: BattleWeaponState = source.weapon_state
	if state.is_reloading:
		return "reloading"
	if state.ammo_in_magazine <= 0:
		return "empty_magazine"
	if not is_finite(state.cooldown_remaining_seconds) or state.cooldown_remaining_seconds > 0.0:
		return "cooldown"
	var definition: BattleWeaponDefinition = BattleWeaponCatalog.for_participant(source)
	if definition == null:
		return "invalid_weapon_state"
	if not _is_target_in_range(source, target, definition):
		return "out_of_range"
	var los_result: BattleLineOfSightResult = BattleLineOfSightService.check_participant_to_participant(
		battle_state,
		source.participant_id,
		target.participant_id
	)
	if los_result == null or not los_result.success:
		return "source_not_eligible"
	if not los_result.has_line_of_sight:
		return "line_of_sight_blocked"
	if _is_target_tucked_protected(battle_state, source, target):
		return "target_tucked_protected"
	return ""


static func is_spatial_fire_engagement(
	battle_state: BattleState,
	source: BattleParticipant,
	target: BattleParticipant
) -> bool:
	if battle_state == null or source == null or target == null:
		return false
	var definition: BattleWeaponDefinition = BattleWeaponCatalog.for_participant(source)
	if definition == null:
		return false
	if not _source_identity_rejection_code(battle_state, source, definition).is_empty():
		return false
	if not _target_rejection_code(battle_state, source, target).is_empty():
		return false
	if not _is_target_in_range(source, target, definition):
		return false
	var los_result: BattleLineOfSightResult = BattleLineOfSightService.check_participant_to_participant(
		battle_state,
		source.participant_id,
		target.participant_id
	)
	if los_result == null or not los_result.success:
		return false
	return los_result.has_line_of_sight


static func _advance_acquire_reaction(participant: BattleParticipant, delta_seconds: float) -> void:
	if participant == null:
		return
	if not is_finite(participant.acquire_reaction_remaining_seconds):
		participant.acquire_reaction_remaining_seconds = 0.0
		return
	if participant.acquire_reaction_remaining_seconds <= 0.0:
		participant.acquire_reaction_remaining_seconds = 0.0
		return
	participant.acquire_reaction_remaining_seconds = maxf(
		participant.acquire_reaction_remaining_seconds - delta_seconds,
		0.0
	)


static func _advance_sniper_aim(participant: BattleParticipant, delta_seconds: float) -> void:
	if participant == null:
		return
	if not is_finite(participant.sniper_aim_remaining_seconds):
		participant.sniper_aim_remaining_seconds = 0.0
		return
	if participant.sniper_aim_remaining_seconds <= 0.0:
		participant.sniper_aim_remaining_seconds = 0.0
		return
	participant.sniper_aim_remaining_seconds = maxf(
		participant.sniper_aim_remaining_seconds - delta_seconds,
		0.0
	)


static func _source_rejection_code(
	battle_state: BattleState,
	participant: BattleParticipant,
	ignore_source_cover_posture: bool = false
) -> String:
	var identity_rejection: String = _source_identity_rejection_code(battle_state, participant)
	if not identity_rejection.is_empty():
		return identity_rejection
	if participant.has_wound_reaction():
		return "wound_reaction"
	if participant.weapon_type == "sniper" and (participant.velocity.length_squared() > 0.04 or (participant.has_active_navigation_path() and participant.battle_position.distance_to(participant.navigation_destination) > 0.1)):
		return "sniper_moving"
	if not ignore_source_cover_posture and participant.is_cover_tucked():
		return "cover_tucked"
	return ""


static func _is_target_tucked_protected(
	battle_state: BattleState,
	source: BattleParticipant,
	target: BattleParticipant
) -> bool:
	if battle_state == null or source == null or target == null:
		return false
	if not target.is_cover_tucked():
		return false
	if battle_state.battlefield_geometry == null:
		return false
	if not source.has_battle_position:
		return false
	var protection: BattleCoverProtectionResult = BattleCoverProtectionService.query_protection(
		battle_state.battlefield_geometry,
		target,
		source.battle_position
	)
	if protection == null or not protection.has_applicable_cover:
		return false
	if not is_finite(protection.protection_factor):
		return false
	return (
		protection.protection_factor
		>= BattleCombatBehaviorCatalog.COVER_TUCKED_SHOT_BLOCK_FACTOR
	)


static func _source_identity_rejection_code(
	battle_state: BattleState,
	participant: BattleParticipant,
	prepared_definition: BattleWeaponDefinition = null
) -> String:
	if participant == null:
		return "source_not_eligible"
	if not participant.is_alive:
		return "source_not_eligible"
	if not participant.has_battle_position:
		return "source_not_eligible"
	if not _is_finite_vector(participant.battle_position):
		return "source_not_eligible"
	if participant.side_id.is_empty() or not battle_state.has_side(participant.side_id):
		return "source_not_eligible"
	var state: BattleWeaponState = participant.weapon_state
	if state == null:
		return "invalid_weapon_state"
	if state.weapon_type_id.is_empty():
		return "invalid_weapon_state"
	if not participant.weapon_type.is_empty() and participant.weapon_type != state.weapon_type_id:
		return "weapon_type_mismatch"
	if prepared_definition == null and BattleWeaponCatalog.for_participant(participant) == null:
		return "invalid_weapon_state"
	if state.ammo_in_magazine < 0:
		return "invalid_weapon_state"
	if not is_finite(state.cooldown_remaining_seconds) or not is_finite(state.reload_remaining_seconds):
		return "invalid_weapon_state"
	return ""


static func _target_rejection_code(
	battle_state: BattleState,
	source: BattleParticipant,
	target: BattleParticipant
) -> String:
	if source == null or target == null:
		return "target_not_eligible"
	if target.participant_id == source.participant_id:
		return "target_not_eligible"
	if not target.is_alive:
		return "target_not_eligible"
	if not target.has_battle_position:
		return "target_not_eligible"
	if not _is_finite_vector(target.battle_position):
		return "target_not_eligible"
	if target.side_id.is_empty() or not battle_state.has_side(target.side_id):
		return "target_not_eligible"
	if source.side_id == target.side_id:
		return "not_hostile"
	return ""


static func _is_target_in_range(
	source: BattleParticipant,
	target: BattleParticipant,
	definition: BattleWeaponDefinition
) -> bool:
	if source == null or target == null or definition == null:
		return false
	var max_range_squared: float = definition.max_range * definition.max_range
	if not is_finite(max_range_squared):
		return false
	var distance_squared: float = source.battle_position.distance_squared_to(target.battle_position)
	if not is_finite(distance_squared):
		return false
	return distance_squared <= max_range_squared


static func _sorted_participant_ids(battle_state: BattleState) -> Array[String]:
	var ids: Array[String] = []
	for participant_id: String in battle_state.participants:
		ids.append(participant_id)
	ids.sort()
	return ids


static func _is_finite_vector(value: Vector2) -> bool:
	return is_finite(value.x) and is_finite(value.y)

