class_name BattleLineOfSightService
extends RefCounted

const BattleState := preload("res://battle/core/battle_state.gd")
const BattleParticipant := preload("res://battle/core/battle_participant.gd")
const BattlefieldGeometry := preload("res://battle/geometry/battlefield_geometry.gd")
const BattleObstacle := preload("res://battle/geometry/battle_obstacle.gd")
const BattleSpatialService := preload("res://battle/geometry/battle_spatial_service.gd")
const BattleLineOfSightResult := preload("res://battle/combat/battle_line_of_sight_result.gd")

# Geometric contact tolerance only. Not perception range, weapon range, or cover.
const LINE_OF_SIGHT_EPSILON := 0.0001


static func check_participant_to_participant(
	battle_state: BattleState,
	source_participant_id: String,
	target_participant_id: String
) -> BattleLineOfSightResult:
	var geometry_error: BattleLineOfSightResult = _validate_geometry(
		battle_state,
		source_participant_id,
		target_participant_id
	)
	if geometry_error != null:
		return geometry_error
	if source_participant_id.is_empty() or not battle_state.has_participant(source_participant_id):
		return BattleLineOfSightResult.failed(
			"source_not_found",
			"Battle line of sight failed: source participant was not found.",
			source_participant_id,
			target_participant_id
		)
	if target_participant_id.is_empty() or not battle_state.has_participant(target_participant_id):
		return BattleLineOfSightResult.failed(
			"target_not_found",
			"Battle line of sight failed: target participant was not found.",
			source_participant_id,
			target_participant_id
		)
	var source: BattleParticipant = battle_state.get_participant(source_participant_id)
	var target: BattleParticipant = battle_state.get_participant(target_participant_id)
	if not _is_eligible_endpoint(source):
		return BattleLineOfSightResult.failed(
			"source_not_eligible",
			"Battle line of sight failed: source participant is not eligible.",
			source_participant_id,
			target_participant_id
		)
	if not _is_eligible_endpoint(target):
		return BattleLineOfSightResult.failed(
			"target_not_eligible",
			"Battle line of sight failed: target participant is not eligible.",
			source_participant_id,
			target_participant_id
		)
	return _trace_segment_cached(
		battle_state,
		source.battle_position,
		target.battle_position,
		source_participant_id,
		target_participant_id
	)


static func check_segment(
	battle_state: BattleState,
	start_position: Vector2,
	end_position: Vector2
) -> BattleLineOfSightResult:
	var geometry_error: BattleLineOfSightResult = _validate_geometry(battle_state, "", "")
	if geometry_error != null:
		return geometry_error
	if not BattlefieldGeometry.is_finite_point(start_position) or not BattlefieldGeometry.is_finite_point(end_position):
		return BattleLineOfSightResult.failed(
			"invalid_segment",
			"Battle line of sight failed: segment endpoints are invalid."
		)
	return _trace_segment_cached(
		battle_state,
		start_position,
		end_position,
		"",
		""
	)


static func _validate_geometry(
	battle_state: BattleState,
	source_participant_id: String,
	target_participant_id: String
) -> BattleLineOfSightResult:
	if battle_state == null:
		return BattleLineOfSightResult.failed(
			"null_battle_state",
			"Battle line of sight failed: battle_state is null.",
			source_participant_id,
			target_participant_id
		)
	if battle_state.battlefield_geometry == null:
		return BattleLineOfSightResult.failed(
			"missing_battlefield_geometry",
			"Battle line of sight failed: battlefield geometry is missing.",
			source_participant_id,
			target_participant_id
		)
	if not battle_state.has_valid_geometry():
		return BattleLineOfSightResult.failed(
			"invalid_battlefield_geometry",
			"Battle line of sight failed: battlefield geometry is invalid.",
			source_participant_id,
			target_participant_id
		)
	return null


static func _is_eligible_endpoint(participant: BattleParticipant) -> bool:
	if participant == null:
		return false
	if not participant.is_alive:
		return false
	if not participant.has_battle_position:
		return false
	return BattlefieldGeometry.is_finite_point(participant.battle_position)


static func _trace_segment_cached(
	battle_state: BattleState,
	start_position: Vector2,
	end_position: Vector2,
	source_participant_id: String,
	target_participant_id: String
) -> BattleLineOfSightResult:
	var cached: Variant = battle_state.los_cache_lookup(start_position, end_position)
	if cached is Dictionary:
		var cached_row: Dictionary = cached
		return BattleLineOfSightResult.succeeded(
			bool(cached_row.get("has_los", false)),
			source_participant_id,
			target_participant_id,
			str(cached_row.get("blocking_obstacle_id", ""))
		)
	var result: BattleLineOfSightResult = _trace_segment(
		battle_state.battlefield_geometry,
		start_position,
		end_position,
		source_participant_id,
		target_participant_id
	)
	if result != null and result.success:
		battle_state.los_cache_store(
			start_position,
			end_position,
			result.has_line_of_sight,
			result.blocking_obstacle_id
		)
	return result


# Future elevation-aware visibility (source/target elevation_level, obstacle
# height/occupancy) belongs here. Callers should keep using this service rather
# than branching on elevation themselves. Current combat is flat level 0.
static func _trace_segment(
	geometry: BattlefieldGeometry,
	start_position: Vector2,
	end_position: Vector2,
	source_participant_id: String,
	target_participant_id: String
) -> BattleLineOfSightResult:
	var displacement: Vector2 = end_position - start_position
	if not BattlefieldGeometry.is_finite_point(displacement):
		return BattleLineOfSightResult.failed(
			"invalid_segment",
			"Battle line of sight failed: segment displacement is invalid.",
			source_participant_id,
			target_participant_id
		)
	if (
		start_position.is_equal_approx(end_position)
		or displacement.length() <= LINE_OF_SIGHT_EPSILON
	):
		return BattleLineOfSightResult.succeeded(
			true,
			source_participant_id,
			target_participant_id,
			""
		)
	var segment_bounds: Rect2 = Rect2(start_position.min(end_position), displacement.abs()).grow(LINE_OF_SIGHT_EPSILON)
	var best_t: float = INF
	var best_obstacle_id: String = ""
	var obstacle_ids: Array[String] = geometry.get_obstacle_ids_for_segment(start_position,end_position)
	for obstacle_id: String in obstacle_ids:
		var obstacle: BattleObstacle = geometry.get_obstacle(obstacle_id)
		if obstacle == null or not obstacle.blocks_line_of_sight:
			continue
		if not obstacle.bounds.intersects(segment_bounds, true):
			continue
		if not obstacle.bounds_are_usable():
			continue
		var interior: Rect2 = _interior_bounds(obstacle.bounds)
		if not BattlefieldGeometry.rect_is_usable(interior):
			continue
		var overlap: Vector2 = BattleSpatialService.segment_aabb_overlap_t(
			start_position,
			displacement,
			interior
		)
		if overlap.x > overlap.y:
			continue
		var vis_enter: float = maxf(overlap.x, 0.0)
		var vis_exit: float = minf(overlap.y, 1.0)
		if vis_exit - vis_enter <= LINE_OF_SIGHT_EPSILON:
			continue
		var hit_t: float = vis_enter
		if hit_t < best_t and not is_equal_approx(hit_t, best_t):
			best_t = hit_t
			best_obstacle_id = obstacle_id
			continue
		if is_equal_approx(hit_t, best_t):
			if best_obstacle_id.is_empty() or obstacle_id < best_obstacle_id:
				best_t = hit_t
				best_obstacle_id = obstacle_id
	if best_obstacle_id.is_empty():
		return BattleLineOfSightResult.succeeded(
			true,
			source_participant_id,
			target_participant_id,
			""
		)
	return BattleLineOfSightResult.succeeded(
		false,
		source_participant_id,
		target_participant_id,
		best_obstacle_id
	)


static func _interior_bounds(bounds: Rect2) -> Rect2:
	return Rect2(
		bounds.position.x + LINE_OF_SIGHT_EPSILON,
		bounds.position.y + LINE_OF_SIGHT_EPSILON,
		bounds.size.x - (LINE_OF_SIGHT_EPSILON * 2.0),
		bounds.size.y - (LINE_OF_SIGHT_EPSILON * 2.0)
	)

battle/combat/battle_player_command_serv:
extends RefCounted
# Group objectives use the same cover/navigation authority as individual orders.
const Cover = preload("res://battle/geometry/battle_cover_service.gd")
const Eval = preload("res://battle/combat/battle_combat_cover_evaluation_service.gd")
const Nav = preload("res://battle/navigation/battle_navigation_service.gd")
const Roles = preload("res://battle/combat/battle_combat_behavior_catalog.gd")
const Body = preload("res://battle/vehicles/battle_vehicle_body_service.gd")
const HOLD_RADIUS = 14.0
const HOP_RADIUS = 16.0
const MIN_ADVANCE = 1.0

static func advance_direction(b, side: String) -> float:
	# Stable deployment geometry, never the changing live unit centroid.
	var g = b.battlefield_geometry
	var own = g.attacker_deployment_rect.get_center().x
	var enemy = g.defender_deployment_rect.get_center().x
	var direction = 1.0 if enemy >= own else -1.0
	return direction if side == b.attacker_side_id else -direction

static func role_progress(role: String) -> float:
	return {"shotgun":1.0, "smg":.95, "pistol":.85, "rifle":.75, "sniper":.6}.get(role, .85)

static func issue(b, ids: Array, command: String, line_x: float = NAN) -> Dictionary:
	b.begin_geometry_validation_scope()
	var previous = Body.begin_runtime_collision_scope(b)
	var result = _issue(b, ids, command, line_x)
	Body.end_runtime_collision_scope(previous)
	b.end_geometry_validation_scope()
	return result

static func _issue(b, ids: Array, command: String, line_x: float) -> Dictionary:
	var result = {"accepted":[], "failed":[]}
	var booked = {}
	for id in ids:
		var p = b.get_participant(id)
		if p == null or not p.is_alive or p.is_wounded or not p.has_battle_position:
			result.failed.append(id)
			continue
		var d = advance_direction(b, p.side_id)
		var state = {"line":line_x, "direction":d, "start":p.battle_position, "goal":p.battle_position, "clock":0.0, "settle":0.0}
		if command == "push":
			var distance = (line_x - p.battle_position.x) * d
			if not is_finite(line_x) or distance < MIN_ADVANCE:
				p.player_order_feedback = "Push line must be ahead of this unit"
				result.failed.append(id)
				continue
			state.goal.x += d * distance * role_progress(p.weapon_type)
		elif command == "fall_back":
			if not is_finite(line_x):
				result.failed.append(id)
				continue
			state.goal.x = minf(p.battle_position.x * d, line_x * d - 1.0) * d
		var choice = _choose(b, p, command, state, booked, true)
		if choice.is_empty():
			p.player_order_feedback = "No reachable protective cover for this order"
			result.failed.append(id)
			continue
		state.goal = choice.slot.position
		state.goal_slot = choice.slot.cover_slot_id
		booked[state.goal_slot] = true
		# Stage long movement through protective cover when a useful intermediate exists.
		var step = choice
		if command != "hold" and p.battle_position.distance_to(state.goal) > HOP_RADIUS:
			var intermediate = _choose(b, p, command, state, {}, false)
			if not intermediate.is_empty():
				step = intermediate
		if not _assign(b, p, step):
			result.failed.append(id)
			continue
		p.player_group_command_id = command
		p.player_command_context = state
		p.player_order_feedback = {"hold":"Seeking protective cover", "push":"Advancing through cover", "fall_back":"Withdrawing through cover"}[command]
		result.accepted.append(id)
	return result

static func _protected(p, slot, threat) -> bool:
	if not Eval._slot_is_legal_for_participant(p, slot):
		return false
	return threat == null or Eval.slot_is_legal_and_protective(p, slot, threat)

static func _allowed(point: Vector2, command: String, state: Dictionary) -> bool:
	if not is_finite(state.line):
		return true
	var x = point.x * state.direction
	var edge = state.line * state.direction
	if command == "push" or command == "hold":
		return x <= edge + .05
	return x <= maxf(state.start.x * state.direction, edge) + .05

static func _route_allowed(path, command: String, state: Dictionary) -> bool:
	var crossed = state.start.x * state.direction <= state.line * state.direction
	for point in path.waypoints:
		if not _allowed(point, command, state):
			return false
		if command == "fall_back":
			var near_side = point.x * state.direction <= state.line * state.direction + .05
			if crossed and not near_side:
				return false
			crossed = crossed or near_side
	return true

static func _choose(b, p, command: String, state: Dictionary, booked: Dictionary, final: bool) -> Dictionary:
	var threat = Eval.relevant_cover_threat(b, p)
	var rows = []
	var direction: float = state.direction
	var goal: Vector2 = state.goal
	for slot in b.battlefield_geometry.cover_slots.values():
		if booked.has(slot.cover_slot_id) or not _protected(p, slot, threat):
			continue
		var distance = p.battle_position.distance_to(slot.position)
		if not _allowed(slot.position, command, state):
			continue
		if command == "hold":
			if slot.position.distance_to(state.goal) > HOLD_RADIUS:
				continue
			if slot.cover_slot_id == p.occupied_cover_slot_id:
				return {"slot":slot, "path":null, "final":true}
		elif command == "push":
			if (slot.position.x - state.start.x) * direction < MIN_ADVANCE:
				continue
		elif final and slot.position.x * direction > state.line * direction:
			continue
		if not final:
			if distance > HOP_RADIUS or distance < 1.0:
				continue
			if slot.position.distance_to(goal) >= p.battle_position.distance_to(goal) - 1.0:
				continue
		var score = distance if command == "hold" else absf(slot.position.x-goal.x)*3.0 + absf(slot.position.y-goal.y)*.8 + distance*.15
		# Rearward/sideways steps during retreat are preferable to approaching a threat.
		if threat != null and slot.position.distance_to(threat.battle_position) < p.battle_position.distance_to(threat.battle_position) - 2.0 and command != "push":
			score += 12.0
		rows.append([score, slot.cover_slot_id, slot])
	rows.sort_custom(func(a,z): return a[1] < z[1] if is_equal_approx(a[0],z[0]) else a[0] < z[0])
	var best = {}
	var best_score = INF
	# Bound path searches per decision; this does not run for each mouse movement.
	for i in range(mini(12, rows.size())):
		var slot = rows[i][2]
		if Cover.is_at_slot(p, slot):
			return {"slot":slot, "path":null, "final":final}
		var path = Nav.find_path(b, p.battle_position, slot.position)
		if path == null or not path.success or not _route_allowed(path, command, state):
			continue
		var cost = float(rows[i][0])
		var previous: Vector2 = p.battle_position
		for point in path.waypoints:
			var length = previous.distance_to(point)
			cost += length * .2
			if threat != null and point.distance_to(threat.battle_position) < p.battle_position.distance_to(threat.battle_position) - 3.0:
				cost += length * .3
			previous = point
		if cost < best_score:
			best_score = cost
			best = {"slot":slot, "path":path, "final":final}
	return best

static func _assign(b, p, choice: Dictionary) -> bool:
	var slot = choice.slot
	var path = choice.path
	if Cover.is_at_slot(p, slot):
		var occupied = Cover.occupy_slot(b, p.participant_id, slot.cover_slot_id)
		if occupied == null or not occupied.success:
			return false
		p.set_player_cover_intent(slot.cover_object_id, slot.cover_slot_id)
		p.clear_navigation_path()
		p.clear_movement_intent()
		p.velocity = Vector2.ZERO
		return true
	if path == null or not path.success:
		return false
	if p.occupied_cover_slot_id != slot.cover_slot_id:
		Cover.release_all_for_participant(b, p.participant_id)
	var reserved = Cover.reserve_slot(b, p.participant_id, slot.cover_slot_id)
	if reserved == null or not reserved.success:
		return false
	p.set_player_cover_intent(slot.cover_object_id, slot.cover_slot_id)
	if Cover.is_at_slot(p, slot):
		Cover.occupy_slot(b, p.participant_id, slot.cover_slot_id)
		p.clear_navigation_path()
		p.clear_movement_intent()
		p.velocity = Vector2.ZERO
	else:
		if not p.set_navigation_path(path.destination, path.waypoints, p.NAVIGATION_SOURCE_EXTERNAL):
			Cover.release_reservation(b, p.participant_id)
			return false
		if p.movement_speed <= 0.0:
			p.set_movement_speed(Roles.DEFAULT_COMBAT_MOVEMENT_SPEED)
	return true

static func advance(b, p, delta: float) -> void:
	if p.player_command_context.is_empty():
		return
	if not p.is_alive or p.is_wounded:
		Cover.release_reservation(b, p.participant_id)
		p.clear_navigation_path()
		p.clear_player_tactical_intent()
		return
	var state: Dictionary = p.player_command_context
	var command: String = p.player_group_command_id
	var slot = b.battlefield_geometry.get_cover_slot(p.player_cover_slot_id)
	var arrived = slot != null and Cover.is_at_slot(p, slot)
	if arrived:
		Cover.occupy_slot(b, p.participant_id, slot.cover_slot_id)
		p.clear_navigation_path()
		if command == "push" and p.battle_position.distance_to(state.goal) < 1.0:
			# Keep occupied protection and independent target priority; release positioning.
			p.clear_player_cover_intent()
			p.player_order_feedback = "Push complete"
			return
		if command == "fall_back" and p.battle_position.x * state.direction <= state.line * state.direction + .05:
			p.player_group_command_id = "hold"
			state.goal = p.battle_position
			command = "hold"
			p.player_order_feedback = "Holding defensive position"
	state.clock = float(state.clock) - delta
	if float(state.clock) > 0.0:
		return
	state.clock = 1.25
	var threat = Eval.relevant_cover_threat(b, p)
	var protective = slot != null and _protected(p, slot, threat) and _allowed(slot.position, command, state)
	if command == "hold" and protective:
		return
	if not arrived and protective and p.has_active_navigation_path():
		return
	if arrived and command != "hold":
		state.settle = float(state.settle) + 1.25
		if float(state.settle) < 1.5:
			return
		state.settle = 0.0
	var choice = _choose(b, p, command, state, {}, false if command != "hold" else true)
	if choice.is_empty():
		choice = _choose(b, p, command, state, {}, true)
	if not choice.is_empty() and _assign(b, p, choice):
		# A taken final slot can be replaced by another suitable position near the goal.
		if command == "push" and (choice.get("final",false) or choice.slot.position.distance_to(state.goal) < 1.0):
			state.goal = choice.slot.position
		return
	# Keep current protection and retry; do not silently resume an aggressive force AI.
	p.player_order_feedback = "Waiting for reachable protective cover"
	if not protective:
		Cover.release_reservation(b, p.participant_id)
		p.set_player_hold_intent()

static func line_segments(b, x: float) -> Array:
	var spans = []
	var start = -1.0
	var height = b.battlefield_geometry.height
	for i in range(ceili(height * 2.0) + 1):
		var y = minf(height, i * .5)
		var point = Vector2(x, y)
		var legal = y < height and b.battlefield_geometry.get_movement_blocking_obstacle_id_at(point).is_empty() and Body.blocking_vehicle_id_at(b, point).is_empty()
		if legal and start < 0.0:
			start = y
		elif not legal and start >= 0.0:
			spans.append(Vector2(start, y))
			start = -1.0
	return spans

battle/combat/battle_shotgun_range_fallo:
class_name BattleShotgunRangeFalloffService
extends RefCounted

const BattleWeaponCatalog := preload("res://battle/combat/battle_weapon_catalog.gd")
const BattleWeaponDefinition := preload("res://battle/combat/battle_weapon_definition.gd")
const BattleCombatBehaviorCatalog := preload("res://battle/combat/battle_combat_behavior_catalog.gd")
const BattleShotgunRangeFalloffResult := preload("res://battle/combat/battle_shotgun_range_falloff_result.gd")

# Shotgun-only close→edge interpolation. Not used by other weapons.
# t = 0 at preferred max and closer; t = 1 at max range and beyond.
# Interpolates cumulative quality bands and trauma. Does not draw RNG.
const EDGE_MISS_PROBABILITY := 0.60
const EDGE_GRAZE_PROBABILITY := 0.25
const EDGE_SOLID_PROBABILITY := 0.14
const EDGE_CRITICAL_PROBABILITY := 0.01
const EDGE_GRAZE_TRAUMA := 0.06
const EDGE_SOLID_TRAUMA := 0.28
const EDGE_CRITICAL_TRAUMA := 0.55


static func apply(
	definition: BattleWeaponDefinition,
	distance: float
) -> BattleShotgunRangeFalloffResult:
	if definition == null or definition.weapon_type_id != BattleWeaponCatalog.WEAPON_SHOTGUN:
		return null
	var t: float = distance_t(distance * BattleWeaponCatalog.SHOTGUN_MAX_RANGE / definition.max_range)
	var close_miss_end: float = definition.miss_probability
	var close_graze_end: float = close_miss_end + definition.graze_probability
	var close_solid_end: float = close_graze_end + definition.solid_probability
	var edge_miss_end: float = EDGE_MISS_PROBABILITY
	var edge_graze_end: float = edge_miss_end + EDGE_GRAZE_PROBABILITY
	var edge_solid_end: float = edge_graze_end + EDGE_SOLID_PROBABILITY
	var miss_end: float = lerpf(close_miss_end, edge_miss_end, t)
	var graze_end: float = lerpf(close_graze_end, edge_graze_end, t)
	var solid_end: float = lerpf(close_solid_end, edge_solid_end, t)
	var result: BattleShotgunRangeFalloffResult = BattleShotgunRangeFalloffResult.new()
	result.miss_probability = miss_end
	result.graze_probability = graze_end - miss_end
	result.solid_probability = solid_end - graze_end
	result.critical_probability = 1.0 - solid_end
	result.graze_trauma = lerpf(definition.graze_trauma, EDGE_GRAZE_TRAUMA, t)
	result.solid_trauma = lerpf(definition.solid_trauma, EDGE_SOLID_TRAUMA, t)
	result.critical_trauma = lerpf(definition.critical_trauma, EDGE_CRITICAL_TRAUMA, t)
	return result


static func distance_t(distance: float) -> float:
	if not is_finite(distance):
		return 0.0
	var full_strength_range: float = BattleCombatBehaviorCatalog.SHOTGUN_PREFERRED_MAX
	var max_range: float = BattleWeaponCatalog.SHOTGUN_MAX_RANGE
	if not is_finite(full_strength_range) or not is_finite(max_range):
		return 0.0
	if max_range <= full_strength_range:
		return 0.0
	if distance <= full_strength_range or is_equal_approx(distance, full_strength_range):
		return 0.0
	if distance >= max_range or is_equal_approx(distance, max_range):
		return 1.0
	return (distance - full_strength_range) / (max_range - full_strength_range)

battle/combat/battle_target_selection_se:
class_name BattleTargetSelectionService
extends RefCounted

const Weapons := preload("res://battle/combat/battle_weapon_catalog.gd")
const LOS := preload("res://battle/combat/battle_line_of_sight_service.gd")
const FireControl := preload("res://battle/combat/battle_fire_control_service.gd")

const BattleState := preload("res://battle/core/battle_state.gd")
const BattleParticipant := preload("res://battle/core/battle_participant.gd")
const BattleTargetSelectionResult := preload("res://battle/combat/battle_target_selection_result.gd")


static func advance(battle_state: BattleState) -> BattleTargetSelectionResult:
	if battle_state == null:
		return BattleTargetSelectionResult.failed(
			"null_battle_state",
			"Battle target selection failed: battle_state is null."
		)
	if battle_state.battle_phase != "active":
		return BattleTargetSelectionResult.failed(
			"battle_not_active",
			"Battle target selection failed: battle phase is '%s', not active." % battle_state.battle_phase
		)
	if battle_state.battlefield_geometry == null:
		return BattleTargetSelectionResult.failed(
			"missing_battlefield_geometry",
			"Battle target selection failed: battlefield geometry is missing."
		)
	if not battle_state.has_valid_geometry():
		return BattleTargetSelectionResult.failed(
			"invalid_battlefield_geometry",
			"Battle target selection failed: battlefield geometry is invalid."
		)
	var participant_ids: Array[String] = _sorted_participant_ids(battle_state)
	# Eligibility fields do not change while this synchronous selection pass runs.
	var eligible_rows: Array = []
	for candidate_id: String in participant_ids:
		var candidate: BattleParticipant = battle_state.get_participant(candidate_id)
		if _is_eligible_source(battle_state, candidate):
			eligible_rows.append([candidate_id, candidate])
	var participants_considered: int = 0
	var participants_with_hostiles: int = 0
	var participants_with_targets: int = 0
	var targets_changed: int = 0
	for participant_id: String in participant_ids:
		var participant: BattleParticipant = battle_state.get_participant(participant_id)
		if participant == null:
			continue
		participants_considered += 1
		var had_target: bool = participant.has_target_participant
		var previous_target_id: String = participant.target_participant_id
		if not _is_eligible_source(battle_state, participant):
			participant.clear_target_participant()
			participant.clear_player_priority_target()
		else:
			var locked_id: String = _honored_player_priority_target_id(battle_state, participant)
			if not locked_id.is_empty():
				participants_with_hostiles += 1
				if not participant.set_target_participant(locked_id):
					participant.clear_target_participant()
					participant.clear_player_priority_target()
			else:
				participant.clear_player_priority_target()
				var hostile_ids: Array[String] = _prepared_hostile_ids(participant, eligible_rows)
				if hostile_ids.is_empty():
					participant.clear_target_participant()
				else:
					participants_with_hostiles += 1
					var selected_id: String = _select_best_hostile_id(battle_state, participant, hostile_ids)
					if selected_id.is_empty() or not participant.set_target_participant(selected_id):
						participant.clear_target_participant()
		if participant.has_target_participant:
			participants_with_targets += 1
		if (
			participant.has_target_participant != had_target
			or participant.target_participant_id != previous_target_id
		):
			targets_changed += 1
	return BattleTargetSelectionResult.succeeded(
		participants_considered,
		participants_with_hostiles,
		participants_with_targets,
		targets_changed
	)


static func _sorted_participant_ids(battle_state: BattleState) -> Array[String]:
	var ids: Array[String] = []
	for participant_id: String in battle_state.participants:
		ids.append(participant_id)
	ids.sort()
	return ids


static func _honored_player_priority_target_id(
	battle_state: BattleState,
	participant: BattleParticipant
) -> String:
	if participant == null or not participant.has_player_priority_target():
		return ""
	var locked: BattleParticipant = battle_state.get_participant(participant.player_priority_target_id)
	if not _is_eligible_hostile_candidate(battle_state, participant, locked):
		return ""
	return locked.participant_id


static func _is_eligible_source(battle_state: BattleState, participant: BattleParticipant) -> bool:
	if participant == null:
		return false
	if not participant.is_alive:
		return false
	if not participant.has_battle_position:
		return false
	if not _is_finite_vector(participant.battle_position):
		return false
	if participant.side_id.is_empty():
		return false
	if not battle_state.has_side(participant.side_id):
		return false
	return true


static func _are_tactical_hostiles(
	battle_state: BattleState,
	left: BattleParticipant,
	right: BattleParticipant
) -> bool:
	if left == null or right == null:
		return false
	if left.side_id.is_empty() or right.side_id.is_empty():
		return false
	if not battle_state.has_side(left.side_id) or not battle_state.has_side(right.side_id):
		return false
	return left.side_id != right.side_id


static func _is_eligible_hostile_candidate(
	battle_state: BattleState,
	source: BattleParticipant,
	candidate: BattleParticipant
) -> bool:
	if source == null or candidate == null:
		return false
	if candidate.participant_id == source.participant_id:
		return false
	if not candidate.is_alive:
		return false
	if not candidate.has_battle_position:
		return false
	if not _is_finite_vector(candidate.battle_position):
		return false
	if not _are_tactical_hostiles(battle_state, source, candidate):
		return false
	return true


static func _sorted_eligible_hostile_ids(
	battle_state: BattleState,
	source: BattleParticipant
) -> Array[String]:
	var ids: Array[String] = []
	for participant_id: String in _sorted_participant_ids(battle_state):
		var candidate: BattleParticipant = battle_state.get_participant(participant_id)
		if _is_eligible_hostile_candidate(battle_state, source, candidate):
			ids.append(participant_id)
	return ids


# Provisional nearest-hostile policy. Later combat scoring (LOS, preferred weapon
# range, cover, threat, wounded state, player force commands) should replace this
# comparison without changing target-state ownership or runtime order.
static func _is_better_hostile_candidate(
	source: BattleParticipant,
	challenger: BattleParticipant,
	incumbent: BattleParticipant
) -> bool:
	var challenger_distance: float = source.battle_position.distance_squared_to(challenger.battle_position)
	var incumbent_distance: float = source.battle_position.distance_squared_to(incumbent.battle_position)
	if not is_finite(challenger_distance):
		return false
	if not is_finite(incumbent_distance):
		return true
	if challenger_distance < incumbent_distance:
		return true
	if challenger_distance > incumbent_distance:
		return false
	return challenger.participant_id < incumbent.participant_id


static func _select_best_hostile_id(
	battle_state: BattleState,
	source: BattleParticipant,
	candidate_ids: Array[String]
) -> String:
	if source.weapon_type == "sniper":
		var sniper_id: String = _sniper_target(battle_state, source, candidate_ids)
		if not sniper_id.is_empty(): return sniper_id
	elif _uses_assault_targeting(battle_state, source):
		var visible_id: String = _assault_target(battle_state, source, candidate_ids)
		if not visible_id.is_empty(): return visible_id
	var best_id: String = ""
	var best: BattleParticipant = null
	for candidate_id: String in candidate_ids:
		var candidate: BattleParticipant = battle_state.get_participant(candidate_id)
		if candidate == null:
			continue
		if best == null:
			var distance: float = source.battle_position.distance_squared_to(candidate.battle_position)
			if not is_finite(distance):
				continue
			best_id = candidate_id
			best = candidate
			continue
		if _is_better_hostile_candidate(source, candidate, best):
			best_id = candidate_id
			best = candidate
	return best_id


static func _is_finite_vector(value: Vector2) -> bool:
	return is_finite(value.x) and is_finite(value.y)


# Pick a distant visible target, then finish the acquisition instead of target hopping.
# A close visible threat overrides the long-range preference; player focus wins upstream.
static func _sniper_target(b: BattleState, source: BattleParticipant, ids: Array[String]) -> String:
	var d = Weapons.for_participant(source)
	if d == null: return ""
	var urgent: String = ""
	var urgent_distance: float = INF
	var distant: Array = []
	var retained: bool = false
	for index in range(ids.size()):
		var id: String = ids[index]
		var p: BattleParticipant = b.get_participant(id)
		var distance: float = source.battle_position.distance_to(p.battle_position)
		if distance > d.max_range: continue
		if id == source.target_participant_id: retained = true
		if distance < 12.0 and distance < urgent_distance:
			var sight = LOS.check_participant_to_participant(b, source.participant_id, id)
			if sight != null and sight.success and sight.has_line_of_sight:
				urgent = id
				urgent_distance = distance
		distant.append([distance,index,id])
	if not urgent.is_empty(): return urgent
	if retained:
		var sight = LOS.check_participant_to_participant(b,source.participant_id,source.target_participant_id)
		if sight != null and sight.success and sight.has_line_of_sight:
			return source.target_participant_id
	# Once no close threat or retained target wins, only the farthest visible
	# candidate matters. Original roster order still breaks equal-distance ties.
	distant.sort_custom(func(a: Array,c: Array):return a[0]>c[0] if a[0]!=c[0] else a[1]<c[1])
	for row: Array in distant:
		var sight = LOS.check_participant_to_participant(b,source.participant_id,row[2])
		if sight != null and sight.success and sight.has_line_of_sight:
			return row[2]
	return ""


# Advancing units engage visible threats instead of tracking a blocked enemy.
# Explicit player targets are honored upstream; sniper acquisition is unchanged.
static func _uses_assault_targeting(b: BattleState, source: BattleParticipant) -> bool:
	var force = b.get_tactical_force(source.tactical_force_id)
	return force != null and force.command_id in ["push", "focus_left", "focus_right"]


static func _assault_target(b: BattleState, source: BattleParticipant, ids: Array[String]) -> String:
	# Source identity and equipment are constant throughout this candidate scan.
	if not FireControl._source_identity_rejection_code(b, source).is_empty():
		return ""
	var definition = Weapons.for_participant(source)
	if definition == null:
		return ""
	# Range is constant for this scan. Cull impossible candidates before ranking,
	# while preserving the original distance calculation and stable tie order.
	var max_range_squared: float = definition.max_range * definition.max_range
	if not is_finite(max_range_squared): return ""
	var ordered: Array = []
	for index in range(ids.size()):
		var id: String = ids[index]
		var candidate: BattleParticipant = b.get_participant(id)
		var distance_squared: float = source.battle_position.distance_squared_to(candidate.battle_position)
		if not is_finite(distance_squared) or distance_squared > max_range_squared: continue
		var distance: float = source.battle_position.distance_to(candidate.battle_position)
		if id == source.target_participant_id: distance *= 0.85
		if distance < INF:
			ordered.append([distance,index,id,candidate])
	ordered.sort_custom(func(a: Array,c: Array):return a[0]<c[0] if a[0]!=c[0] else a[1]<c[1])
	for row: Array in ordered:
		var candidate: BattleParticipant = row[3]
		if not FireControl._target_rejection_code(b, source, candidate).is_empty(): continue
		var sight = LOS.check_participant_to_participant(b, source.participant_id, row[2])
		if sight != null and sight.success and sight.has_line_of_sight:
			return row[2]
	return ""


# Keep registry order and identity exclusions, including malformed alias entries.
static func _prepared_hostile_ids(source: BattleParticipant, rows: Array) -> Array[String]:
	var ids: Array[String] = []
	for row: Array in rows:
		var candidate: BattleParticipant = row[1]
		if candidate.side_id != source.side_id and candidate.participant_id != source.participant_id:
			ids.append(row[0])
	return ids

battle/core/battle_campaign_outcome_brid:
class_name BattleCampaignOutcomeBridgeService
extends RefCounted

const BattleState := preload("res://battle/core/battle_state.gd")
const BattleSide := preload("res://battle/core/battle_side.gd")
const BattleCampaignSource := preload("res://battle/core/battle_campaign_source.gd")
const BattleCampaignOutcomeBridgeResult := preload("res://battle/core/battle_campaign_outcome_bridge_result.gd")
const BattleVictoryResult := preload("res://battle/core/battle_victory_result.gd")
const CampaignMission := preload("res://campaign/missions/campaign_mission.gd")
const NeighborhoodHQBattleResolver := preload("res://campaign/missions/resolvers/neighborhood_hq_battle_resolver.gd")
const NeighborhoodHQBattleResult := preload("res://campaign/missions/resolvers/neighborhood_hq_battle_result.gd")

const SOURCE_NEIGHBORHOOD_HQ_ASSAULT := BattleCampaignSource.SOURCE_NEIGHBORHOOD_HQ_ASSAULT
const MISSION_TYPE_CAPTURE_HQ := "capture_neighborhood_hq"


static func apply(
	game_state: GameState,
	battle_state: BattleState
) -> BattleCampaignOutcomeBridgeResult:
	if game_state == null:
		return BattleCampaignOutcomeBridgeResult.failed(
			"null_game_state",
			"Battle campaign outcome bridge failed: game_state is null."
		)
	if battle_state == null:
		return BattleCampaignOutcomeBridgeResult.failed(
			"null_battle_state",
			"Battle campaign outcome bridge failed: battle_state is null."
		)
	if battle_state.battle_phase != "resolved":
		return BattleCampaignOutcomeBridgeResult.failed(
			"battle_not_resolved",
			"Battle campaign outcome bridge failed: battle phase is '%s', not resolved."
			% battle_state.battle_phase,
			battle_state.mission_id
		)
	if battle_state.tactical_result == null:
		return BattleCampaignOutcomeBridgeResult.failed(
			"missing_tactical_result",
			"Battle campaign outcome bridge failed: resolved battle is missing tactical_result.",
			battle_state.mission_id
		)
	var tactical_result: BattleVictoryResult = battle_state.tactical_result
	if not tactical_result.resolved:
		return BattleCampaignOutcomeBridgeResult.failed(
			"missing_tactical_result",
			"Battle campaign outcome bridge failed: tactical_result is not resolved.",
			battle_state.mission_id
		)

	var source: BattleCampaignSource = _campaign_source(battle_state)
	if source == null or source.source_type_id.is_empty():
		return BattleCampaignOutcomeBridgeResult.failed(
			"malformed_campaign_source",
			"Battle campaign outcome bridge failed: campaign source type is missing.",
			battle_state.mission_id
		)
	if source.source_type_id != SOURCE_NEIGHBORHOOD_HQ_ASSAULT:
		return BattleCampaignOutcomeBridgeResult.acknowledged(
			BattleCampaignOutcomeBridgeResult.OUTCOME_UNSUPPORTED_BATTLE_SOURCE,
			source.mission_id
		)

	var context_error: BattleCampaignOutcomeBridgeResult = _validate_hq_assault_context(
		game_state,
		battle_state,
		source
	)
	if context_error != null:
		return context_error

	var mission: CampaignMission = game_state.get_mission(source.mission_id)
	if _mission_already_resolved(mission):
		return BattleCampaignOutcomeBridgeResult.acknowledged(
			BattleCampaignOutcomeBridgeResult.OUTCOME_ALREADY_APPLIED,
			mission.id
		)

	if tactical_result.result_kind == BattleVictoryResult.RESULT_DRAW:
		return BattleCampaignOutcomeBridgeResult.acknowledged(
			BattleCampaignOutcomeBridgeResult.OUTCOME_DRAW_UNSUPPORTED,
			mission.id
		)

	if tactical_result.result_kind != BattleVictoryResult.RESULT_VICTORY:
		return BattleCampaignOutcomeBridgeResult.failed(
			"invalid_tactical_result",
			"Battle campaign outcome bridge failed: tactical result_kind '%s' is not victory or draw."
			% tactical_result.result_kind,
			mission.id
		)

	var attacker_won: bool = false
	if tactical_result.winning_side_id == battle_state.attacker_side_id:
		attacker_won = true
	elif tactical_result.winning_side_id == battle_state.defender_side_id:
		attacker_won = false
	else:
		return BattleCampaignOutcomeBridgeResult.failed(
			"invalid_winning_side",
			"Battle campaign outcome bridge failed: winning side '%s' is neither attacker '%s' nor defender '%s'."
			% [
				tactical_result.winning_side_id,
				battle_state.attacker_side_id,
				battle_state.defender_side_id
			],
			mission.id
		)

	if mission.mission_state != "awaiting_resolution":
		return BattleCampaignOutcomeBridgeResult.failed(
			"mission_not_awaiting_resolution",
			"Battle campaign outcome bridge failed: mission '%s' is '%s', not awaiting_resolution."
			% [mission.id, mission.mission_state],
			mission.id
		)

	var campaign_result: NeighborhoodHQBattleResult = NeighborhoodHQBattleResolver.resolve(
		game_state,
		mission.id,
		attacker_won
	)
	if campaign_result == null or not campaign_result.success:
		var error_code: String = "campaign_resolution_failed"
		var error_message: String = "Battle campaign outcome bridge failed: existing HQ resolver did not succeed."
		if campaign_result != null:
			if not campaign_result.error_code.is_empty():
				error_code = campaign_result.error_code
			if not campaign_result.error_message.is_empty():
				error_message = campaign_result.error_message
		return BattleCampaignOutcomeBridgeResult.failed(error_code, error_message, mission.id)

	if attacker_won:
		return BattleCampaignOutcomeBridgeResult.applied_outcome(
			BattleCampaignOutcomeBridgeResult.OUTCOME_ATTACKER_VICTORY_APPLIED,
			mission.id
		)
	return BattleCampaignOutcomeBridgeResult.applied_outcome(
		BattleCampaignOutcomeBridgeResult.OUTCOME_DEFENDER_VICTORY_APPLIED,
		mission.id
	)


static func _campaign_source(battle_state: BattleState) -> BattleCampaignSource:
	if battle_state.campaign_source != null:
		return battle_state.campaign_source
	var derived := BattleCampaignSource.new(
		battle_state.battle_type_id,
		battle_state.mission_id,
		"",
		battle_state.location_id
	)
	if not battle_state.attacker_side_id.is_empty():
		var attacker_side: BattleSide = battle_state.get_side(battle_state.attacker_side_id)
		if attacker_side != null:
			derived.force_id = attacker_side.force_id
	return derived


static func _validate_hq_assault_context(
	game_state: GameState,
	battle_state: BattleState,
	source: BattleCampaignSource
) -> BattleCampaignOutcomeBridgeResult:
	if not source.is_populated():
		return BattleCampaignOutcomeBridgeResult.failed(
			"malformed_campaign_source",
			"Battle campaign outcome bridge failed: HQ assault provenance IDs are incomplete.",
			source.mission_id
		)
	if battle_state.battle_type_id != SOURCE_NEIGHBORHOOD_HQ_ASSAULT:
		return BattleCampaignOutcomeBridgeResult.failed(
			"malformed_campaign_source",
			"Battle campaign outcome bridge failed: battle_type_id '%s' does not match neighborhood_hq_assault."
			% battle_state.battle_type_id,
			source.mission_id
		)
	if battle_state.mission_id != source.mission_id:
		return BattleCampaignOutcomeBridgeResult.failed(
			"mission_id_mismatch",
			"Battle campaign outcome bridge failed: battle mission_id '%s' does not match source mission_id '%s'."
			% [battle_state.mission_id, source.mission_id],
			source.mission_id
		)
	if battle_state.location_id != source.target_location_id:
		return BattleCampaignOutcomeBridgeResult.failed(
			"target_location_mismatch",
			"Battle campaign outcome bridge failed: battle location_id '%s' does not match source target_location_id '%s'."
			% [battle_state.location_id, source.target_location_id],
			source.mission_id
		)
	if battle_state.attacker_side_id.is_empty() or not battle_state.has_side(battle_state.attacker_side_id):
		return BattleCampaignOutcomeBridgeResult.failed(
			"missing_attacker_side",
			"Battle campaign outcome bridge failed: attacker_side_id '%s' is missing."
			% battle_state.attacker_side_id,
			source.mission_id
		)
	if battle_state.defender_side_id.is_empty() or not battle_state.has_side(battle_state.defender_side_id):
		return BattleCampaignOutcomeBridgeResult.failed(
			"missing_defender_side",
			"Battle campaign outcome bridge failed: defender_side_id '%s' is missing."
			% battle_state.defender_side_id,
			source.mission_id
		)
	if battle_state.attacker_side_id == battle_state.defender_side_id:
		return BattleCampaignOutcomeBridgeResult.failed(
			"attacker_defender_side_collision",
			"Battle campaign outcome bridge failed: attacker and defender share side id '%s'."
			% battle_state.attacker_side_id,
			source.mission_id
		)
	var attacker_side: BattleSide = battle_state.get_side(battle_state.attacker_side_id)
	if attacker_side == null or attacker_side.force_id != source.force_id:
		return BattleCampaignOutcomeBridgeResult.failed(
			"force_id_mismatch",
			"Battle campaign outcome bridge failed: attacker side force_id does not match source force_id '%s'."
			% source.force_id,
			source.mission_id
		)
	if not game_state.has_mission(source.mission_id):
		return BattleCampaignOutcomeBridgeResult.failed(
			"invalid_mission",
			"Battle campaign outcome bridge failed: mission '%s' does not exist." % source.mission_id,
			source.mission_id
		)
	var mission: CampaignMission = game_state.get_mission(source.mission_id)
	if mission == null:
		return BattleCampaignOutcomeBridgeResult.failed(
			"invalid_mission",
			"Battle campaign outcome bridge failed: mission '%s' does not exist." % source.mission_id,
			source.mission_id
		)
	if mission.mission_type_id != MISSION_TYPE_CAPTURE_HQ:
		return BattleCampaignOutcomeBridgeResult.failed(
			"invalid_mission_type",
			"Battle campaign outcome bridge failed: mission '%s' type is '%s', not capture_neighborhood_hq."
			% [mission.id, mission.mission_type_id],
			mission.id
		)
	if mission.force_id != source.force_id:
		return BattleCampaignOutcomeBridgeResult.failed(
			"force_id_mismatch",
			"Battle campaign outcome bridge failed: mission force_id '%s' does not match source force_id '%s'."
			% [mission.force_id, source.force_id],
			mission.id
		)
	if mission.target_location_id != source.target_location_id:
		return BattleCampaignOutcomeBridgeResult.failed(
			"target_location_mismatch",
			"Battle campaign outcome bridge failed: mission target_location_id '%s' does not match source target_location_id '%s'."
			% [mission.target_location_id, source.target_location_id],
			mission.id
		)
	if source.force_id.is_empty() or not game_state.has_traveling_force(source.force_id):
		return BattleCampaignOutcomeBridgeResult.failed(
			"invalid_force",
			"Battle campaign outcome bridge failed: attacking force '%s' does not exist." % source.force_id,
			mission.id
		)
	var force: TravelingForce = game_state.get_traveling_force(source.force_id)
	if force == null:
		return BattleCampaignOutcomeBridgeResult.failed(
			"invalid_force",
			"Battle campaign outcome bridge failed: attacking force '%s' does not exist." % source.force_id,
			mission.id
		)
	if force.faction_id != mission.faction_id:
		return BattleCampaignOutcomeBridgeResult.failed(
			"force_faction_mismatch",
			"Battle campaign outcome bridge failed: force '%s' faction '%s' does not match mission faction '%s'."
			% [force.id, force.faction_id, mission.faction_id],
			mission.id
		)
	if force.destination_location_id != source.target_location_id:
		return BattleCampaignOutcomeBridgeResult.failed(
			"force_target_mismatch",
			"Battle campaign outcome bridge failed: force '%s' destination '%s' does not match target '%s'."
			% [force.id, force.destination_location_id, source.target_location_id],
			mission.id
		)
	if force.travel_state != "at_destination":
		return BattleCampaignOutcomeBridgeResult.failed(
			"force_not_at_destination",
			"Battle campaign outcome bridge failed: force '%s' is '%s', not at_destination."
			% [force.id, force.travel_state],
			mission.id
		)
	if source.target_location_id.is_empty() or not game_state.has_map_location(source.target_location_id):
		return BattleCampaignOutcomeBridgeResult.failed(
			"invalid_target_location",
			"Battle campaign outcome bridge failed: target '%s' does not exist." % source.target_location_id,
			mission.id
		)
	var target_location: MapLocation = game_state.get_map_location(source.target_location_id)
	if target_location == null or not (target_location is NeighborhoodHQ):
		return BattleCampaignOutcomeBridgeResult.failed(
			"target_not_neighborhood_hq",
			"Battle campaign outcome bridge failed: target '%s' is not a NeighborhoodHQ."
			% source.target_location_id,
			mission.id
		)
	return null


static func _mission_already_resolved(mission: CampaignMission) -> bool:
	if mission == null:
		return false
	if mission.mission_state == "resolved_success":
		return true
	if mission.mission_state == "resolved_failure":
		return true
	if mission.mission_state == "complete":
		return true
	return false

battle/core/battle_deployment_placement_:
class_name BattleDeploymentPlacementService
extends RefCounted

# Authoritative participant placement during deployment.
# Composes BattleState.deploy_participant (membership) with validated battle_position.
# Does not own geometry. Does not auto-layout. Does not begin battle.

const BattleState := preload("res://battle/core/battle_state.gd")
const BattleParticipant := preload("res://battle/core/battle_participant.gd")
const BattleSide := preload("res://battle/core/battle_side.gd")
const BattleDeploymentPlacementResult := preload("res://battle/core/battle_deployment_placement_result.gd")


static func place_participant(
	battle_state: BattleState,
	participant_id: String,
	position: Vector2
) -> BattleDeploymentPlacementResult:
	if battle_state == null:
		return BattleDeploymentPlacementResult.failed(
			"null_battle_state",
			"Deployment placement failed: battle_state is null.",
			participant_id,
			position
		)
	if battle_state.battle_phase != "deployment":
		return BattleDeploymentPlacementResult.failed(
			"battle_not_in_deployment",
			"Deployment placement failed: battle phase is '%s', not deployment." % battle_state.battle_phase,
			participant_id,
			position
		)
	if participant_id.is_empty() or not battle_state.has_participant(participant_id):
		return BattleDeploymentPlacementResult.failed(
			"unknown_participant",
			"Deployment placement failed: participant '%s' does not exist." % participant_id,
			participant_id,
			position
		)
	var participant: BattleParticipant = battle_state.get_participant(participant_id)
	if participant == null:
		return BattleDeploymentPlacementResult.failed(
			"unknown_participant",
			"Deployment placement failed: participant '%s' does not exist." % participant_id,
			participant_id,
			position
		)
	if not participant.is_alive:
		return BattleDeploymentPlacementResult.failed(
			"participant_dead",
			"Deployment placement failed: participant '%s' is not alive." % participant_id,
			participant_id,
			position
		)
	if battle_state.is_participant_deployed(participant_id) or participant.has_battle_position:
		if (
			battle_state.is_participant_deployed(participant_id)
			and participant.has_battle_position
		):
			return _reposition_deployed_participant(
				battle_state,
				participant,
				participant_id,
				position
			)
		return BattleDeploymentPlacementResult.failed(
			"already_deployed",
			"Deployment placement failed: participant '%s' is already deployed." % participant_id,
			participant_id,
			position
		)
	if not battle_state.has_side(participant.side_id):
		return BattleDeploymentPlacementResult.failed(
			"missing_side",
			"Deployment placement failed: side '%s' does not exist." % participant.side_id,
			participant_id,
			position
		)
	if battle_state.is_side_deployment_committed(participant.side_id):
		return BattleDeploymentPlacementResult.failed(
			"side_deployment_committed",
			"Deployment placement failed: side '%s' deployment is already committed." % participant.side_id,
			participant_id,
			position
		)
	var side: BattleSide = battle_state.get_side(participant.side_id)
	if side == null or side.deployment_zone_id.is_empty():
		return BattleDeploymentPlacementResult.failed(
			"missing_deployment_zone",
			"Deployment placement failed: side '%s' has no deployment zone." % participant.side_id,
			participant_id,
			position
		)
	var geometry_error: BattleDeploymentPlacementResult = _validate_position(
		battle_state,
		participant.side_id,
		position,
		participant_id
	)
	if geometry_error != null:
		return geometry_error
	if not battle_state.deploy_participant(participant_id, side.deployment_zone_id):
		return BattleDeploymentPlacementResult.failed(
			"deploy_failed",
			"Deployment placement failed: BattleState.deploy_participant rejected '%s'." % participant_id,
			participant_id,
			position
		)
	participant.has_battle_position = true
	participant.battle_position = position
	return BattleDeploymentPlacementResult.succeeded(participant_id, position)


static func _reposition_deployed_participant(
	battle_state: BattleState,
	participant: BattleParticipant,
	participant_id: String,
	position: Vector2
) -> BattleDeploymentPlacementResult:
	if battle_state.is_side_deployment_committed(participant.side_id):
		return BattleDeploymentPlacementResult.failed(
			"side_deployment_committed",
			"Deployment placement failed: side '%s' deployment is already committed." % participant.side_id,
			participant_id,
			position
		)
	var geometry_error: BattleDeploymentPlacementResult = _validate_position(
		battle_state,
		participant.side_id,
		position,
		participant_id
	)
	if geometry_error != null:
		return geometry_error
	participant.has_battle_position = true
	participant.battle_position = position
	return BattleDeploymentPlacementResult.succeeded(participant_id, position)


static func _validate_position(
	battle_state: BattleState,
	side_id: String,
	position: Vector2,
	participant_id: String
) -> BattleDeploymentPlacementResult:
	# Shared legality lives on BattleState.get_deployment_position_error:
	# finite point, geometry.contains_point, attacker_deployment_contains,
	# defender_deployment_contains, and obstacle.blocks_movement.
	var error_code: String = battle_state.get_deployment_position_error(side_id, position)
	if error_code.is_empty():
		return null
	return BattleDeploymentPlacementResult.failed(
		error_code,
		_position_error_message(error_code, side_id, position, battle_state),
		participant_id,
		position
	)


static func _position_error_message(
	error_code: String,
	side_id: String,
	position: Vector2,
	battle_state: BattleState
) -> String:
	match error_code:
		"invalid_position":
			return "Deployment placement failed: position is not finite."
		"missing_battlefield_geometry":
			return "Deployment placement failed: battlefield geometry is missing or invalid."
		"outside_battlefield":
			return "Deployment placement failed: position is outside battlefield bounds."
		"outside_deployment_zone":
			if side_id == battle_state.attacker_side_id:
				return "Deployment placement failed: position is outside the attacker deployment region."
			if side_id == battle_state.defender_side_id:
				return "Deployment placement failed: position is outside the defender deployment region."
			return "Deployment placement failed: position is outside the deployment region."
		"unknown_side":
			return "Deployment placement failed: side '%s' is not attacker or defender." % side_id
		"inside_blocking_obstacle":
			var blocking_id: String = ""
			if battle_state.battlefield_geometry != null:
				blocking_id = battle_state.battlefield_geometry.get_movement_blocking_obstacle_id_at(position)
			if blocking_id.is_empty():
				return "Deployment placement failed: position is inside a movement-blocking obstacle."
			return "Deployment placement failed: position is inside movement-blocking obstacle '%s'." % blocking_id
		"inside_vehicle_body":
			return "Deployment placement failed: position is inside a positioned vehicle body."
		_:
			return "Deployment placement failed: position is not legal (%s)." % error_code

