class_name AuthoredBattlefieldService
extends RefCounted

# Applies an authored battlefield definition onto BattleState.
# Does not own combat, commands, or campaign geography.

const BattleState := preload("res://battle/core/battle_state.gd")
const BattleSide := preload("res://battle/core/battle_side.gd")
const DeploymentZone := preload("res://battle/core/deployment_zone.gd")
const BattlefieldGeometry := preload("res://battle/geometry/battlefield_geometry.gd")
const BattlefieldGeometryResult := preload("res://battle/geometry/battlefield_geometry_result.gd")
const AuthoredBattlefieldDefinition := preload("res://battle/geometry/authored_battlefield_definition.gd")
const TacticalProvingGroundCatalog := preload("res://battle/geometry/tactical_proving_ground_catalog.gd")
const BattleObstacle := preload("res://battle/geometry/battle_obstacle.gd")
const BattleCoverObject := preload("res://battle/geometry/battle_cover_object.gd")
const BattleCoverSlot := preload("res://battle/geometry/battle_cover_slot.gd")
const BattleSurfaceRegion := preload("res://battle/geometry/battle_surface_region.gd")
const BattlePresentationMarking := preload("res://battle/geometry/battle_presentation_marking.gd")
const BattleVisualBinding := preload("res://battle/presentation/battle_visual_binding.gd")
const BattleForceCommandService := preload("res://battle/core/battle_force_command_service.gd")

const LAYOUT_PROVING_GROUND := TacticalProvingGroundCatalog.LAYOUT_ID


static func initialize_proving_ground(battle_state: BattleState) -> BattlefieldGeometryResult:
	return apply_definition(battle_state, TacticalProvingGroundCatalog.hq_frontage_assault_v1())


static func apply_definition(
	battle_state: BattleState,
	definition: AuthoredBattlefieldDefinition
) -> BattlefieldGeometryResult:
	if battle_state == null:
		return BattlefieldGeometryResult.failed(
			"null_battle_state",
			"Authored battlefield failed: battle_state is null."
		)
	if battle_state.battle_phase != "deployment":
		return BattlefieldGeometryResult.failed(
			"battle_not_in_deployment",
			"Authored battlefield failed: battle phase is '%s', not deployment." % battle_state.battle_phase
		)
	if battle_state.attacker_side_id.is_empty() or not battle_state.has_side(battle_state.attacker_side_id):
		return BattlefieldGeometryResult.failed(
			"missing_attacker_side",
			"Authored battlefield failed: attacker side is missing."
		)
	if battle_state.defender_side_id.is_empty() or not battle_state.has_side(battle_state.defender_side_id):
		return BattlefieldGeometryResult.failed(
			"missing_defender_side",
			"Authored battlefield failed: defender side is missing."
		)
	var attacker_side: BattleSide = battle_state.get_side(battle_state.attacker_side_id)
	var defender_side: BattleSide = battle_state.get_side(battle_state.defender_side_id)
	var attacker_zone: DeploymentZone = _require_side_zone(
		battle_state,
		attacker_side,
		battle_state.attacker_side_id
	)
	if attacker_zone == null:
		return BattlefieldGeometryResult.failed(
			"missing_attacker_deployment_zone",
			"Authored battlefield failed: attacker deployment zone is missing."
		)
	var defender_zone: DeploymentZone = _require_side_zone(
		battle_state,
		defender_side,
		battle_state.defender_side_id
	)
	if defender_zone == null:
		return BattlefieldGeometryResult.failed(
			"missing_defender_deployment_zone",
			"Authored battlefield failed: defender deployment zone is missing."
		)
	if definition == null or not definition.is_valid():
		return BattlefieldGeometryResult.failed(
			"invalid_geometry",
			"Authored battlefield failed: definition is invalid."
		)
	var geometry: BattlefieldGeometry = _build_geometry(definition)
	if geometry == null or not geometry.is_valid():
		return BattlefieldGeometryResult.failed(
			"invalid_geometry",
			"Authored battlefield failed: generated geometry is invalid."
		)
	battle_state.battlefield_geometry = geometry
	attacker_zone.deployment_rect = geometry.attacker_deployment_rect
	defender_zone.deployment_rect = geometry.defender_deployment_rect
	BattleForceCommandService.initialize_assault_frames_from_geometry(battle_state)
	return BattlefieldGeometryResult.succeeded(0, 0)


static func _build_geometry(definition: AuthoredBattlefieldDefinition) -> BattlefieldGeometry:
	if definition == null:
		return null
	var geometry: BattlefieldGeometry = BattlefieldGeometry.new()
	geometry.authored_layout_id = definition.definition_id
	geometry.width = definition.width
	geometry.height = definition.height
	geometry.attacker_deployment_area = definition.attacker_deployment_area
	geometry.defender_deployment_area = definition.defender_deployment_area
	geometry.attacker_deployment_rect = definition.attacker_deployment_area.bounding_rect()
	geometry.defender_deployment_rect = definition.defender_deployment_area.bounding_rect()
	geometry.attacker_vehicle_placement_context = definition.attacker_vehicle_placement_context
	geometry.defender_vehicle_placement_context = definition.defender_vehicle_placement_context
	for surface: BattleSurfaceRegion in definition.surfaces:
		if surface == null or not geometry.add_surface_region(surface):
			return null
	for marking: BattlePresentationMarking in definition.presentation_markings:
		if marking == null or not geometry.add_presentation_marking(marking):
			return null
	for binding: BattleVisualBinding in definition.visual_bindings:
		if binding == null or not geometry.add_visual_binding(binding):
			return null
	for obstacle: BattleObstacle in definition.obstacles:
		if obstacle == null or not geometry.add_obstacle(obstacle):
			return null
	for cover_object: BattleCoverObject in definition.cover_objects:
		if cover_object == null or not geometry.add_cover_object(cover_object):
			return null
	for cover_slot: BattleCoverSlot in definition.cover_slots:
		if cover_slot == null or not geometry.add_cover_slot(cover_slot):
			return null
	return geometry


static func _require_side_zone(
	battle_state: BattleState,
	side: BattleSide,
	expected_side_id: String
) -> DeploymentZone:
	if battle_state == null or side == null:
		return null
	if side.deployment_zone_id.is_empty():
		return null
	if not battle_state.has_deployment_zone(side.deployment_zone_id):
		return null
	var zone: DeploymentZone = battle_state.get_deployment_zone(side.deployment_zone_id)
	if zone == null or zone.side_id != expected_side_id:
		return null
	return zone

battle/geometry/battlefield_geometry.gd:
class_name BattlefieldGeometry
extends RefCounted
const RectangleQueryIndex = preload("res://battle/geometry/battle_rectangle_query_index.gd")

const BattleObstacle := preload("res://battle/geometry/battle_obstacle.gd")
const BattleCoverObject := preload("res://battle/geometry/battle_cover_object.gd")
const BattleCoverSlot := preload("res://battle/geometry/battle_cover_slot.gd")
const BattleDeploymentArea := preload("res://battle/geometry/battle_deployment_area.gd")
const BattleDeploymentPocket := preload("res://battle/geometry/battle_deployment_pocket.gd")
const BattleSurfaceRegion := preload("res://battle/geometry/battle_surface_region.gd")
const BattlePresentationMarking := preload("res://battle/geometry/battle_presentation_marking.gd")
const BattleVehiclePlacementContext := preload("res://battle/vehicles/battle_vehicle_placement_context.gd")
const BattleVisualBinding := preload("res://battle/presentation/battle_visual_binding.gd")

var authored_layout_id: String = ""
var width: float = 0.0
var height: float = 0.0
var attacker_deployment_rect: Rect2 = Rect2()
var defender_deployment_rect: Rect2 = Rect2()
var attacker_deployment_area: BattleDeploymentArea = BattleDeploymentArea.new()
var defender_deployment_area: BattleDeploymentArea = BattleDeploymentArea.new()
var attacker_vehicle_placement_context: BattleVehiclePlacementContext = null
var defender_vehicle_placement_context: BattleVehiclePlacementContext = null
var obstacles: Dictionary[String, BattleObstacle] = {}
var cover_objects: Dictionary[String, BattleCoverObject] = {}
var cover_slots: Dictionary[String, BattleCoverSlot] = {}
var surface_regions: Dictionary[String, BattleSurfaceRegion] = {}
var presentation_markings: Array[BattlePresentationMarking] = []
# Presentation-only. Never used by collision, LOS, cover, nav, or deployment.
var visual_bindings: Array[BattleVisualBinding] = []
var content_revision: int = 0
# Cheap cover-catalog stamp. Independent of occupancy and movement blockers.
var cover_slot_revision: int = 0


func is_valid() -> bool:
	if not is_finite(width) or not is_finite(height):
		return false
	if width <= 0.0 or height <= 0.0:
		return false
	if not rect_is_usable(attacker_deployment_rect):
		return false
	if not rect_is_usable(defender_deployment_rect):
		return false
	if not _rect_is_within_battlefield(attacker_deployment_rect):
		return false
	if not _rect_is_within_battlefield(defender_deployment_rect):
		return false
	if attacker_deployment_area == null or not attacker_deployment_area.is_valid():
		return false
	if defender_deployment_area == null or not defender_deployment_area.is_valid():
		return false
	if attacker_deployment_area.has_pockets() and not _area_is_within_battlefield(attacker_deployment_area):
		return false
	if defender_deployment_area.has_pockets() and not _area_is_within_battlefield(defender_deployment_area):
		return false
	for surface_id: String in surface_regions:
		var surface: BattleSurfaceRegion = surface_regions[surface_id]
		if surface == null or surface.region_id != surface_id:
			return false
		if not surface.is_valid():
			return false
	var movement_bounds: Dictionary = {}
	for obstacle_id: String in obstacles:
		var obstacle: BattleObstacle = obstacles[obstacle_id]
		if obstacle == null or obstacle.obstacle_id != obstacle_id:
			return false
		if not obstacle.is_valid():
			return false
		if obstacle.blocks_movement:
			# This validation index is rebuilt from live bounds on every call.
			# Direct edits remain detectable without testing each slot against
			# every obstacle on the entire battlefield.
			var a: Vector2i = Vector2i((obstacle.bounds.position / OBSTACLE_QUERY_CELL_SIZE).floor())
			var z: Vector2i = Vector2i((obstacle.bounds.end / OBSTACLE_QUERY_CELL_SIZE).floor())
			for x in range(a.x, z.x + 1):
				for y in range(a.y, z.y + 1):
					var cell: Vector2i = Vector2i(x, y)
					if not movement_bounds.has(cell):movement_bounds[cell] = []
					movement_bounds[cell].append(obstacle.bounds)
	for cover_object_id: String in cover_objects:
		var cover_object: BattleCoverObject = cover_objects[cover_object_id]
		if cover_object == null or cover_object.cover_object_id != cover_object_id:
			return false
		if not cover_object.is_valid():
			return false
		for slot_id: String in cover_object.slot_ids:
			if not cover_slots.has(slot_id):
				return false
			var owned_slot: BattleCoverSlot = cover_slots[slot_id]
			if owned_slot == null or owned_slot.cover_object_id != cover_object_id:
				return false
	for cover_slot_id: String in cover_slots:
		var cover_slot: BattleCoverSlot = cover_slots[cover_slot_id]
		if cover_slot == null or cover_slot.cover_slot_id != cover_slot_id:
			return false
		if not cover_slot.is_valid():
			return false
		if not cover_objects.has(cover_slot.cover_object_id):
			return false
		var point: Vector2 = cover_slot.position
		if not contains_point(point):
			return false
		# Bounds were validated above. Avoid revalidating each obstacle for every
		# cover slot. Keep the same inclusive edges as rect_contains_point.
		for blocker: Rect2 in movement_bounds.get(Vector2i((point / OBSTACLE_QUERY_CELL_SIZE).floor()), []):
			if point.x >= blocker.position.x and point.x <= blocker.end.x and point.y >= blocker.position.y and point.y <= blocker.end.y:
				return false
	return true


func contains_point(point: Vector2) -> bool:
	if not is_finite_point(point):
		return false
	return (
		point.x >= 0.0
		and point.y >= 0.0
		and point.x <= width
		and point.y <= height
	)


func attacker_deployment_contains(point: Vector2) -> bool:
	if attacker_deployment_area != null and attacker_deployment_area.has_pockets():
		return attacker_deployment_area.contains_point(point)
	return rect_contains_point(attacker_deployment_rect, point)


