func add_cover_slot(cover_slot: BattleCoverSlot) -> bool:
	if cover_slot == null:
		push_error("BattlefieldGeometry.add_cover_slot: cover slot is null.")
		return false
	if cover_slot.cover_slot_id.is_empty():
		push_error("BattlefieldGeometry.add_cover_slot: cover slot id is empty.")
		return false
	if cover_slots.has(cover_slot.cover_slot_id):
		push_error(
			"BattlefieldGeometry.add_cover_slot: duplicate cover slot id '%s'." % cover_slot.cover_slot_id
		)
		return false
	if not cover_slot.is_valid():
		push_error(
			"BattlefieldGeometry.add_cover_slot: cover slot '%s' is invalid." % cover_slot.cover_slot_id
		)
		return false
	if not cover_objects.has(cover_slot.cover_object_id):
		push_error(
			"BattlefieldGeometry.add_cover_slot: cover object '%s' does not exist."
			% cover_slot.cover_object_id
		)
		return false
	if not _cover_slot_position_is_legal(cover_slot.position):
		push_error(
			"BattlefieldGeometry.add_cover_slot: cover slot '%s' position is illegal."
			% cover_slot.cover_slot_id
		)
		return false
	var cover_object: BattleCoverObject = cover_objects[cover_slot.cover_object_id]
	if cover_object.slot_ids.has(cover_slot.cover_slot_id):
		push_error(
			"BattlefieldGeometry.add_cover_slot: cover object '%s' already lists slot '%s'."
			% [cover_object.cover_object_id, cover_slot.cover_slot_id]
		)
		return false
	cover_slots[cover_slot.cover_slot_id] = cover_slot
	cover_object.slot_ids.append(cover_slot.cover_slot_id)
	cover_slot_revision += 1
	return true


func has_cover_slot(cover_slot_id: String) -> bool:
	return cover_slots.has(cover_slot_id)


func get_cover_slot(cover_slot_id: String) -> BattleCoverSlot:
	if cover_slots.has(cover_slot_id):
		return cover_slots[cover_slot_id]
	return null


func get_sorted_cover_slot_ids() -> Array[String]:
	var ids: Array[String] = []
	for cover_slot_id: String in cover_slots:
		ids.append(cover_slot_id)
	ids.sort()
	return ids


func remove_cover_slot(cover_slot_id: String) -> bool:
	if not cover_slots.has(cover_slot_id):
		push_error("BattlefieldGeometry.remove_cover_slot: unknown cover slot id '%s'." % cover_slot_id)
		return false
	var cover_slot: BattleCoverSlot = cover_slots[cover_slot_id]
	if cover_slot != null and (cover_slot.is_occupied() or cover_slot.is_reserved()):
		push_error(
			"BattlefieldGeometry.remove_cover_slot: cover slot '%s' is still owned." % cover_slot_id
		)
		return false
	if cover_slot != null and cover_objects.has(cover_slot.cover_object_id):
		var cover_object: BattleCoverObject = cover_objects[cover_slot.cover_object_id]
		var remaining: Array[String] = []
		for owned_id: String in cover_object.slot_ids:
			if owned_id != cover_slot_id:
				remaining.append(owned_id)
		cover_object.slot_ids = remaining
	cover_slots.erase(cover_slot_id)
	cover_slot_revision += 1
	return true


func _cover_slot_position_is_legal(point: Vector2) -> bool:
	if not is_finite_point(point):
		return false
	if not contains_point(point):
		return false
	for obstacle_id: String in obstacles:
		var obstacle: BattleObstacle = obstacles[obstacle_id]
		if obstacle == null or not obstacle.blocks_movement:
			continue
		if obstacle.contains_point(point):
			return false
	return true


static func rect_contains_point(rect: Rect2, point: Vector2) -> bool:
	if not is_finite_point(point):
		return false
	if not rect_is_usable(rect):
		return false
	return (
		point.x >= rect.position.x
		and point.y >= rect.position.y
		and point.x <= rect.position.x + rect.size.x
		and point.y <= rect.position.y + rect.size.y
	)


static func is_finite_point(point: Vector2) -> bool:
	return is_finite(point.x) and is_finite(point.y)


static func rect_is_usable(rect: Rect2) -> bool:
	if not is_finite(rect.position.x) or not is_finite(rect.position.y):
		return false
	if not is_finite(rect.size.x) or not is_finite(rect.size.y):
		return false
	return rect.size.x > 0.0 and rect.size.y > 0.0


func _rect_is_within_battlefield(rect: Rect2) -> bool:
	if not rect_is_usable(rect):
		return false
	return (
		rect.position.x >= 0.0
		and rect.position.y >= 0.0
		and rect.position.x + rect.size.x <= width
		and rect.position.y + rect.size.y <= height
	)


func _area_is_within_battlefield(area: BattleDeploymentArea) -> bool:
	if area == null:
		return false
	for pocket: BattleDeploymentPocket in area.pockets:
		if pocket == null:
			return false
		for point: Vector2 in pocket.polygon:
			if not contains_point(point):
				return false
	return true


# Spatial lookup for local cover decisions. Occupancy is checked live by the
# caller; this index stores positions only and rebuilds on structural edits.
const COVER_CELL_SIZE := 12.0
var _cover_grid: Dictionary = {}
var _cover_grid_revision: int = -1
var _cover_grid_content_revision: int = -1
var _cover_grid_count: int = -1

func get_cover_slot_ids_in_radius(origin: Vector2, radius: float) -> Array[String]:
	if not is_finite(radius):return get_sorted_cover_slot_ids()
	var ids: Array[String] = []
	if radius < 0.0 or not is_finite_point(origin):return ids
	if _cover_grid_revision != cover_slot_revision or _cover_grid_content_revision != content_revision or _cover_grid_count != cover_slots.size():
		_cover_grid.clear()
		for id: String in cover_slots:
			var slot: BattleCoverSlot = cover_slots[id]
			if slot == null or not is_finite_point(slot.position):continue
			var cell := Vector2i(floori(slot.position.x/COVER_CELL_SIZE),floori(slot.position.y/COVER_CELL_SIZE))
			if not _cover_grid.has(cell):_cover_grid[cell]=[]
			_cover_grid[cell].append(id)
		_cover_grid_revision=cover_slot_revision
		_cover_grid_content_revision=content_revision
		_cover_grid_count=cover_slots.size()
	# Include the tolerance used by existing is_equal_approx distance checks.
	var reach := radius + maxf(0.00002,absf(radius)*0.00002)
	var low := Vector2i(floori((origin.x-reach)/COVER_CELL_SIZE),floori((origin.y-reach)/COVER_CELL_SIZE))
	var high := Vector2i(floori((origin.x+reach)/COVER_CELL_SIZE),floori((origin.y+reach)/COVER_CELL_SIZE))
	for x in range(low.x,high.x+1):
		for y in range(low.y,high.y+1):
			for id: String in _cover_grid.get(Vector2i(x,y),[]):
				var slot: BattleCoverSlot=cover_slots[id]
				if origin.distance_squared_to(slot.position)<=reach*reach:ids.append(id)
	ids.sort()
	return ids

# Scoped spatial broad phase: rebuilt at each runtime/navigation scope and on
# authored revisions. Outside a scope, public queries still read all live data.
# This preserves direct edits between queries without a persistent stale cache.
const OBSTACLE_QUERY_CELL_SIZE := 8.0
var _obstacle_query_scope: bool = false
var _obstacle_query_revision: int = -1
var _obstacle_query_count: int = -1
var _obstacle_query_grid: Dictionary = {}

func begin_obstacle_query_scope() -> void:
	_segment_index_checked = false
	_obstacle_query_scope = true
	_obstacle_query_revision = -1

func end_obstacle_query_scope() -> void:
	_obstacle_query_scope = false

func get_obstacle_ids_at_point(point: Vector2) -> Array[String]:
	if not _obstacle_query_scope or not is_finite_point(point):
		return get_sorted_obstacle_ids()
	if _obstacle_query_revision != content_revision or _obstacle_query_count != obstacles.size():
		_obstacle_query_grid.clear()
		for id: String in get_sorted_obstacle_ids():
			var obstacle: BattleObstacle = obstacles[id]
			if obstacle == null or not obstacle.bounds_are_usable():
				continue
			var a: Vector2i = Vector2i((obstacle.bounds.position / OBSTACLE_QUERY_CELL_SIZE).floor())
			var z: Vector2i = Vector2i((obstacle.bounds.end / OBSTACLE_QUERY_CELL_SIZE).floor())
			for x in range(a.x, z.x + 1):
				for y in range(a.y, z.y + 1):
					var cell: Vector2i = Vector2i(x, y)
					if not _obstacle_query_grid.has(cell):
						var ids: Array[String] = []
						_obstacle_query_grid[cell] = ids
					_obstacle_query_grid[cell].append(id)
		_obstacle_query_revision = content_revision
		_obstacle_query_count = obstacles.size()
	var cell: Vector2i = Vector2i((point / OBSTACLE_QUERY_CELL_SIZE).floor())
	if _obstacle_query_grid.has(cell):
		return _obstacle_query_grid[cell]
	return []

# Conservative candidates for finite segments. Exact collision/LOS tests remain
# with their callers. Long queries use the full list to bound grid traversal.
func get_obstacle_ids_in_rect(query: Rect2) -> Array[String]:
	if not _obstacle_query_scope or not is_finite_point(query.position) or not is_finite_point(query.end):
		return get_sorted_obstacle_ids()
	var area: Rect2 = query.abs()
	var a: Vector2i = Vector2i((area.position / OBSTACLE_QUERY_CELL_SIZE).floor())
	var z: Vector2i = Vector2i((area.end / OBSTACLE_QUERY_CELL_SIZE).floor())
	if (z.x - a.x + 1) * (z.y - a.y + 1) > 64:
		return get_sorted_obstacle_ids()
	# Reuse the scoped index and its revision handling.
	get_obstacle_ids_at_point(area.position)
	var unique: Dictionary = {}
	for x in range(a.x, z.x + 1):
		for y in range(a.y, z.y + 1):
			for id: String in _obstacle_query_grid.get(Vector2i(x, y), []):
				unique[id] = true
	var ids: Array[String] = []
	for id: String in unique:
		ids.append(id)
	ids.sort()
	return ids

# Compare the live LOS geometry once per synchronous scope, retaining the tree
# when it is identical. Direct edits between scopes remain observable.
var _segment_index_checked: bool = false
var _segment_index_revision: int = -1
var _segment_index_count: int = -1
var _segment_index_rows: Array = []
var _segment_index_tree: Array = []

func get_obstacle_ids_for_segment(start: Vector2,end: Vector2) -> Array[String]:
	if not _obstacle_query_scope:
		return get_sorted_obstacle_ids()
	if not _segment_index_checked or _segment_index_revision != content_revision or _segment_index_count != obstacles.size():
		var rows: Array = []
		for id: String in get_sorted_obstacle_ids():
			var obstacle: BattleObstacle = obstacles[id]
			if obstacle != null and obstacle.blocks_line_of_sight and obstacle.bounds_are_usable():
				rows.append([obstacle.bounds,id])
		if rows != _segment_index_rows:
			_segment_index_rows = rows
			_segment_index_tree = RectangleQueryIndex.build(rows)
		_segment_index_checked = true
		_segment_index_revision = content_revision
		_segment_index_count = obstacles.size()
	return RectangleQueryIndex.query(_segment_index_tree,start,end)

