class_name BattleCoverService
extends RefCounted

const BattleState := preload("res://battle/core/battle_state.gd")
const BattleParticipant := preload("res://battle/core/battle_participant.gd")
const BattlefieldGeometry := preload("res://battle/geometry/battlefield_geometry.gd")
const BattleCoverSlot := preload("res://battle/geometry/battle_cover_slot.gd")
const BattleCoverResult := preload("res://battle/geometry/battle_cover_result.gd")
const BattleCoverQueryResult := preload("res://battle/geometry/battle_cover_query_result.gd")
const BattleNavigationService := preload("res://battle/navigation/battle_navigation_service.gd")
const BattleNavigationResult := preload("res://battle/navigation/battle_navigation_result.gd")
const BattleCoverPostureService := preload("res://battle/combat/battle_cover_posture_service.gd")

# Participant must be this close to a slot to occupy it. Reservation has no range.
const COVER_OCCUPANCY_EPSILON := 0.5


static func is_at_slot(participant: BattleParticipant, slot: BattleCoverSlot) -> bool:
	if participant == null or slot == null:
		return false
	if not participant.has_battle_position:
		return false
	if not BattlefieldGeometry.is_finite_point(participant.battle_position):
		return false
	if not BattlefieldGeometry.is_finite_point(slot.position):
		return false
	return participant.battle_position.distance_to(slot.position) <= COVER_OCCUPANCY_EPSILON


static func occupancy_is_valid(battle_state: BattleState, participant: BattleParticipant) -> bool:
	if participant == null or battle_state == null or battle_state.battlefield_geometry == null:
		return false
	if participant.occupied_cover_slot_id.is_empty():
		return false
	var slot: BattleCoverSlot = battle_state.battlefield_geometry.get_cover_slot(
		participant.occupied_cover_slot_id
	)
	if slot == null or not slot.is_valid():
		return false
	if slot.occupied_by_participant_id != participant.participant_id:
		return false
	return is_at_slot(participant, slot)


static func reserve_slot(
	battle_state: BattleState,
	participant_id: String,
	cover_slot_id: String
) -> BattleCoverResult:
	var prepared: Dictionary = _prepare_command(battle_state, participant_id, cover_slot_id)
	if prepared.has("failure"):
		return prepared["failure"] as BattleCoverResult
	var participant: BattleParticipant = prepared["participant"] as BattleParticipant
	var slot: BattleCoverSlot = prepared["slot"] as BattleCoverSlot
	if slot.is_occupied():
		return BattleCoverResult.failed(
			"cover_slot_occupied",
			"Battle cover failed: cover slot '%s' is occupied." % cover_slot_id,
			cover_slot_id,
			participant_id
		)
	if slot.reserved_by_participant_id == participant_id:
		return BattleCoverResult.succeeded(cover_slot_id, participant_id)
	if slot.is_reserved():
		return BattleCoverResult.failed(
			"cover_slot_reserved",
			"Battle cover failed: cover slot '%s' is reserved." % cover_slot_id,
			cover_slot_id,
			participant_id
		)
	_clear_reservation(battle_state, participant)
	slot.reserved_by_participant_id = participant_id
	participant.reserved_cover_slot_id = cover_slot_id
	return BattleCoverResult.succeeded(cover_slot_id, participant_id)


static func release_reservation(
	battle_state: BattleState,
	participant_id: String
) -> BattleCoverResult:
	var prepared: Dictionary = _prepare_participant(battle_state, participant_id)
	if prepared.has("failure"):
		return prepared["failure"] as BattleCoverResult
	var participant: BattleParticipant = prepared["participant"] as BattleParticipant
	var slot_id: String = participant.reserved_cover_slot_id
	if slot_id.is_empty():
		return BattleCoverResult.failed(
			"cover_slot_not_found",
			"Battle cover failed: participant '%s' has no cover reservation." % participant_id,
			"",
			participant_id
		)
	_clear_reservation(battle_state, participant)
	return BattleCoverResult.succeeded(slot_id, participant_id)


static func occupy_slot(
	battle_state: BattleState,
	participant_id: String,
	cover_slot_id: String
) -> BattleCoverResult:
	var prepared: Dictionary = _prepare_command(battle_state, participant_id, cover_slot_id)
	if prepared.has("failure"):
		return prepared["failure"] as BattleCoverResult
	var participant: BattleParticipant = prepared["participant"] as BattleParticipant
	var slot: BattleCoverSlot = prepared["slot"] as BattleCoverSlot
	if slot.occupied_by_participant_id == participant_id:
		if slot.reserved_by_participant_id == participant_id:
			slot.reserved_by_participant_id = ""
			if participant.reserved_cover_slot_id == cover_slot_id:
				participant.reserved_cover_slot_id = ""
		participant.occupied_cover_slot_id = cover_slot_id
		BattleCoverPostureService.ensure_occupied_posture(participant)
		return BattleCoverResult.succeeded(cover_slot_id, participant_id)
	if slot.is_occupied():
		return BattleCoverResult.failed(
			"cover_slot_occupied",
			"Battle cover failed: cover slot '%s' is occupied." % cover_slot_id,
			cover_slot_id,
			participant_id
		)
	if slot.is_reserved() and slot.reserved_by_participant_id != participant_id:
		return BattleCoverResult.failed(
			"cover_slot_reserved",
			"Battle cover failed: cover slot '%s' is reserved." % cover_slot_id,
			cover_slot_id,
			participant_id
		)
	if not is_at_slot(participant, slot):
		return BattleCoverResult.failed(
			"participant_not_at_slot",
			"Battle cover failed: participant '%s' is not at cover slot '%s'." % [participant_id, cover_slot_id],
			cover_slot_id,
			participant_id
		)
	_clear_occupancy(battle_state, participant)
	if slot.reserved_by_participant_id == participant_id:
		slot.reserved_by_participant_id = ""
		if participant.reserved_cover_slot_id == cover_slot_id:
			participant.reserved_cover_slot_id = ""
	slot.occupied_by_participant_id = participant_id
	participant.occupied_cover_slot_id = cover_slot_id
	BattleCoverPostureService.enter_tucked(participant)
	return BattleCoverResult.succeeded(cover_slot_id, participant_id)


static func vacate_slot(
	battle_state: BattleState,
	participant_id: String
) -> BattleCoverResult:
	var prepared: Dictionary = _prepare_participant(battle_state, participant_id)
	if prepared.has("failure"):
		return prepared["failure"] as BattleCoverResult
	var participant: BattleParticipant = prepared["participant"] as BattleParticipant
	var slot_id: String = participant.occupied_cover_slot_id
	if slot_id.is_empty():
		return BattleCoverResult.failed(
			"cover_slot_not_found",
			"Battle cover failed: participant '%s' has no cover occupancy." % participant_id,
			"",
			participant_id
		)
	_clear_occupancy(battle_state, participant)
	return BattleCoverResult.succeeded(slot_id, participant_id)


static func release_all_for_participant(
	battle_state: BattleState,
	participant_id: String
) -> BattleCoverResult:
	var prepared: Dictionary = _prepare_participant(battle_state, participant_id, false)
	if prepared.has("failure"):
		return prepared["failure"] as BattleCoverResult
	var participant: BattleParticipant = prepared["participant"] as BattleParticipant
	var occupied_id: String = participant.occupied_cover_slot_id
	var reserved_id: String = participant.reserved_cover_slot_id
	_clear_occupancy(battle_state, participant)
	_clear_reservation(battle_state, participant)
	var reported_id: String = occupied_id
	if reported_id.is_empty():
		reported_id = reserved_id
	return BattleCoverResult.succeeded(reported_id, participant_id)


static func get_available_slots(battle_state: BattleState) -> BattleCoverQueryResult:
	var geometry_result: Dictionary = _require_geometry(battle_state)
	if geometry_result.has("failure"):
		return geometry_result["failure"] as BattleCoverQueryResult
	var geometry: BattlefieldGeometry = geometry_result["geometry"] as BattlefieldGeometry
	var available: Array[String] = []
	for slot_id: String in geometry.get_sorted_cover_slot_ids():
		var slot: BattleCoverSlot = geometry.get_cover_slot(slot_id)
		if slot != null and slot.is_available():
			available.append(slot_id)
	return BattleCoverQueryResult.succeeded(available)


static func find_nearest_available_slot(
	battle_state: BattleState,
	participant_id: String,
	require_reachable: bool = false
) -> BattleCoverQueryResult:
	var prepared: Dictionary = _prepare_participant(battle_state, participant_id)
	if prepared.has("failure"):
		var command_failure: BattleCoverResult = prepared["failure"] as BattleCoverResult
		return BattleCoverQueryResult.failed(command_failure.error_code, command_failure.error_message)
	var participant: BattleParticipant = prepared["participant"] as BattleParticipant
	var geometry: BattlefieldGeometry = battle_state.battlefield_geometry
	var best_id: String = ""
	var best_distance: float = INF
	for slot_id: String in geometry.get_sorted_cover_slot_ids():
		var slot: BattleCoverSlot = geometry.get_cover_slot(slot_id)
		if slot == null or not slot.is_available():
			continue
		if require_reachable and not _slot_is_reachable(battle_state, participant, slot):
			continue
		var distance: float = participant.battle_position.distance_squared_to(slot.position)
		if not is_finite(distance):
			continue
		if best_id.is_empty() or distance < best_distance:
			best_id = slot_id
			best_distance = distance
	if best_id.is_empty():
		return BattleCoverQueryResult.succeeded()
	var ids: Array[String] = [best_id]
	return BattleCoverQueryResult.succeeded(ids, best_id)


static func _slot_is_reachable(
	battle_state: BattleState,
	participant: BattleParticipant,
	slot: BattleCoverSlot
) -> bool:
	if participant == null or slot == null:
		return false
	var navigation: BattleNavigationResult = BattleNavigationService.find_path(
		battle_state,
		participant.battle_position,
		slot.position
	)
	return navigation != null and navigation.success


static func _prepare_command(
	battle_state: BattleState,
	participant_id: String,
	cover_slot_id: String
) -> Dictionary:
	var prepared: Dictionary = _prepare_participant(battle_state, participant_id)
	if prepared.has("failure"):
		return prepared
	if cover_slot_id.is_empty():
		prepared["failure"] = BattleCoverResult.failed(
			"cover_slot_not_found",
			"Battle cover failed: cover slot id is empty.",
			"",
			participant_id
		)
		return prepared
	var geometry: BattlefieldGeometry = battle_state.battlefield_geometry
	var slot: BattleCoverSlot = geometry.get_cover_slot(cover_slot_id)
	if slot == null or not slot.is_valid():
		prepared["failure"] = BattleCoverResult.failed(
			"cover_slot_not_found" if slot == null else "invalid_cover_slot",
			"Battle cover failed: cover slot '%s' is %s." % [
				cover_slot_id,
				"missing" if slot == null else "invalid"
			],
			cover_slot_id,
			participant_id
		)
		return prepared
	prepared["slot"] = slot
	return prepared


static func _prepare_participant(
	battle_state: BattleState,
	participant_id: String,
	require_eligible: bool = true
) -> Dictionary:
	var prepared: Dictionary = {}
	var geometry_result: Dictionary = _require_geometry(battle_state)
	if geometry_result.has("failure"):
		var query_failure: BattleCoverQueryResult = geometry_result["failure"] as BattleCoverQueryResult
		prepared["failure"] = BattleCoverResult.failed(
			query_failure.error_code,
			query_failure.error_message,
			"",
			participant_id
		)
		return prepared
	if participant_id.is_empty() or battle_state.get_participant(participant_id) == null:
		prepared["failure"] = BattleCoverResult.failed(
			"participant_not_found",
			"Battle cover failed: participant '%s' was not found." % participant_id,
			"",
			participant_id
		)
		return prepared
	var participant: BattleParticipant = battle_state.get_participant(participant_id)
	if require_eligible and not _participant_is_eligible(participant):
		prepared["failure"] = BattleCoverResult.failed(
			"participant_not_eligible",
			"Battle cover failed: participant '%s' is not eligible to use cover." % participant_id,
			"",
			participant_id
		)
		return prepared
	prepared["participant"] = participant
	return prepared


static func _require_geometry(battle_state: BattleState) -> Dictionary:
	var prepared: Dictionary = {}
	if battle_state == null:
		prepared["failure"] = BattleCoverQueryResult.failed(
			"null_battle_state",
			"Battle cover failed: battle_state is null."
		)
		return prepared
	if battle_state.battlefield_geometry == null:
		prepared["failure"] = BattleCoverQueryResult.failed(
			"missing_battlefield_geometry",
			"Battle cover failed: battlefield geometry is missing."
		)
		return prepared
	if not battle_state.has_valid_geometry():
		prepared["failure"] = BattleCoverQueryResult.failed(
			"invalid_battlefield_geometry",
			"Battle cover failed: battlefield geometry is invalid."
		)
		return prepared
	prepared["geometry"] = battle_state.battlefield_geometry
	return prepared


static func _participant_is_eligible(participant: BattleParticipant) -> bool:
	if participant == null or not participant.is_alive:
		return false
	if not participant.has_battle_position:
		return false
	return is_finite(participant.battle_position.x) and is_finite(participant.battle_position.y)


static func _clear_reservation(battle_state: BattleState, participant: BattleParticipant) -> void:
	if participant == null or battle_state == null or battle_state.battlefield_geometry == null:
		return
	var slot_id: String = participant.reserved_cover_slot_id
	var freed: bool = false
	if not slot_id.is_empty():
		var slot: BattleCoverSlot = battle_state.battlefield_geometry.get_cover_slot(slot_id)
		if slot != null and slot.reserved_by_participant_id == participant.participant_id:
			slot.reserved_by_participant_id = ""
			freed = true
	participant.reserved_cover_slot_id = ""
	if freed:
		_bump_cover_occupancy_revision(battle_state)


static func _clear_occupancy(battle_state: BattleState, participant: BattleParticipant) -> void:
	if participant == null or battle_state == null or battle_state.battlefield_geometry == null:
		return
	var slot_id: String = participant.occupied_cover_slot_id
	var freed: bool = false
	if not slot_id.is_empty():
		var slot: BattleCoverSlot = battle_state.battlefield_geometry.get_cover_slot(slot_id)
		if slot != null and slot.occupied_by_participant_id == participant.participant_id:
			slot.occupied_by_participant_id = ""
			freed = true
	participant.occupied_cover_slot_id = ""
	BattleCoverPostureService.clear(participant)
	if freed:
		_bump_cover_occupancy_revision(battle_state)


static func _bump_cover_occupancy_revision(battle_state: BattleState) -> void:
	if battle_state == null:
		return
	battle_state.cover_occupancy_revision += 1

battle/geometry/battle_cover_slot.gd:
class_name BattleCoverSlot
extends RefCounted

# Authored occupiable cover position. Metadata only; not a collision shape.
var cover_slot_id: String = ""
var cover_object_id: String = ""
var position: Vector2 = Vector2.ZERO
# Unit vector toward the protected approach. Attackers from this side receive cover benefit.
var facing_direction: Vector2 = Vector2.ZERO
var occupied_by_participant_id: String = ""
var reserved_by_participant_id: String = ""


func _init(
	p_cover_slot_id: String = "",
	p_cover_object_id: String = "",
	p_position: Vector2 = Vector2.ZERO,
	p_facing_direction: Vector2 = Vector2.ZERO
) -> void:
	cover_slot_id = p_cover_slot_id
	cover_object_id = p_cover_object_id
	position = p_position
	if is_finite(p_facing_direction.x) and is_finite(p_facing_direction.y) and not p_facing_direction.is_equal_approx(Vector2.ZERO):
		facing_direction = p_facing_direction.normalized()
	else:
		facing_direction = p_facing_direction


func set_facing_direction(direction: Vector2) -> bool:
	if not is_finite(direction.x) or not is_finite(direction.y):
		push_error("BattleCoverSlot.set_facing_direction: direction is not finite.")
		return false
	if direction.is_equal_approx(Vector2.ZERO):
		push_error("BattleCoverSlot.set_facing_direction: direction is zero.")
		return false
	facing_direction = direction.normalized()
	return true


func is_valid() -> bool:
	if cover_slot_id.is_empty() or cover_object_id.is_empty():
		return false
	if not is_finite(position.x) or not is_finite(position.y):
		return false
	if not is_finite(facing_direction.x) or not is_finite(facing_direction.y):
		return false
	if facing_direction.is_equal_approx(Vector2.ZERO):
		return false
	return is_equal_approx(facing_direction.length(), 1.0)


func is_occupied() -> bool:
	return not occupied_by_participant_id.is_empty()


func is_reserved() -> bool:
	return not reserved_by_participant_id.is_empty()


func is_available() -> bool:
	return not is_occupied() and not is_reserved()

battle/geometry/battle_deployment_area.g:
class_name BattleDeploymentArea
extends RefCounted

# Side deployment area as one or more polygonal pockets.
# Empty pockets mean the legacy axis-aligned rect is the authority.
# Point-in-area is the legality query; bounding_rect is a coarse envelope only.

const BattleDeploymentPocket := preload("res://battle/geometry/battle_deployment_pocket.gd")

var pockets: Array[BattleDeploymentPocket] = []


func has_pockets() -> bool:
	return not pockets.is_empty()


func is_valid() -> bool:
	if pockets.is_empty():
		return true
	var seen: Dictionary = {}
	for pocket: BattleDeploymentPocket in pockets:
		if pocket == null or not pocket.is_valid():
			return false
		if seen.has(pocket.pocket_id):
			return false
		seen[pocket.pocket_id] = true
	return _rect_is_usable(bounding_rect())


func add_pocket(pocket: BattleDeploymentPocket) -> bool:
	if pocket == null or not pocket.is_valid():
		return false
	for existing: BattleDeploymentPocket in pockets:
		if existing != null and existing.pocket_id == pocket.pocket_id:
			return false
	pockets.append(pocket)
	return true


func contains_point(point: Vector2) -> bool:
	if not has_pockets():
		return false
	for pocket: BattleDeploymentPocket in pockets:
		if pocket != null and pocket.contains_point(point):
			return true
	return false


func bounding_rect() -> Rect2:
	var first: bool = true
	var min_x: float = 0.0
	var min_y: float = 0.0
	var max_x: float = 0.0
	var max_y: float = 0.0
	for pocket: BattleDeploymentPocket in pockets:
		if pocket == null:
			continue
		var rect: Rect2 = pocket.bounding_rect()
		if not _rect_is_usable(rect):
			continue
		if first:
			min_x = rect.position.x
			min_y = rect.position.y
			max_x = rect.position.x + rect.size.x
			max_y = rect.position.y + rect.size.y
			first = false
			continue
		min_x = minf(min_x, rect.position.x)
		min_y = minf(min_y, rect.position.y)
		max_x = maxf(max_x, rect.position.x + rect.size.x)
		max_y = maxf(max_y, rect.position.y + rect.size.y)
	if first:
		return Rect2()
	return Rect2(Vector2(min_x, min_y), Vector2(max_x - min_x, max_y - min_y))


func centroid() -> Vector2:
	if pockets.is_empty():
		return Vector2.ZERO
	var sum: Vector2 = Vector2.ZERO
	var count: int = 0
	for pocket: BattleDeploymentPocket in pockets:
		if pocket == null or pocket.polygon.size() < 3:
			continue
		sum += pocket.centroid()
		count += 1
	if count <= 0:
		return Vector2.ZERO
	return sum / float(count)


func get_sorted_pockets() -> Array[BattleDeploymentPocket]:
	var copied: Array[BattleDeploymentPocket] = []
	for pocket: BattleDeploymentPocket in pockets:
		copied.append(pocket)
	copied.sort_custom(_sort_pockets)
	return copied


func pocket_bounding_rects() -> Array[Rect2]:
	var rects: Array[Rect2] = []
	for pocket: BattleDeploymentPocket in get_sorted_pockets():
		if pocket == null:
			continue
		var rect: Rect2 = pocket.bounding_rect()
		if _rect_is_usable(rect):
			rects.append(rect)
	return rects


static func _rect_is_usable(rect: Rect2) -> bool:
	if not is_finite(rect.position.x) or not is_finite(rect.position.y):
		return false
	if not is_finite(rect.size.x) or not is_finite(rect.size.y):
		return false
	return rect.size.x > 0.0 and rect.size.y > 0.0


static func _sort_pockets(left: BattleDeploymentPocket, right: BattleDeploymentPocket) -> bool:
	var left_id: String = ""
	var right_id: String = ""
	if left != null:
		left_id = left.pocket_id
	if right != null:
		right_id = right.pocket_id
	return left_id < right_id

battle/geometry/battle_deployment_pocket:
class_name BattleDeploymentPocket
extends RefCounted

# One polygonal deployment pocket. Query-only geometry.
# Not a visual overlay and not a second legality authority.

var pocket_id: String = ""
var polygon: PackedVector2Array = PackedVector2Array()


func _init(p_pocket_id: String = "", p_polygon: PackedVector2Array = PackedVector2Array()) -> void:
	pocket_id = p_pocket_id
	polygon = p_polygon


func is_valid() -> bool:
	if pocket_id.is_empty():
		return false
	if polygon.size() < 3:
		return false
	for point: Vector2 in polygon:
		if not is_finite(point.x) or not is_finite(point.y):
			return false
	return bounding_rect().size.x > 0.0 and bounding_rect().size.y > 0.0


func contains_point(point: Vector2) -> bool:
	if not is_finite(point.x) or not is_finite(point.y):
		return false
	if polygon.size() < 3:
		return false
	return Geometry2D.is_point_in_polygon(point, polygon)


func bounding_rect() -> Rect2:
	if polygon.size() < 1:
		return Rect2()
	var min_x: float = polygon[0].x
	var min_y: float = polygon[0].y
	var max_x: float = polygon[0].x
	var max_y: float = polygon[0].y
	var index: int = 1
	while index < polygon.size():
		var point: Vector2 = polygon[index]
		min_x = minf(min_x, point.x)
		min_y = minf(min_y, point.y)
		max_x = maxf(max_x, point.x)
		max_y = maxf(max_y, point.y)
		index += 1
	return Rect2(Vector2(min_x, min_y), Vector2(max_x - min_x, max_y - min_y))


func centroid() -> Vector2:
	if polygon.size() < 1:
		return Vector2.ZERO
	var sum: Vector2 = Vector2.ZERO
	for point: Vector2 in polygon:
		sum += point
	return sum / float(polygon.size())

battle/geometry/battle_obstacle.gd:
class_name BattleObstacle
extends RefCounted

var obstacle_id: String = ""
var bounds: Rect2 = Rect2()
var blocks_movement: bool = true
var blocks_line_of_sight: bool = true
var presentation_kind: String = ""


func _init(
	p_obstacle_id: String = "",
	p_bounds: Rect2 = Rect2(),
	p_blocks_movement: bool = true,
	p_blocks_line_of_sight: bool = true,
	p_presentation_kind: String = ""
) -> void:
	obstacle_id = p_obstacle_id
	bounds = p_bounds
	blocks_movement = p_blocks_movement
	blocks_line_of_sight = p_blocks_line_of_sight
	presentation_kind = p_presentation_kind


func is_valid() -> bool:
	if obstacle_id.is_empty():
		return false
	return bounds_are_usable()


func bounds_are_usable() -> bool:
	if not is_finite(bounds.position.x) or not is_finite(bounds.position.y):
		return false
	if not is_finite(bounds.size.x) or not is_finite(bounds.size.y):
		return false
	return bounds.size.x > 0.0 and bounds.size.y > 0.0


func contains_point(point: Vector2) -> bool:
	if not is_finite(point.x) or not is_finite(point.y):
		return false
	if not bounds_are_usable():
		return false
	return (
		point.x >= bounds.position.x
		and point.y >= bounds.position.y
		and point.x <= bounds.position.x + bounds.size.x
		and point.y <= bounds.position.y + bounds.size.y
	)

battle/geometry/battle_spatial_service.g:
class_name BattleSpatialService
extends RefCounted

const BattleState := preload("res://battle/core/battle_state.gd")
const BattlefieldGeometry := preload("res://battle/geometry/battlefield_geometry.gd")
const BattleObstacle := preload("res://battle/geometry/battle_obstacle.gd")
const BattleVehicleBodyService := preload("res://battle/vehicles/battle_vehicle_body_service.gd")
const BattleVehicle := preload("res://battle/core/battle_vehicle.gd")
const BattleSpatialResult := preload("res://battle/geometry/battle_spatial_result.gd")

# Participants are treated as points at battle_position. A later body radius can
# be introduced here without changing movement intent or runtime architecture.
const COLLISION_EPSILON := 0.0001
const NO_HIT := INF


static func resolve_translation(
	battle_state: BattleState,
	start_position: Vector2,
	requested_displacement: Vector2
) -> BattleSpatialResult:
	if battle_state == null:
		return BattleSpatialResult.failed(
			"null_battle_state",
			"Battle spatial resolution failed: battle_state is null.",
			start_position,
			requested_displacement
		)
	if battle_state.battlefield_geometry == null:
		return BattleSpatialResult.failed(
			"missing_battlefield_geometry",
			"Battle spatial resolution failed: battlefield geometry is missing.",
			start_position,
			requested_displacement
		)
	var geometry: BattlefieldGeometry = battle_state.battlefield_geometry
	if not battle_state.has_valid_geometry():
		return BattleSpatialResult.failed(
			"invalid_battlefield_geometry",
			"Battle spatial resolution failed: battlefield geometry is invalid.",
			start_position,
			requested_displacement
		)
	if not BattlefieldGeometry.is_finite_point(start_position):
		return BattleSpatialResult.failed(
			"invalid_start_position",
			"Battle spatial resolution failed: start position is invalid.",
			start_position,
			requested_displacement
		)
	if not BattlefieldGeometry.is_finite_point(requested_displacement):
		return BattleSpatialResult.failed(
			"invalid_displacement",
			"Battle spatial resolution failed: requested displacement is invalid.",
			start_position,
			requested_displacement
		)
	if not geometry.contains_point(start_position):
		return BattleSpatialResult.failed(
			"start_outside_battlefield",
			"Battle spatial resolution failed: start position is outside the battlefield.",
			start_position,
			requested_displacement
		)
	var inside_obstacle_id: String = _blocking_obstacle_at(geometry, start_position)
	if not inside_obstacle_id.is_empty():
		return BattleSpatialResult.failed(
			"start_inside_blocking_obstacle",
			"Battle spatial resolution failed: start position is inside blocking obstacle '%s'." % inside_obstacle_id,
			start_position,
			requested_displacement,
			inside_obstacle_id
		)
	var inside_vehicle_id: String = BattleVehicleBodyService.blocking_vehicle_id_at(
		battle_state,
		start_position
	)
	if not inside_vehicle_id.is_empty():
		return BattleSpatialResult.failed(
			"start_inside_vehicle",
			"Battle spatial resolution failed: start position is inside vehicle '%s'." % inside_vehicle_id,
			start_position,
			requested_displacement,
			inside_vehicle_id
		)
	if requested_displacement.is_equal_approx(Vector2.ZERO):
		return BattleSpatialResult.succeeded(
			start_position,
			requested_displacement,
			Vector2.ZERO,
			start_position,
			false,
			""
		)
	return _resolve_legal_translation(battle_state, geometry, start_position, requested_displacement)


# Raw AABB slab overlap for start + t * displacement.
# Returns Vector2(t_enter, t_exit). A miss is encoded as t_enter > t_exit.
static func segment_aabb_overlap_t(
	start_position: Vector2,
	displacement: Vector2,
	rect: Rect2
) -> Vector2:
	var miss: Vector2 = Vector2(INF, -INF)
	if not BattlefieldGeometry.rect_is_usable(rect):
		return miss
	var min_x: float = rect.position.x
	var min_y: float = rect.position.y
	var max_x: float = rect.position.x + rect.size.x
	var max_y: float = rect.position.y + rect.size.y
	var t_enter: float = -INF
	var t_exit: float = INF
	if is_zero_approx(displacement.x):
		if start_position.x < min_x or start_position.x > max_x:
			return miss
	else:
		var t1: float = (min_x - start_position.x) / displacement.x
		var t2: float = (max_x - start_position.x) / displacement.x
		if t1 > t2:
			var swap_t: float = t1
			t1 = t2
			t2 = swap_t
		t_enter = maxf(t_enter, t1)
		t_exit = minf(t_exit, t2)
	if is_zero_approx(displacement.y):
		if start_position.y < min_y or start_position.y > max_y:
			return miss
	else:
		var t1y: float = (min_y - start_position.y) / displacement.y
		var t2y: float = (max_y - start_position.y) / displacement.y
		if t1y > t2y:
			var swap_y: float = t1y
			t1y = t2y
			t2y = swap_y
		t_enter = maxf(t_enter, t1y)
		t_exit = minf(t_exit, t2y)
	if t_enter > t_exit:
		return miss
	return Vector2(t_enter, t_exit)


static func is_translation_clear(
	battle_state: BattleState,
	start_position: Vector2,
	destination: Vector2
) -> bool:
	if not BattlefieldGeometry.is_finite_point(start_position):
		return false
	if not BattlefieldGeometry.is_finite_point(destination):
		return false
	var displacement: Vector2 = destination - start_position
	if not BattlefieldGeometry.is_finite_point(displacement):
		return false
	var result: BattleSpatialResult = resolve_translation(
		battle_state,
		start_position,
		displacement
	)
	if result == null or not result.success:
		return false
	if result.was_blocked:
		return false
	return result.final_position.is_equal_approx(destination)


# Boolean clearance for visibility-graph edges. Same blockers as
# is_translation_clear, without allocating a spatial result or searching
# for the earliest hit. assume_legal_endpoints skips point-in-blocker
# retests when both ends were already accepted as navigation nodes.
static func is_open_segment(
	battle_state: BattleState,
	start_position: Vector2,
	destination: Vector2,
	assume_legal_endpoints: bool = false
) -> bool:
	if battle_state == null or battle_state.battlefield_geometry == null:
		return false
	if not BattlefieldGeometry.is_finite_point(start_position):
		return false
	if not BattlefieldGeometry.is_finite_point(destination):
		return false
	var geometry: BattlefieldGeometry = battle_state.battlefield_geometry
	if not battle_state.has_valid_geometry():
		return false
	if not assume_legal_endpoints:
		if not geometry.contains_point(start_position) or not geometry.contains_point(destination):
			return false
	if start_position.is_equal_approx(destination):
		return true
	if not assume_legal_endpoints:
		if not _blocking_obstacle_at(geometry, start_position).is_empty():
			return false
		if not BattleVehicleBodyService.blocking_vehicle_id_at(battle_state, start_position).is_empty():
			return false
	var displacement: Vector2 = destination - start_position
	if not BattlefieldGeometry.is_finite_point(displacement):
		return false
	for obstacle_id: String in geometry.get_obstacle_ids_in_rect(Rect2(start_position.min(destination), displacement.abs()).grow(COLLISION_EPSILON)):
		var obstacle: BattleObstacle = geometry.obstacles[obstacle_id]
		if obstacle == null or not obstacle.blocks_movement:
			continue
		if not obstacle.bounds_are_usable():
			continue
		var hit_t: float = _segment_rect_entry_t(start_position, displacement, obstacle.bounds)
		if is_inf(hit_t):
			continue
		if hit_t < 0.0 or hit_t > 1.0:
			continue
		return false
	for vehicle_id: String in battle_state.vehicles:
		var vehicle: BattleVehicle = battle_state.vehicles[vehicle_id]
		var hit_t: float = BattleVehicleBodyService.segment_entry_t(
			vehicle,
			start_position,
			displacement
		)
		if is_inf(hit_t):
			continue
		if hit_t < 0.0 or hit_t > 1.0:
			continue
		return false
	if not assume_legal_endpoints:
		if not _blocking_obstacle_at(geometry, destination).is_empty():
			return false
		if not BattleVehicleBodyService.blocking_vehicle_id_at(battle_state, destination).is_empty():
			return false
	return true


static func _resolve_legal_translation(
	battle_state: BattleState,
	geometry: BattlefieldGeometry,
	start_position: Vector2,
	requested_displacement: Vector2
) -> BattleSpatialResult:
	var requested_end: Vector2 = start_position + requested_displacement
	var best_t: float = 1.0
	var best_obstacle_id: String = ""
	var blocked_by_boundary: bool = false
	var boundary_t: float = _battlefield_exit_t(geometry, start_position, requested_displacement)
	if boundary_t < 1.0:
		best_t = boundary_t
		blocked_by_boundary = true
	var obstacle_ids: Array[String] = geometry.get_obstacle_ids_in_rect(Rect2(start_position.min(requested_end), requested_displacement.abs()).grow(COLLISION_EPSILON))
	for obstacle_id: String in obstacle_ids:
		var obstacle: BattleObstacle = geometry.get_obstacle(obstacle_id)
		if obstacle == null or not obstacle.blocks_movement:
			continue
		if not obstacle.bounds_are_usable():
			continue
		var hit_t: float = _segment_rect_entry_t(start_position, requested_displacement, obstacle.bounds)
		if is_inf(hit_t):
			continue
		if hit_t < 0.0 or hit_t > 1.0:
			continue
		if _is_earlier_hit(hit_t, obstacle_id, best_t, best_obstacle_id, blocked_by_boundary):
			best_t = hit_t
			best_obstacle_id = obstacle_id
			blocked_by_boundary = false
	var vehicle_ids: Array[String] = []
	for vehicle_id: String in battle_state.vehicles:
		vehicle_ids.append(vehicle_id)
	vehicle_ids.sort()
	for vehicle_id: String in vehicle_ids:
		var vehicle: BattleVehicle = battle_state.get_vehicle(vehicle_id)
		var hit_t: float = BattleVehicleBodyService.segment_entry_t(
			vehicle,
			start_position,
			requested_displacement
		)
		if is_inf(hit_t):
			continue
		if hit_t < 0.0 or hit_t > 1.0:
			continue
		if _is_earlier_hit(hit_t, vehicle_id, best_t, best_obstacle_id, blocked_by_boundary):
			best_t = hit_t
			best_obstacle_id = vehicle_id
			blocked_by_boundary = false
	var was_blocked: bool = blocked_by_boundary or not best_obstacle_id.is_empty()
	var final_position: Vector2 = requested_end
	if was_blocked:
		final_position = _position_at_hit(
			battle_state,
			geometry,
			start_position,
			requested_displacement,
			best_t,
			best_obstacle_id
		)
	final_position = _clamp_to_battlefield(geometry, final_position)
	if not geometry.contains_point(final_position):
		final_position = start_position
	if not _blocking_obstacle_at(geometry, final_position).is_empty():
		final_position = start_position
	if not BattleVehicleBodyService.blocking_vehicle_id_at(battle_state, final_position).is_empty():
		final_position = start_position
	var resolved_displacement: Vector2 = final_position - start_position
	if not BattlefieldGeometry.is_finite_point(resolved_displacement) or not BattlefieldGeometry.is_finite_point(final_position):
		return BattleSpatialResult.succeeded(
			start_position,
			requested_displacement,
			Vector2.ZERO,
			start_position,
			true,
			best_obstacle_id
		)
	return BattleSpatialResult.succeeded(
		start_position,
		requested_displacement,
		resolved_displacement,
		final_position,
		was_blocked,
		best_obstacle_id
	)


static func _is_earlier_hit(
	hit_t: float,
	obstacle_id: String,
	best_t: float,
	best_obstacle_id: String,
	blocked_by_boundary: bool
) -> bool:
	if hit_t < best_t and not is_equal_approx(hit_t, best_t):
		return true
	if not is_equal_approx(hit_t, best_t):
		return false
	if blocked_by_boundary or best_obstacle_id.is_empty():
		return true
	return obstacle_id < best_obstacle_id


static func _position_at_hit(
	battle_state: BattleState,
	geometry: BattlefieldGeometry,
	start_position: Vector2,
	requested_displacement: Vector2,
	hit_t: float,
	obstacle_id: String
) -> Vector2:
	var t: float = hit_t
	if t < 0.0:
		t = 0.0
	if t > 1.0:
		t = 1.0
	if not obstacle_id.is_empty():
		var path_length: float = requested_displacement.length()
		if not is_finite(path_length) or path_length <= COLLISION_EPSILON:
			return start_position
		var t_back: float = COLLISION_EPSILON / path_length
		t -= t_back
		if t < 0.0:
			t = 0.0
	var point: Vector2 = start_position + requested_displacement * t
	if not obstacle_id.is_empty():
		var obstacle: BattleObstacle = geometry.get_obstacle(obstacle_id)
		if obstacle != null and obstacle.contains_point(point):
			return start_position
		if battle_state != null and battle_state.has_vehicle(obstacle_id):
			var vehicle: BattleVehicle = battle_state.get_vehicle(obstacle_id)
			if BattleVehicleBodyService.contains_point(vehicle, point):
				return start_position
	return point


static func _battlefield_exit_t(
	geometry: BattlefieldGeometry,
	start_position: Vector2,
	displacement: Vector2
) -> float:
	var requested_end: Vector2 = start_position + displacement
	if geometry.contains_point(requested_end):
		return 1.0
	var t: float = 1.0
	if displacement.x > 0.0:
		t = minf(t, (geometry.width - start_position.x) / displacement.x)
	elif displacement.x < 0.0:
		t = minf(t, (0.0 - start_position.x) / displacement.x)
	if displacement.y > 0.0:
		t = minf(t, (geometry.height - start_position.y) / displacement.y)
	elif displacement.y < 0.0:
		t = minf(t, (0.0 - start_position.y) / displacement.y)
	if t < 0.0:
		return 0.0
	if t > 1.0:
		return 1.0
	return t


static func _segment_rect_entry_t(
	start_position: Vector2,
	displacement: Vector2,
	rect: Rect2
) -> float:
	var segment_bounds: Rect2 = Rect2(start_position.min(start_position + displacement), displacement.abs()).grow(COLLISION_EPSILON)
	if not rect.intersects(segment_bounds, true):
		return NO_HIT
	var overlap: Vector2 = segment_aabb_overlap_t(start_position, displacement, rect)
	var t_enter: float = overlap.x
	var t_exit: float = overlap.y
	if t_enter > t_exit:
		return NO_HIT
	if t_exit < 0.0:
		return NO_HIT
	if t_enter > 1.0:
		return NO_HIT
	if t_enter <= 0.0:
		return 0.0
	return t_enter


static func _blocking_obstacle_at(geometry: BattlefieldGeometry, point: Vector2) -> String:
	return geometry.get_movement_blocking_obstacle_id_at(point)

static func _clamp_to_battlefield(geometry: BattlefieldGeometry, point: Vector2) -> Vector2:
	if not BattlefieldGeometry.is_finite_point(point):
		return point
	return Vector2(
		clampf(point.x, 0.0, geometry.width),
		clampf(point.y, 0.0, geometry.height)
	)

