class_name TacticalParticipantVisual
extends RefCounted

# Shared presentation facing / origin. Does not own combat or hit-testing.

const BattleState := preload("res://battle/core/battle_state.gd")
const BattleParticipant := preload("res://battle/core/battle_participant.gd")
const BattleCoverSlot := preload("res://battle/geometry/battle_cover_slot.gd")
const BattleAttackEvent := preload("res://battle/combat/battle_attack_event.gd")

const COVER_OCCUPY_VISUAL_NUDGE_PIXELS := 3.2
const FACING_EPSILON := 0.001
const LOCOMOTION_SPEED_EPSILON := 0.35
const DIRECTION_HYSTERESIS_DOT := 0.22
const FIRE_PRESENTATION_SECONDS := 0.32
const NOMINAL_WALK_SPEED := 3.6
const WALK_SPEED_SCALE_MIN := 0.72
const WALK_SPEED_SCALE_MAX := 1.28
const DIR_N := "n"
const DIR_NE := "ne"
const DIR_E := "e"
const DIR_SE := "se"
const DIR_S := "s"
const DIR_SW := "sw"
const DIR_W := "w"
const DIR_NW := "nw"
const DIRECTION_IDS_8: Array[String] = [
	DIR_N, DIR_NE, DIR_E, DIR_SE, DIR_S, DIR_SW, DIR_W, DIR_NW
]
const IMPLEMENTED_DIRECTION_IDS: Array[String] = [
	DIR_N, DIR_NE, DIR_E, DIR_SE, DIR_S, DIR_SW, DIR_W, DIR_NW
]


static func facing(battle_state: BattleState, participant: BattleParticipant) -> Vector2:
	if participant == null:
		return Vector2.UP
	if participant.has_target_participant and battle_state != null:
		var target: BattleParticipant = battle_state.get_participant(participant.target_participant_id)
		if target != null and target.has_battle_position:
			var to_target: Vector2 = target.battle_position - participant.battle_position
			if is_usable(to_target):
				return to_target.normalized()
	if is_usable(participant.velocity):
		return participant.velocity.normalized()
	if is_usable(participant.movement_intent):
		return participant.movement_intent.normalized()
	if participant.has_movement_target_position:
		var to_move: Vector2 = participant.movement_target_position - participant.battle_position
		if is_usable(to_move):
			return to_move.normalized()
	if participant.has_active_navigation_path():
		var to_waypoint: Vector2 = participant.get_current_navigation_waypoint() - participant.battle_position
		if is_usable(to_waypoint):
			return to_waypoint.normalized()
	if participant.has_occupied_cover_slot() and battle_state != null and battle_state.battlefield_geometry != null:
		var slot: BattleCoverSlot = battle_state.battlefield_geometry.get_cover_slot(
			participant.occupied_cover_slot_id
		)
		if slot != null and is_usable(slot.facing_direction):
			return slot.facing_direction.normalized()
	var from_event: Vector2 = _latest_source_shot_facing(battle_state, participant)
	if is_usable(from_event):
		return from_event.normalized()
	if battle_state != null and participant.side_id == battle_state.defender_side_id:
		return Vector2.DOWN
	return Vector2.UP


static func view_origin(
	battle_state: BattleState,
	participant: BattleParticipant,
	pixels_per_unit: float
) -> Vector2:
	if participant == null or not participant.has_battle_position:
		return Vector2.ZERO
	var view_pos: Vector2 = participant.battle_position * pixels_per_unit
	if battle_state != null and battle_state.battlefield_geometry != null and battle_state.battlefield_geometry.authored_layout_id in ["dead_street_dusk_v1", "river_suspension_bridge_v1", "whittaker_estate_v1", "doble_ocho_yard_v1","freight_exchange_v1"]:
		view_pos.y *= 0.75
	# Harold cover positions include body clearance; aiming must not slide feet into scenery.
	if battle_state != null and battle_state.battlefield_geometry != null and battle_state.battlefield_geometry.authored_layout_id in ["dead_street_dusk_v1", "doble_ocho_yard_v1","freight_exchange_v1"]:
		return view_pos
	if not participant.has_occupied_cover_slot():
		return view_pos
	var face: Vector2 = facing(battle_state, participant)
	if not is_usable(face):
		return view_pos
	return view_pos + face.normalized() * COVER_OCCUPY_VISUAL_NUDGE_PIXELS


static func is_usable(direction: Vector2) -> bool:
	return direction.length_squared() > FACING_EPSILON


static func is_locomoting(participant: BattleParticipant) -> bool:
	if participant == null:
		return false
	return participant.velocity.length() >= LOCOMOTION_SPEED_EPSILON


static func presentation_facing(battle_state: BattleState, participant: BattleParticipant) -> Vector2:
	if participant == null:
		return Vector2.UP
	if is_locomoting(participant):
		return participant.velocity.normalized()
	return facing(battle_state, participant)


static func animation_clip_id(_battle_state: BattleState, participant: BattleParticipant) -> String:
	if participant == null or not participant.is_alive:
		return TacticalUnitAnimationCatalog.CLIP_DEATH
	if is_locomoting(participant):
		return TacticalUnitAnimationCatalog.CLIP_WALK
	if _is_reloading(participant):
		return TacticalUnitAnimationCatalog.CLIP_RELOAD
	if participant.has_occupied_cover_slot():
		if participant.cover_posture_phase == "exposing":
			return TacticalUnitAnimationCatalog.CLIP_COVER_POPOUT
		if _is_visually_firing(participant) and (
			participant.is_cover_exposed() or participant.cover_posture_phase == "holding"
		):
			return TacticalUnitAnimationCatalog.CLIP_COVER_FIRE
		if participant.is_cover_exposed() or participant.cover_posture_phase == "holding":
			return TacticalUnitAnimationCatalog.CLIP_COVER_EXPOSED_IDLE
		if participant.cover_posture_phase == "tucking":
			return TacticalUnitAnimationCatalog.CLIP_COVER_TUCKED_IDLE
		return TacticalUnitAnimationCatalog.CLIP_COVER_TUCKED_IDLE
	if _is_visually_firing(participant):
		return TacticalUnitAnimationCatalog.CLIP_FIRE
	if participant.has_target_participant:
		return TacticalUnitAnimationCatalog.CLIP_AIM
	if participant.is_wounded:
		return TacticalUnitAnimationCatalog.CLIP_WOUNDED_IDLE
	return TacticalUnitAnimationCatalog.CLIP_IDLE


static func walk_speed_scale(participant: BattleParticipant) -> float:
	if participant == null:
		return 1.0
	var nominal: float = participant.movement_speed
	if not is_finite(nominal) or nominal <= 0.1:
		nominal = NOMINAL_WALK_SPEED
	var speed: float = participant.velocity.length()
	return clampf(speed / nominal, WALK_SPEED_SCALE_MIN, WALK_SPEED_SCALE_MAX)


static func _is_reloading(participant: BattleParticipant) -> bool:
	if participant == null or participant.weapon_state == null:
		return false
	return participant.weapon_state.is_reloading


static func _is_visually_firing(participant: BattleParticipant) -> bool:
	if participant == null or participant.weapon_state == null:
		return false
	if not is_finite(participant.weapon_state.cooldown_remaining_seconds):
		return false
	return participant.weapon_state.cooldown_remaining_seconds > FIRE_PRESENTATION_SECONDS


static func eight_direction_id(direction: Vector2) -> String:
	if not is_usable(direction):
		return DIR_S
	var deg: float = rad_to_deg(atan2(direction.y, direction.x))
	var idx: int = int(round(deg / 45.0))
	if idx == 8 or idx == -8:
		idx = 0
	match idx:
		0:
			return DIR_E
		1:
			return DIR_SE
		2:
			return DIR_S
		3:
			return DIR_SW
		4, -4:
			return DIR_W
		-3:
			return DIR_NW
		-2:
			return DIR_N
		-1:
			return DIR_NE
		_:
			return DIR_S


static func implemented_direction_id(direction: Vector2, previous_id: String = "") -> String:
	var raw_id: String = eight_direction_id(direction)
	if previous_id.is_empty() or previous_id == raw_id:
		return raw_id
	if not DIRECTION_IDS_8.has(previous_id):
		return raw_id
	var incoming: Vector2 = direction.normalized()
	var prev_v: Vector2 = _eight_vector(previous_id)
	var raw_v: Vector2 = _eight_vector(raw_id)
	if incoming.dot(prev_v) + DIRECTION_HYSTERESIS_DOT >= incoming.dot(raw_v):
		return previous_id
	return raw_id


static func eight_vector(direction_id: String) -> Vector2:
	return _eight_vector(direction_id)


static func _eight_vector(direction_id: String) -> Vector2:
	match direction_id:
		DIR_E:
			return Vector2.RIGHT
		DIR_SE:
			return Vector2(1.0, 1.0).normalized()
		DIR_S:
			return Vector2.DOWN
		DIR_SW:
			return Vector2(-1.0, 1.0).normalized()
		DIR_W:
			return Vector2.LEFT
		DIR_NW:
			return Vector2(-1.0, -1.0).normalized()
		DIR_N:
			return Vector2.UP
		DIR_NE:
			return Vector2(1.0, -1.0).normalized()
		_:
			return Vector2.DOWN


static func _latest_source_shot_facing(
	battle_state: BattleState,
	participant: BattleParticipant
) -> Vector2:
	if battle_state == null or participant == null:
		return Vector2.ZERO
	var events: Array = battle_state.combat_feedback_events
	var i: int = events.size() - 1
	while i >= 0:
		var event: BattleAttackEvent = events[i]
		i -= 1
		if event == null or event.source_participant_id != participant.participant_id:
			continue
		if not event.has_source_position or not event.has_target_position:
			continue
		var along: Vector2 = event.target_position - event.source_position
		if is_usable(along):
			return along
	return Vector2.ZERO

battle/presentation/tactical_unit_animat:
class_name TacticalUnitAnimationCatalog
extends RefCounted

const Factions := preload("res://battle/identity/faction_unit_catalog.gd")
const Weapons := preload("res://battle/combat/battle_weapon_catalog.gd")

# Cached SpriteFrames for tactical people.
# Accepted regular outfits share the same eight-direction clip schema.
# Approved pixel outfits with equipment-independent cached atlases.
# Does not own combat or TacticalBattleView.

const DIR_N := "n"
const DIR_NE := "ne"
const DIR_E := "e"
const DIR_SE := "se"
const DIR_S := "s"
const DIR_SW := "sw"
const DIR_W := "w"
const DIR_NW := "nw"

const DIRECTION_IDS_8: Array[String] = [
	DIR_N, DIR_NE, DIR_E, DIR_SE, DIR_S, DIR_SW, DIR_W, DIR_NW
]
const IMPLEMENTED_DIRECTION_IDS: Array[String] = [
	DIR_N, DIR_NE, DIR_E, DIR_SE, DIR_S, DIR_SW, DIR_W, DIR_NW
]

const CLIP_IDLE := "idle"
const CLIP_WALK := "walk"
const CLIP_AIM := "aim"
const CLIP_FIRE := "fire"
const CLIP_RELOAD := "reload"
const CLIP_COVER_EXPOSED_IDLE := "cover_exposed_idle"
const CLIP_COVER_TUCKED_IDLE := "cover_tucked_idle"
const CLIP_COVER_POPOUT := "cover_popout"
const CLIP_COVER_FIRE := "cover_fire"
const CLIP_WOUNDED_IDLE := "wounded_idle"
const CLIP_DEATH := "death"
const CLIP_DEATH_BACK := "death_back"
const CLIP_COVER_TUCKED := CLIP_COVER_TUCKED_IDLE
const CLIP_COVER_EXPOSED := CLIP_COVER_EXPOSED_IDLE
const CLIP_WOUNDED := CLIP_WOUNDED_IDLE
const CLIP_HIT := "hit"
const CLIP_WOUNDED_WALK := "wounded_walk"

const IDLE_FRAME_COUNT := 6
const WALK_FRAME_COUNT := 16
const AIM_FRAME_COUNT := 2
const FIRE_FRAME_COUNT := 3
const RELOAD_FRAME_COUNT := 2
const COVER_IDLE_FRAME_COUNT := 2
const COVER_POPOUT_FRAME_COUNT := 2
const COVER_FIRE_FRAME_COUNT := 2
const WOUNDED_FRAME_COUNT := 2
const DEATH_FRAME_COUNT := 2

const IDLE_FPS := 4.0
const WALK_FPS := 12.0
const AIM_FPS := 4.0
const FIRE_FPS := 12.0
const RELOAD_FPS := 3.0
const COVER_IDLE_FPS := 3.5
const COVER_POPOUT_FPS := 12.0
const COVER_FIRE_FPS := 12.0
const WOUNDED_FPS := 3.0
const DEATH_FPS := 8.0

const DEFAULT_ART_PPU := 38.0
const DEFAULT_FOOT_OFFSET_Y := -46.0

static var _texture_cache: Dictionary = {}
static var _frames_cache: Dictionary = {}
static var _variant_lru: Array[String] = []
const MAX_CACHED_VARIANTS := 12


static func animation_name(clip_id: String, direction_id: String) -> String:
	return "%s_%s" % [clip_id, direction_id]


static func clip_loops(clip_id: String) -> bool:
	return bool(clip_specs().get(clip_id, {}).get("loop", false))


static func implemented_clip_ids() -> Array[String]:
	return bound_clip_ids()



static var _manifest: Dictionary = {}

static func manifest() -> Dictionary:
	if _manifest.is_empty():
		var value: Variant = JSON.parse_string(FileAccess.get_file_as_string("res://assets/art/units/pixel_v1/manifest.json"))
		if value is Dictionary:
			_manifest = value
	return _manifest

static func variant_for(gang: String, weapon: String, model_id: String = "", specialist_id: String = "") -> String:
	var faction_id: String = Factions.canonical_id(gang)
	if not faction_id.is_empty():
		var model: String = Weapons.default_model(weapon) if model_id.is_empty() else model_id
		var definition = Weapons.get_model(model)
		if definition == null or definition.weapon_type_id != weapon: return ""
		if faction_id == "mercer" and specialist_id == "mercer_dual_glock" and model == "glock_17": return "mercer_dual_glock"
		var bound: String = str(faction_manifest().get("models", {}).get(faction_id+":"+model, ""))
		if not bound.is_empty(): return bound
		# Legacy entry points still work before a roster asset build is installed.
		if not gang in ["local_street_gang", "russian_organized_crime"]: return ""
	var outfit: String = ""
	match gang:
		"local_street_gang": outfit = "0"
		"russian_organized_crime": outfit = "1"
		"italian_mob": outfit = "2"
	if outfit == "0":
		if specialist_id == "mercer_dual_glock" and model_id == "glock_17": return "mercer_dual_glock"
		var mercer_variant: String = str(mercer_manifest().get("models", {}).get(outfit+"_"+model_id, ""))
		if not mercer_variant.is_empty(): return mercer_variant
	if not model_id.is_empty():
		var model_variant: String = str(arsenal_manifest().get("models", {}).get(outfit+"_"+model_id, ""))
		if not model_variant.is_empty(): return model_variant
	var gun: String = ""
	match weapon:
		"rifle": gun = "ak_rifle"
		"shotgun": gun = "pump_shotgun"
		"smg": gun = "uzi_smg"
		"pistol": gun = "pistol"
		"sniper": gun = "ak_rifle"
	if outfit.is_empty() or gun.is_empty():
		return ""
	return outfit + "_" + gun

static func bound_variant_ids() -> Array[String]:
	var result: Array[String] = []
	result.assign(manifest().get("variants", []))
	result.append_array(arsenal_manifest().get("variants", {}).keys())
	result.append_array(mercer_manifest().get("variants", {}).keys())
	result.append_array(faction_manifest().get("variants", {}).keys())
	return result

static func bound_clip_ids() -> Array[String]:
	var result: Array[String] = []
	result.assign(clip_specs().keys())
	return result

static func has_bound_frames(_participant_id: String, gang: String, weapon: String, model_id: String = "", specialist_id: String = "") -> bool:
	return is_bound_variant(variant_for(gang, weapon, model_id, specialist_id))

static func playback_clip_id(clip_id: String) -> String:
	return clip_id if bound_clip_ids().has(clip_id) else CLIP_IDLE

static func clip_frame_count(clip_id: String) -> int:
	return int(clip_specs().get(clip_id, {}).get("count", 0))

static func clip_fps(clip_id: String) -> float:
	return float(clip_specs().get(clip_id, {}).get("fps", 1.0))

static func frames_for(variant_id: String) -> SpriteFrames:
	if not is_bound_variant(variant_id):
		return null
	if _frames_cache.has(variant_id):
		_touch_variant(variant_id)
		return _frames_cache[variant_id] as SpriteFrames
	var atlas: Texture2D = _texture(atlas_path(variant_id, "units"))
	if atlas == null:
		return null
	var frames := SpriteFrames.new()
	frames.remove_animation("default")
	var directions: Array = manifest()["directions"]
	var rows: int = int(manifest()["rows_per_direction"])
	for clip: String in bound_clip_ids():
		var spec: Dictionary = clip_specs()[clip]
		var clip_atlas: Texture2D=atlas
		if spec.get("atlas", "") in ["death_back","check_comrade","fire_left","cover_fire_left"]:
			var extra_path=atlas_path(variant_id, str(spec.atlas))
			if not FileAccess.file_exists(extra_path):continue
			clip_atlas=_texture(extra_path)
		for d in range(directions.size()):
			var anim: String = animation_name(clip, str(directions[d]))
			frames.add_animation(anim)
			frames.set_animation_speed(anim, float(spec["fps"]))
			frames.set_animation_loop(anim, bool(spec["loop"]))
			for i in range(int(spec["count"])):
				var cell: int = int(spec["start"]) + i
				var tex := AtlasTexture.new()
				tex.atlas = clip_atlas
				tex.region = Rect2((cell % 32) * 128, (d * rows + cell / 32) * 128, 128, 128)
				if spec.get("atlas", "") in ["death_back","check_comrade","fire_left","cover_fire_left"]:tex.region=Rect2(i*128,d*128,128,128)
				frames.add_frame(anim, tex)
	_frames_cache[variant_id] = frames
	_touch_variant(variant_id)
	return frames


static func texture_cache_size() -> int:
	return _texture_cache.size()


static func frames_cache_size() -> int:
	return _frames_cache.size()


static func art_pixels_per_unit() -> float:
	return DEFAULT_ART_PPU


static func sprite_foot_offset() -> Vector2:
	return Vector2(0.0, DEFAULT_FOOT_OFFSET_Y)


static func _texture(path: String) -> Texture2D:
	if path.is_empty():
		return null
	if _texture_cache.has(path):
		var cached: Variant = _texture_cache[path]
		if cached is Texture2D:
			return cached as Texture2D
	var texture: Texture2D = _load_texture(path)
	if texture == null:
		return null
	_texture_cache[path] = texture
	return texture


static func _load_texture(path: String) -> Texture2D:
	if ResourceLoader.exists(path):
		var loaded: Resource = ResourceLoader.load(path, "Texture2D")
		if loaded is Texture2D:
			return loaded as Texture2D
	if not FileAccess.file_exists(path):
		return null
	var image: Image = Image.new()
	if image.load(path) != OK:
		return null
	return ImageTexture.create_from_image(image)


static var _arsenal: Dictionary = {}
static func arsenal_manifest() -> Dictionary:
	if _arsenal.is_empty():
		var path: String = "res://assets/art/weapons/arsenal/manifest.json"
		if FileAccess.file_exists(path):
			var data: Variant = JSON.parse_string(FileAccess.get_file_as_string(path))
			if data is Dictionary: _arsenal = data
	return _arsenal

static func base_variant(variant: String) -> String:
	if faction_manifest().get("variants", {}).has(variant): return str(faction_manifest().variants[variant].base)
	if mercer_manifest().get("variants", {}).has(variant): return str(mercer_manifest().variants[variant].base)
	return str(arsenal_manifest().get("variants", {}).get(variant, {}).get("base", variant))

static func atlas_path(variant: String, folder: String) -> String:
	if faction_manifest().get("variants", {}).has(variant): return "res://assets/art/units/factions/"+folder+"/"+variant+".png"
	if mercer_manifest().get("variants", {}).has(variant): return "res://assets/art/units/mercer/"+folder+"/"+variant+".png"
	var row: Dictionary = arsenal_manifest().get("variants", {}).get(variant, {})
	if not row.is_empty():
		return "res://assets/art/weapons/arsenal/"+folder+"/"+str(row.file)+".png"
	return "res://assets/art/units/pixel_v1/"+("" if folder=="units" else folder+"/")+variant+".png"


# Browsing the arsenal must not retain dozens of 4096x6144 atlases indefinitely.
# Active sprites own their frames independently, so eviction cannot blank a living unit.
static func _touch_variant(variant: String) -> void:
	_variant_lru.erase(variant)
	_variant_lru.append(variant)
	while _variant_lru.size() > MAX_CACHED_VARIANTS:
		var old: String = _variant_lru.pop_front()
		_frames_cache.erase(old)
		for folder: String in ["units", "death_back", "check_comrade", "fire_left", "cover_fire_left"]:
			_texture_cache.erase(atlas_path(old, folder))

static var _mercer: Dictionary = {}
static func mercer_manifest() -> Dictionary:
	if _mercer.is_empty():
		var path = "res://assets/art/units/mercer/manifest.json"
		if FileAccess.file_exists(path):
			var data: Variant = JSON.parse_string(FileAccess.get_file_as_string(path))
			if data is Dictionary: _mercer = data
	return _mercer

static func clip_specs() -> Dictionary:
	var clips: Dictionary = manifest().get("clips", {}).duplicate()
	clips.merge(mercer_manifest().get("clips", {}), true)
	return clips

static func foot_anchor(variant: String) -> Vector2:
	return Vector2(64,104 if variant.begins_with("mercer_") or variant.begins_with("faction_") else 110)

static func blood_mask_path(variant: String) -> String:
	if variant.begins_with("mercer_") or variant.begins_with("faction_"): return atlas_path(variant, "blood_masks")
	return "res://assets/art/units/pixel_v1/blood_masks/"+base_variant(variant)+".png"


static var _factions: Dictionary = {}
static func faction_manifest() -> Dictionary:
	if _factions.is_empty():
		var path := "res://assets/art/units/factions/manifest.json"
		if FileAccess.file_exists(path):
			var value: Variant = JSON.parse_string(FileAccess.get_file_as_string(path))
			if value is Dictionary: _factions = value
	return _factions

static func is_bound_variant(variant: String) -> bool:
	return faction_manifest().get("variants", {}).has(variant) or arsenal_manifest().get("variants", {}).has(variant) or mercer_manifest().get("variants", {}).has(variant) or manifest().get("variants", []).has(variant)

battle/presentation/tactical_visual_plac:
class_name TacticalVisualPlacement
extends RefCounted

# Native-proportion environment placement. Presentation only.
# A gameplay Rect2 is an anchor frame, not an art stretch target.
#
# Tactical projection contract:
# One fixed top-down camera with restrained faux-depth toward world-south
# (screen-bottom). North-row art may expose south-facing street frontage.
# South-row art MUST use the same depth direction and must not mirror
# storefronts toward the camera. All future authored environment assets
# obey this convention.

const BattleVisualBinding := preload("res://battle/presentation/battle_visual_binding.gd")

const DEPTH_DIRECTION_SOUTH := "south"

const ANCHOR_CENTER := "center"
const ANCHOR_NORTH := "north"
const ANCHOR_SOUTH := "south"
const ANCHOR_FRONTAGE := "frontage"
const ANCHOR_CUSTOM := "custom"

const MODE_NATIVE := "native"
const MODE_TILE := "tile"


static func is_known_anchor(mode: String) -> bool:
	return (
		mode == ANCHOR_CENTER
		or mode == ANCHOR_NORTH
		or mode == ANCHOR_SOUTH
		or mode == ANCHOR_FRONTAGE
		or mode == ANCHOR_CUSTOM
	)


static func is_known_placement_mode(mode: String) -> bool:
	return mode == MODE_NATIVE or mode == MODE_TILE


static func native_world_size(texture: Texture2D, art_ppu: float) -> Vector2:
	if texture == null or art_ppu <= 0.0:
		return Vector2.ZERO
	var px_w: float = float(texture.get_width())
	var px_h: float = float(texture.get_height())
	if px_w <= 0.0 or px_h <= 0.0:
		return Vector2.ZERO
	return Vector2(px_w / art_ppu, px_h / art_ppu)


static func visual_uv(anchor_mode: String, custom_uv: Vector2) -> Vector2:
	if anchor_mode == ANCHOR_NORTH:
		return Vector2(0.5, 0.0)
	if anchor_mode == ANCHOR_SOUTH or anchor_mode == ANCHOR_FRONTAGE:
		return Vector2(0.5, 1.0)
	if anchor_mode == ANCHOR_CUSTOM:
		return custom_uv
	return Vector2(0.5, 0.5)


static func gameplay_anchor_point(bounds: Rect2, anchor_mode: String) -> Vector2:
	if anchor_mode == ANCHOR_NORTH:
		return Vector2(bounds.get_center().x, bounds.position.y)
	if anchor_mode == ANCHOR_SOUTH or anchor_mode == ANCHOR_FRONTAGE:
		return Vector2(bounds.get_center().x, bounds.position.y + bounds.size.y)
	return bounds.get_center()


static func world_sprite_center(anchor_world: Vector2, world_size: Vector2, uv: Vector2) -> Vector2:
	return Vector2(
		anchor_world.x + (0.5 - uv.x) * world_size.x,
		anchor_world.y + (0.5 - uv.y) * world_size.y
	)


static func resolved_world_size(
	texture: Texture2D,
	art_ppu: float,
	binding: BattleVisualBinding,
	gameplay_bounds: Rect2,
	use_gameplay_bounds: bool
) -> Vector2:
	if binding == null:
		return Vector2.ZERO
	if binding.placement_mode == MODE_TILE:
		if binding.visual_world_size.x > 0.0 and binding.visual_world_size.y > 0.0:
			return binding.visual_world_size * binding.scale
		if use_gameplay_bounds:
			return gameplay_bounds.size * binding.scale
		return Vector2.ZERO
	var native: Vector2 = native_world_size(texture, art_ppu)
	if native.x <= 0.0 or native.y <= 0.0:
		return Vector2.ZERO
	var size: Vector2 = native
	if binding.visual_world_size.x > 0.0:
		size = native * (binding.visual_world_size.x / native.x)
	elif binding.visual_world_size.y > 0.0:
		size = native * (binding.visual_world_size.y / native.y)
	return size * binding.scale


static func compute(
	texture: Texture2D,
	spec: Dictionary,
	binding: BattleVisualBinding,
	view_ppu: float,
	gameplay_bounds: Rect2,
	use_gameplay_bounds: bool
) -> Dictionary:
	var empty: Dictionary = {}
	if texture == null or binding == null or spec.is_empty():
		return empty
	if view_ppu <= 0.0:
		return empty
	var art_ppu: float = float(spec.get("art_pixels_per_unit", 0.0))
	if art_ppu <= 0.0:
		return empty
	if not is_known_anchor(binding.anchor_mode):
		return empty
	if not is_known_placement_mode(binding.placement_mode):
		return empty
	var world_size: Vector2 = resolved_world_size(
		texture,
		art_ppu,
		binding,
		gameplay_bounds,
		use_gameplay_bounds
	)
	if world_size.x <= 0.0 or world_size.y <= 0.0:
		return empty
	var uv: Vector2 = visual_uv(binding.anchor_mode, binding.anchor_uv)
	if not is_finite(uv.x) or not is_finite(uv.y):
		return empty
	var anchor_world: Vector2 = binding.offset
	if use_gameplay_bounds:
		anchor_world = gameplay_anchor_point(gameplay_bounds, binding.anchor_mode) + binding.offset
	var world_center: Vector2 = world_sprite_center(anchor_world, world_size, uv)
	var view_scale: float = 0.0
	var region_enabled: bool = binding.placement_mode == MODE_TILE
	var region_rect: Rect2 = Rect2()
	if region_enabled:
		region_rect = Rect2(Vector2.ZERO, world_size * art_ppu)
		view_scale = view_ppu / art_ppu
	else:
		var px_w: float = float(texture.get_width())
		if px_w <= 0.0:
			return empty
		view_scale = (world_size.x * view_ppu) / px_w
	if view_scale <= 0.0 or not is_finite(view_scale):
		return empty
	var world_rect: Rect2 = Rect2(world_center - world_size * 0.5, world_size)
	return {
		"world_center": world_center,
		"world_size": world_size,
		"world_rect": world_rect,
		"view_position": world_center * view_ppu,
		"view_scale": view_scale,
		"uniform": true,
		"region_enabled": region_enabled,
		"region_rect": region_rect,
		"texture_repeat": region_enabled,
	}

battle/runtime/battle_movement_service.g:
class_name BattleMovementService
extends RefCounted

const BattleWeaponCatalog := preload("res://battle/combat/battle_weapon_catalog.gd")

const BattleState := preload("res://battle/core/battle_state.gd")
const BattleParticipant := preload("res://battle/core/battle_participant.gd")
const BattleMovementResult := preload("res://battle/runtime/battle_movement_result.gd")
const BattleSpatialService := preload("res://battle/geometry/battle_spatial_service.gd")
const BattleSpatialResult := preload("res://battle/geometry/battle_spatial_result.gd")


static func advance(battle_state: BattleState, delta_seconds: float) -> BattleMovementResult:
	if battle_state == null:
		return BattleMovementResult.failed(
			"null_battle_state",
			"Battle movement failed: battle_state is null.",
			delta_seconds
		)
	if battle_state.battle_phase != "active":
		return BattleMovementResult.failed(
			"battle_not_active",
			"Battle movement failed: battle phase is '%s', not active." % battle_state.battle_phase,
			delta_seconds
		)
	if not is_finite(delta_seconds) or delta_seconds < 0.0:
		return BattleMovementResult.failed(
			"invalid_delta",
			"Battle movement failed: delta_seconds is invalid.",
			delta_seconds
		)
	if battle_state.battlefield_geometry == null:
		return BattleMovementResult.failed(
			"missing_battlefield_geometry",
			"Battle movement failed: battlefield geometry is missing.",
			delta_seconds
		)
	if not battle_state.has_valid_geometry():
		return BattleMovementResult.failed(
			"invalid_battlefield_geometry",
			"Battle movement failed: battlefield geometry is invalid.",
			delta_seconds
		)
	var participant_ids: Array[String] = _sorted_participant_ids(battle_state)
	var participants_considered: int = 0
	var participants_moved: int = 0
	for participant_id: String in participant_ids:
		var participant: BattleParticipant = battle_state.get_participant(participant_id)
		if participant == null:
			continue
		participants_considered += 1
		if _advance_participant(battle_state, participant, delta_seconds):
			participants_moved += 1
	return BattleMovementResult.succeeded(delta_seconds, participants_considered, participants_moved)


static func _sorted_participant_ids(battle_state: BattleState) -> Array[String]:
	var ids: Array[String] = []
	for participant_id: String in battle_state.participants:
		ids.append(participant_id)
	ids.sort()
	return ids


static func _advance_participant(
	battle_state: BattleState,
	participant: BattleParticipant,
	delta_seconds: float
) -> bool:
	if not participant.has_battle_position:
		participant.velocity = Vector2.ZERO
		return false
	if not participant.is_alive:
		participant.velocity = Vector2.ZERO
		return false
	var definition = BattleWeaponCatalog.for_participant(participant)
	var weight_speed: float = definition.movement_multiplier if definition != null else 1.0
	var speed: float = participant.movement_speed * weight_speed * cover_hustle_multiplier(battle_state, participant)
	if not is_finite(speed) or speed < 0.0:
		participant.velocity = Vector2.ZERO
		return false
	if speed == 0.0:
		participant.velocity = Vector2.ZERO
		return false
	var direction: Vector2 = _resolved_direction(participant.movement_intent)
	if direction == Vector2.ZERO:
		participant.velocity = Vector2.ZERO
		return false
	var next_velocity: Vector2 = direction * speed
	if not _is_finite_vector(next_velocity):
		participant.velocity = Vector2.ZERO
		return false
	participant.velocity = next_velocity
	if not _is_finite_vector(participant.battle_position):
		return false
	var displacement: Vector2 = participant.velocity * delta_seconds
	if not _is_finite_vector(displacement):
		return false
	var start_position: Vector2 = participant.battle_position
	displacement = _capped_displacement(participant, start_position, displacement)
	if not _is_finite_vector(displacement):
		return false
	var spatial: BattleSpatialResult = BattleSpatialService.resolve_translation(
		battle_state,
		start_position,
		displacement
	)
	if spatial == null or not spatial.success:
		return false
	if not _is_finite_vector(spatial.final_position):
		return false
	participant.battle_position = spatial.final_position
	return not start_position.is_equal_approx(spatial.final_position)


static func _capped_displacement(
	participant: BattleParticipant,
	start_position: Vector2,
	displacement: Vector2
) -> Vector2:
	if not participant.has_movement_target_position:
		return displacement
	if not _is_finite_vector(participant.movement_target_position):
		return displacement
	var to_target: Vector2 = participant.movement_target_position - start_position
	if not _is_finite_vector(to_target):
		return displacement
	var remaining: float = to_target.length()
	if not is_finite(remaining):
		return displacement
	if is_zero_approx(remaining):
		return Vector2.ZERO
	if displacement.length() < remaining:
		return displacement
	if displacement.dot(to_target) <= 0.0:
		return displacement
	return to_target


static func _resolved_direction(intent: Vector2) -> Vector2:
	if not _is_finite_vector(intent):
		return Vector2.ZERO
	if intent == Vector2.ZERO:
		return Vector2.ZERO
	var direction: Vector2 = intent.normalized()
	if not _is_finite_vector(direction) or direction == Vector2.ZERO:
		return Vector2.ZERO
	return direction


static func _is_finite_vector(value: Vector2) -> bool:
	return is_finite(value.x) and is_finite(value.y)

# A temporary multiplier, so base movement tuning and wounded penalties remain intact.
static func cover_hustle_multiplier(b, p) -> float:
	if b==null or p==null or not p.is_alive or not p.has_active_navigation_path():return 1.0
	if p.has_occupied_cover_slot():return 1.0
	var slot_id: String=p.reserved_cover_slot_id
	if slot_id.is_empty() and p.has_player_cover_intent():slot_id=p.player_cover_slot_id
	if slot_id.is_empty() or b.battlefield_geometry==null:return 1.0
	var slot=b.battlefield_geometry.get_cover_slot(slot_id)
	if slot==null or p.navigation_destination.distance_to(slot.position)>1.0:return 1.0
	# Moving between cover points in exposed walkable space; no boost for ordinary moves.
	if not b.battlefield_geometry.get_movement_blocking_obstacle_id_at(p.battle_position).is_empty():return 1.0
	return 1.18

battle/runtime/battle_runtime_service.gd:
class_name BattleRuntimeService
extends RefCounted
const CollisionShapes := preload("res://battle/vehicles/battle_vehicle_body_service.gd")
const RoleProfiles = preload("res://battle/combat/battle_combat_behavior_catalog.gd")
const WeaponProfiles := preload("res://battle/combat/battle_weapon_catalog.gd")

const Strength = preload("res://battle/ai/battle_relative_strength.gd")
const Tactics = preload("res://battle/ai/battle_adaptive_tactics.gd")
const BattleState := preload("res://battle/core/battle_state.gd")
const BattleRuntimeResult := preload("res://battle/runtime/battle_runtime_result.gd")
const BattleFireControlService := preload("res://battle/combat/battle_fire_control_service.gd")
const BattleFireControlResult := preload("res://battle/combat/battle_fire_control_result.gd")
const BattleTargetSelectionService := preload("res://battle/combat/battle_target_selection_service.gd")
const BattleTargetSelectionResult := preload("res://battle/combat/battle_target_selection_result.gd")
const BattleCombatPressureService := preload("res://battle/combat/battle_combat_pressure_service.gd")
const BattleCombatPressureResult := preload("res://battle/combat/battle_combat_pressure_result.gd")
const BattleCombatBehaviorService := preload("res://battle/combat/battle_combat_behavior_service.gd")
const BattleCombatBehaviorResult := preload("res://battle/combat/battle_combat_behavior_result.gd")
const BattlePathFollowService := preload("res://battle/navigation/battle_path_follow_service.gd")
const BattlePathFollowResult := preload("res://battle/navigation/battle_path_follow_result.gd")
const BattleMovementService := preload("res://battle/runtime/battle_movement_service.gd")
const BattleMovementResult := preload("res://battle/runtime/battle_movement_result.gd")
const BattleVictoryService := preload("res://battle/core/battle_victory_service.gd")
const BattleVictoryResult := preload("res://battle/core/battle_victory_result.gd")


static func advance(battle_state: BattleState, delta_seconds: float) -> BattleRuntimeResult:
	if battle_state == null or battle_state.battle_phase != "active" or not is_finite(delta_seconds) or delta_seconds < 0.0 or not is_finite(battle_state.elapsed_time_seconds) or battle_state.elapsed_time_seconds < 0.0:
		return _advance_validated(battle_state, delta_seconds)
	if battle_state.tactical_paused:
		return BattleRuntimeResult.succeeded(0.0, battle_state.elapsed_time_seconds, battle_state.elapsed_time_seconds)
	delta_seconds *= battle_state.tactical_speed
	battle_state.begin_geometry_validation_scope()
	var previous_profiles: Dictionary = WeaponProfiles.begin_runtime_profile_scope(battle_state.participants)
	var previous_roles: Dictionary = RoleProfiles.begin_runtime_profile_scope(battle_state.participants)
	var previous_collision: Array = CollisionShapes.begin_runtime_collision_scope(battle_state)
	var previous_readiness: Array = battle_state.begin_runtime_readiness_scope()
	var result: BattleRuntimeResult = _advance_validated(battle_state, delta_seconds)
	CollisionShapes.end_runtime_collision_scope(previous_collision)
	battle_state.end_runtime_readiness_scope(previous_readiness)
	RoleProfiles.end_runtime_profile_scope(previous_roles)
	WeaponProfiles.end_runtime_profile_scope(previous_profiles)
	battle_state.end_geometry_validation_scope()
	return result


static func _advance_validated(battle_state: BattleState, delta_seconds: float) -> BattleRuntimeResult:
	if battle_state == null:
		return BattleRuntimeResult.failed(
			"null_battle_state",
			"Battle runtime failed: battle_state is null.",
			delta_seconds,
			0.0
		)
	battle_state.prepare_los_cache_for_tick()
	var elapsed_before: float = battle_state.elapsed_time_seconds
	if battle_state.battle_phase != "active":
		return BattleRuntimeResult.failed(
			"battle_not_active",
			"Battle runtime failed: battle phase is '%s', not active." % battle_state.battle_phase,
			delta_seconds,
			elapsed_before
		)
	if not is_finite(delta_seconds) or delta_seconds < 0.0:
		return BattleRuntimeResult.failed(
			"invalid_delta",
			"Battle runtime failed: delta_seconds is invalid.",
			delta_seconds,
			elapsed_before
		)
	if not is_finite(elapsed_before) or elapsed_before < 0.0:
		return BattleRuntimeResult.failed(
			"invalid_elapsed_time",
			"Battle runtime failed: elapsed_time_seconds is invalid.",
			delta_seconds,
			elapsed_before
		)
	var early_victory: BattleVictoryResult = BattleVictoryService.resolve_if_terminal(battle_state)
	if early_victory != null and early_victory.success and early_victory.resolved_this_call:
		return _finish_runtime(battle_state, delta_seconds, elapsed_before, early_victory, true)
	var weapon_result: BattleFireControlResult = BattleFireControlService.advance_weapon_state(
		battle_state,
		delta_seconds
	)
	if weapon_result == null or not weapon_result.success:
		var weapon_error_code: String = "invalid_delta"
		var weapon_error_message: String = "Battle runtime failed: weapon state advancement failed."
		if weapon_result != null:
			if not weapon_result.error_code.is_empty():
				weapon_error_code = weapon_result.error_code
			if not weapon_result.error_message.is_empty():
				weapon_error_message = weapon_result.error_message
		return BattleRuntimeResult.failed(
			weapon_error_code,
			weapon_error_message,
			delta_seconds,
			elapsed_before
		)
	var target_result: BattleTargetSelectionResult = BattleTargetSelectionService.advance(battle_state)
	if target_result == null or not target_result.success:
		var target_error_code: String = "invalid_delta"
		var target_error_message: String = "Battle runtime failed: target selection failed."
		if target_result != null:
			if not target_result.error_code.is_empty():
				target_error_code = target_result.error_code
			if not target_result.error_message.is_empty():
				target_error_message = target_result.error_message
		return BattleRuntimeResult.failed(
			target_error_code,
			target_error_message,
			delta_seconds,
			elapsed_before
		)
	var pressure_result: BattleCombatPressureResult = BattleCombatPressureService.refresh(battle_state)
	if pressure_result == null or not pressure_result.success:
		var pressure_error_code: String = "invalid_delta"
		var pressure_error_message: String = "Battle runtime failed: combat pressure refresh failed."
		if pressure_result != null:
			if not pressure_result.error_code.is_empty():
				pressure_error_code = pressure_result.error_code
			if not pressure_result.error_message.is_empty():
				pressure_error_message = pressure_result.error_message
		return BattleRuntimeResult.failed(
			pressure_error_code,
			pressure_error_message,
			delta_seconds,
			elapsed_before
		)
	Tactics.advance(battle_state, delta_seconds)
	var combat_result: BattleCombatBehaviorResult = BattleCombatBehaviorService.advance(
		battle_state,
		delta_seconds
	)
	if combat_result == null or not combat_result.success:
		var combat_error_code: String = "invalid_delta"
		var combat_error_message: String = "Battle runtime failed: combat behavior failed."
		if combat_result != null:
			if not combat_result.error_code.is_empty():
				combat_error_code = combat_result.error_code
			if not combat_result.error_message.is_empty():
				combat_error_message = combat_result.error_message
		return BattleRuntimeResult.failed(
			combat_error_code,
			combat_error_message,
			delta_seconds,
			elapsed_before
		)
	var victory_result: BattleVictoryResult = BattleVictoryService.resolve_if_terminal(battle_state)
	if battle_state.battle_phase != "active":
		return _finish_runtime(battle_state, delta_seconds, elapsed_before, victory_result, true)
	var path_follow_result: BattlePathFollowResult = BattlePathFollowService.advance(battle_state)
	if path_follow_result == null or not path_follow_result.success:
		var follow_error_code: String = "invalid_delta"
		var follow_error_message: String = "Battle runtime failed: path following failed."
		if path_follow_result != null:
			if not path_follow_result.error_code.is_empty():
				follow_error_code = path_follow_result.error_code
			if not path_follow_result.error_message.is_empty():
				follow_error_message = path_follow_result.error_message
		return BattleRuntimeResult.failed(
			follow_error_code,
			follow_error_message,
			delta_seconds,
			elapsed_before
		)
	var movement_result: BattleMovementResult = BattleMovementService.advance(battle_state, delta_seconds)
	if movement_result == null or not movement_result.success:
		var error_code: String = "invalid_delta"
		var error_message: String = "Battle runtime failed: movement advancement failed."
		if movement_result != null:
			if not movement_result.error_code.is_empty():
				error_code = movement_result.error_code
			if not movement_result.error_message.is_empty():
				error_message = movement_result.error_message
		return BattleRuntimeResult.failed(
			error_code,
			error_message,
			delta_seconds,
			elapsed_before
		)
	return _finish_runtime(battle_state, delta_seconds, elapsed_before, null, false)


static func _finish_runtime(
	battle_state: BattleState,
	delta_seconds: float,
	elapsed_before: float,
	victory_result: BattleVictoryResult,
	resolved_this_pass: bool
) -> BattleRuntimeResult:
	Strength.refresh(battle_state, battle_state.battle_phase == "resolved")
	var winning_side_id: String = ""
	if victory_result != null and victory_result.success and victory_result.resolved:
		winning_side_id = victory_result.winning_side_id
		if victory_result.resolved_this_call:
			resolved_this_pass = true
	if delta_seconds == 0.0:
		return BattleRuntimeResult.succeeded(
			delta_seconds,
			elapsed_before,
			elapsed_before,
			resolved_this_pass,
			winning_side_id
		)
	battle_state.elapsed_time_seconds = elapsed_before + delta_seconds
	return BattleRuntimeResult.succeeded(
		delta_seconds,
		elapsed_before,
		battle_state.elapsed_time_seconds,
		resolved_this_pass,
		winning_side_id
	)

