class_name BattleVehiclePhysicalCatalog
extends RefCounted

const BattleVehiclePhysicalProfile := preload("res://battle/vehicles/battle_vehicle_physical_profile.gd")

const TYPE_CAR := "car"
const Models=preload("res://campaign/vehicles/vehicle_model_catalog.gd")

# Match the authored curb sedans; the same body drives art, navigation and cover.
const CAR_LENGTH := 5.15 * Models.TACTICAL_SCALE
const CAR_WIDTH := 2.1 * Models.TACTICAL_SCALE


static func get_profile(vehicle_type_id: String) -> BattleVehiclePhysicalProfile:
	var profile: BattleVehiclePhysicalProfile = _make_profile(vehicle_type_id)
	if profile == null or not profile.is_valid():
		return null
	return profile


static func has_profile(vehicle_type_id: String) -> bool:
	return get_profile(vehicle_type_id) != null


static func _make_profile(vehicle_type_id: String) -> BattleVehiclePhysicalProfile:
	if Models.has_model(vehicle_type_id):
		var m=Models.model(vehicle_type_id)
		return BattleVehiclePhysicalProfile.new(vehicle_type_id,float(m.length)*Models.TACTICAL_SCALE,float(m.width)*Models.TACTICAL_SCALE)
	match vehicle_type_id:
		TYPE_CAR:
			return BattleVehiclePhysicalProfile.new(TYPE_CAR, CAR_LENGTH, CAR_WIDTH)
		_:
			# Provisional default so unknown campaign types still have a body.
			# Not a second type catalog or a design lock.
			if vehicle_type_id.is_empty():
				return null
			return BattleVehiclePhysicalProfile.new(vehicle_type_id, CAR_LENGTH, CAR_WIDTH)

# Internal collision queries reuse profiles. Public get_profile still returns
# an independent object. Authored model dimension edits are observed immediately.
static var _collision_profiles: Dictionary = {}

static func _get_collision_profile(vehicle_type_id: String) -> BattleVehiclePhysicalProfile:
	if vehicle_type_id.is_empty():
		return null
	var length: float = CAR_LENGTH
	var width: float = CAR_WIDTH
	if Models.has_model(vehicle_type_id):
		var model: Dictionary = Models.model(vehicle_type_id)
		length = float(model.length)*Models.TACTICAL_SCALE
		width = float(model.width)*Models.TACTICAL_SCALE
	if not is_finite(length) or not is_finite(width) or length <= 0.0 or width <= 0.0:
		return null
	var cached: BattleVehiclePhysicalProfile = _collision_profiles.get(vehicle_type_id)
	if cached != null and cached.vehicle_type_id == vehicle_type_id and cached.length == length and cached.width == width:
		return cached
	var profile := BattleVehiclePhysicalProfile.new(vehicle_type_id, length, width)
	if _collision_profiles.size() >= 128:
		_collision_profiles.clear()
	_collision_profiles[vehicle_type_id] = profile
	return profile

battle/vehicles/battle_vehicle_placement:
class_name BattleVehiclePlacementService
extends RefCounted

# Authoritative vehicle placement during deployment.
# Composes BattleState.deploy_vehicle (membership) with validated pose.
# Does not own geometry. Does not begin battle. Does not write from the view.

const BattleState := preload("res://battle/core/battle_state.gd")
const BattleVehicle := preload("res://battle/core/battle_vehicle.gd")
const BattleSide := preload("res://battle/core/battle_side.gd")
const BattleVehiclePlacementResult := preload("res://battle/vehicles/battle_vehicle_placement_result.gd")
const BattleVehicleBodyService := preload("res://battle/vehicles/battle_vehicle_body_service.gd")
const BattleVehicleCoverService := preload("res://battle/vehicles/battle_vehicle_cover_service.gd")


static func place_vehicle(
	battle_state: BattleState,
	vehicle_id: String,
	position: Vector2,
	facing_direction: Vector2
) -> BattleVehiclePlacementResult:
	if battle_state == null:
		return BattleVehiclePlacementResult.failed(
			"null_battle_state",
			"Vehicle placement failed: battle_state is null.",
			vehicle_id,
			position,
			facing_direction
		)
	if battle_state.battle_phase != "deployment":
		return BattleVehiclePlacementResult.failed(
			"battle_not_in_deployment",
			"Vehicle placement failed: battle phase is '%s', not deployment." % battle_state.battle_phase,
			vehicle_id,
			position,
			facing_direction
		)
	if vehicle_id.is_empty() or not battle_state.has_vehicle(vehicle_id):
		return BattleVehiclePlacementResult.failed(
			"unknown_vehicle",
			"Vehicle placement failed: vehicle '%s' does not exist." % vehicle_id,
			vehicle_id,
			position,
			facing_direction
		)
	var vehicle: BattleVehicle = battle_state.get_vehicle(vehicle_id)
	if vehicle == null:
		return BattleVehiclePlacementResult.failed(
			"unknown_vehicle",
			"Vehicle placement failed: vehicle '%s' does not exist." % vehicle_id,
			vehicle_id,
			position,
			facing_direction
		)
	if not _facing_is_usable(facing_direction):
		return BattleVehiclePlacementResult.failed(
			"invalid_orientation",
			"Vehicle placement failed: facing direction is invalid.",
			vehicle_id,
			position,
			facing_direction
		)
	var normalized_facing: Vector2 = facing_direction.normalized()
	if battle_state.is_vehicle_deployed(vehicle_id) and vehicle.has_battle_position:
		return BattleVehiclePlacementResult.failed(
			"already_deployed",
			"Vehicle placement failed: vehicle '%s' is already deployed." % vehicle_id,
			vehicle_id,
			position,
			normalized_facing
		)
	if not battle_state.has_side(vehicle.side_id):
		return BattleVehiclePlacementResult.failed(
			"missing_side",
			"Vehicle placement failed: side '%s' does not exist." % vehicle.side_id,
			vehicle_id,
			position,
			normalized_facing
		)
	if battle_state.is_side_deployment_committed(vehicle.side_id):
		return BattleVehiclePlacementResult.failed(
			"side_deployment_committed",
			"Vehicle placement failed: side '%s' deployment is already committed." % vehicle.side_id,
			vehicle_id,
			position,
			normalized_facing
		)
	var side: BattleSide = battle_state.get_side(vehicle.side_id)
	if side == null or side.deployment_zone_id.is_empty():
		return BattleVehiclePlacementResult.failed(
			"missing_deployment_zone",
			"Vehicle placement failed: side '%s' has no deployment zone." % vehicle.side_id,
			vehicle_id,
			position,
			normalized_facing
		)
	var legality: String = BattleVehicleBodyService.get_placement_error(
		battle_state,
		vehicle_id,
		position,
		normalized_facing
	)
	if not legality.is_empty():
		return BattleVehiclePlacementResult.failed(
			legality,
			_position_error_message(legality, vehicle.side_id, battle_state, vehicle_id),
			vehicle_id,
			position,
			normalized_facing
		)
	var preview_vehicle: BattleVehicle = BattleVehicle.new(
		vehicle.battle_vehicle_id,
		vehicle.campaign_vehicle_id,
		vehicle.faction_id,
		vehicle.side_id,
		vehicle.vehicle_type_id,
		vehicle.deployment_slot_id
	)
	preview_vehicle.has_battle_position = true
	preview_vehicle.battle_position = position
	preview_vehicle.set_facing_direction(normalized_facing)
	var needs_cover=bool(preload("res://campaign/vehicles/vehicle_model_catalog.gd").model(vehicle.vehicle_type_id).get("cover",true))
	if needs_cover and BattleVehicleCoverService.collect_legal_body_slots(battle_state, preview_vehicle).is_empty():
		return BattleVehiclePlacementResult.failed(
			"cover_failed",
			"Vehicle placement failed: body cover could not be created for '%s'." % vehicle_id,
			vehicle_id,
			position,
			normalized_facing
		)
	var already_member: bool = battle_state.is_vehicle_deployed(vehicle_id)
	if not already_member:
		if not battle_state.deploy_vehicle(vehicle_id, side.deployment_zone_id):
			return BattleVehiclePlacementResult.failed(
				"deploy_failed",
				"Vehicle placement failed: BattleState.deploy_vehicle rejected '%s'." % vehicle_id,
				vehicle_id,
				position,
				normalized_facing
			)
	if not vehicle.set_facing_direction(normalized_facing):
		return BattleVehiclePlacementResult.failed(
			"invalid_orientation",
			"Vehicle placement failed: facing direction is invalid.",
			vehicle_id,
			position,
			normalized_facing
		)
	vehicle.has_battle_position = true
	vehicle.battle_position = position
	if not BattleVehicleCoverService.ensure_body_cover(battle_state, vehicle_id):
		vehicle.has_battle_position = false
		vehicle.battle_position = Vector2.ZERO
		vehicle.has_facing = false
		vehicle.facing_direction = Vector2.ZERO
		return BattleVehiclePlacementResult.failed(
			"cover_failed",
			"Vehicle placement failed: body cover could not be created for '%s'." % vehicle_id,
			vehicle_id,
			position,
			normalized_facing
		)
	return BattleVehiclePlacementResult.succeeded(vehicle_id, position, normalized_facing)


static func _facing_is_usable(facing: Vector2) -> bool:
	if not is_finite(facing.x) or not is_finite(facing.y):
		return false
	if facing.is_equal_approx(Vector2.ZERO):
		return false
	return true


static func _position_error_message(
	error_code: String,
	side_id: String,
	battle_state: BattleState,
	vehicle_id: String
) -> String:
	match error_code:
		"invalid_position":
			return "Vehicle placement failed: position is not finite."
		"invalid_orientation":
			return "Vehicle placement failed: facing direction is invalid."
		"unknown_vehicle":
			return "Vehicle placement failed: vehicle '%s' does not exist." % vehicle_id
		"missing_profile":
			return "Vehicle placement failed: vehicle '%s' has no physical profile." % vehicle_id
		"missing_battlefield_geometry":
			return "Vehicle placement failed: battlefield geometry is missing or invalid."
		"outside_battlefield":
			return "Vehicle placement failed: vehicle body is outside battlefield bounds."
		"outside_deployment_zone":
			if side_id == battle_state.attacker_side_id:
				return "Vehicle placement failed: vehicle body is outside the attacker deployment region."
			if side_id == battle_state.defender_side_id:
				return "Vehicle placement failed: vehicle body is outside the defender deployment region."
			return "Vehicle placement failed: vehicle body is outside the deployment region."
		"unknown_side":
			return "Vehicle placement failed: side '%s' is not attacker or defender." % side_id
		"inside_blocking_obstacle":
			return "Vehicle placement failed: vehicle body intersects a movement-blocking obstacle."
		"overlaps_vehicle":
			return "Vehicle placement failed: vehicle body overlaps another vehicle."
		"overlaps_participant":
			return "Vehicle placement failed: vehicle body overlaps a positioned participant."
		_:
			return "Vehicle placement failed: pose is not legal (%s)." % error_code

campaign/actions/deployment_service.gd:
class_name DeploymentService
extends RefCounted


static func deploy(game_state: GameState, request: DeploymentRequest) -> DeploymentResult:
	if game_state == null:
		return DeploymentResult.failed("null_game_state", "Deployment failed: game_state is null.")
	if request == null:
		return DeploymentResult.failed("null_request", "Deployment failed: request is null.")
	if request.force_id.is_empty():
		return DeploymentResult.failed("empty_force_id", "Deployment failed: force_id is empty.")
	if request.faction_id.is_empty():
		return DeploymentResult.failed("invalid_faction", "Deployment failed: faction_id is empty.")
	if request.origin_stronghold_id.is_empty():
		return DeploymentResult.failed("invalid_origin", "Deployment failed: origin_stronghold_id is empty.")
	if request.destination_location_id.is_empty():
		return DeploymentResult.failed("invalid_destination", "Deployment failed: destination_location_id is empty.")
	if request.movement_budget < 0.0:
		return DeploymentResult.failed("invalid_movement_budget", "Deployment failed: movement_budget is negative.")
	if game_state.has_traveling_force(request.force_id):
		return DeploymentResult.failed("duplicate_force_id", "Deployment failed: force_id '%s' already exists." % request.force_id)

	if not game_state.has_faction(request.faction_id):
		return DeploymentResult.failed("invalid_faction", "Deployment failed: faction '%s' does not exist." % request.faction_id)

	var origin_location: MapLocation = game_state.get_map_location(request.origin_stronghold_id)
	if origin_location == null:
		return DeploymentResult.failed("invalid_origin", "Deployment failed: origin '%s' does not exist." % request.origin_stronghold_id)
	if not (origin_location is Stronghold):
		return DeploymentResult.failed("invalid_origin", "Deployment failed: origin '%s' is not a Stronghold." % request.origin_stronghold_id)
	var origin: Stronghold = origin_location as Stronghold
	if origin.owner_faction_id != request.faction_id:
		return DeploymentResult.failed("origin_wrong_faction", "Deployment failed: origin '%s' is not owned by faction '%s'." % [request.origin_stronghold_id, request.faction_id])
	if origin.road_node_id.is_empty():
		return DeploymentResult.failed("origin_missing_road_node", "Deployment failed: origin '%s' has no road_node_id." % request.origin_stronghold_id)

	var destination: MapLocation = game_state.get_map_location(request.destination_location_id)
	if destination == null:
		return DeploymentResult.failed("invalid_destination", "Deployment failed: destination '%s' does not exist." % request.destination_location_id)
	if destination.road_node_id.is_empty():
		return DeploymentResult.failed("destination_missing_road_node", "Deployment failed: destination '%s' has no road_node_id." % request.destination_location_id)

	var soldier_result: DeploymentResult = _validate_soldiers(game_state, request, origin)
	if not soldier_result.success:
		return soldier_result
	var vehicle_result: DeploymentResult = _validate_vehicles(game_state, request, origin)
	if not vehicle_result.success:
		return vehicle_result

	if request.soldier_ids.is_empty():
		return DeploymentResult.failed("no_soldiers", "Deployment failed: at least one soldier must be selected.")
	if request.vehicle_ids.is_empty():
		return DeploymentResult.failed("no_vehicles", "Deployment failed: at least one vehicle must be selected.")

	if request.vehicle_ids.size()>request.soldier_ids.size():
		return DeploymentResult.failed("insufficient_drivers", "Deployment failed: every vehicle needs a soldier to drive it.")

	var soldier_group: SoldierGroup = SoldierGroup.new()
	for soldier_id: String in request.soldier_ids:
		soldier_group.add_soldier_id(soldier_id)
	var vehicle_group: VehicleGroup = VehicleGroup.new()
	for vehicle_id: String in request.vehicle_ids:
		vehicle_group.add_vehicle_id(vehicle_id)
	var transport_capacity: int = vehicle_group.get_total_passenger_capacity(game_state)
	if request.soldier_ids.size() > transport_capacity:
		return DeploymentResult.failed("insufficient_transport", "Deployment failed: soldier count %s exceeds transport capacity %s." % [request.soldier_ids.size(), transport_capacity])

	var exclusivity_result: DeploymentResult = _validate_exclusivity(game_state, request)
	if not exclusivity_result.success:
		return exclusivity_result

	var graph: RoadGraph = game_state.road_graph
	if graph == null:
		return DeploymentResult.failed("invalid_origin_road_node", "Deployment failed: road graph is missing.")
	if not graph.has_node(origin.road_node_id):
		return DeploymentResult.failed("invalid_origin_road_node", "Deployment failed: origin road node '%s' is not in the road graph." % origin.road_node_id)
	if not graph.has_node(destination.road_node_id):
		return DeploymentResult.failed("invalid_destination_road_node", "Deployment failed: destination road node '%s' is not in the road graph." % destination.road_node_id)
	var route: Array[String] = graph.find_route(origin.road_node_id, destination.road_node_id)
	if route.is_empty():
		return DeploymentResult.failed("no_route", "Deployment failed: no route from '%s' to '%s'." % [origin.road_node_id, destination.road_node_id])

	var convoy_movement: float = vehicle_group.get_movement_per_turn(game_state)
	var actual_launch_budget: float = minf(request.movement_budget, convoy_movement)
	var force: TravelingForce = TravelingForce.new(
		request.force_id,
		request.faction_id,
		request.origin_stronghold_id,
		request.destination_location_id,
		route,
		convoy_movement,
		"traveling_outbound"
	)
	force.soldier_group = soldier_group
	force.vehicle_group = vehicle_group
	force.movement_per_turn = convoy_movement
	force.movement_remaining = actual_launch_budget
	game_state.add_traveling_force(force)
	var unused_movement: float = force.advance(actual_launch_budget, graph)
	force.movement_remaining = unused_movement
	var reached_destination: bool = force.travel_state == "at_destination"
	return DeploymentResult.succeeded(force.id, reached_destination, unused_movement)


static func _validate_soldiers(game_state: GameState, request: DeploymentRequest, origin: Stronghold) -> DeploymentResult:
	var seen_ids: Dictionary[String, bool] = {}
	for soldier_id: String in request.soldier_ids:
		if soldier_id.is_empty():
			return DeploymentResult.failed("empty_soldier_id", "Deployment failed: a requested soldier id is empty.")
		if seen_ids.has(soldier_id):
			return DeploymentResult.failed("duplicate_soldier_id", "Deployment failed: duplicate soldier id '%s'." % soldier_id)
		seen_ids[soldier_id] = true
		if not game_state.has_soldier(soldier_id):
			return DeploymentResult.failed("invalid_soldier", "Deployment failed: soldier '%s' does not exist." % soldier_id)
		var soldier: Soldier = game_state.get_soldier(soldier_id)
		if soldier.faction_id != request.faction_id:
			return DeploymentResult.failed("soldier_wrong_faction", "Deployment failed: soldier '%s' does not belong to faction '%s'." % [soldier_id, request.faction_id])
		if soldier.home_stronghold_id != request.origin_stronghold_id:
			return DeploymentResult.failed("soldier_wrong_home", "Deployment failed: soldier '%s' home is not origin '%s'." % [soldier_id, request.origin_stronghold_id])
		if not origin.has_soldier_id(soldier_id):
			return DeploymentResult.failed("soldier_not_at_origin", "Deployment failed: origin '%s' does not contain soldier '%s'." % [request.origin_stronghold_id, soldier_id])
		if not soldier.garrison_hq_id.is_empty():
			return DeploymentResult.failed(
				"soldier_in_hq_garrison",
				"Deployment failed: soldier '%s' is garrisoned at NeighborhoodHQ '%s'."
				% [soldier_id, soldier.garrison_hq_id]
			)
	return DeploymentResult.succeeded("", false, 0.0)


static func _validate_vehicles(game_state: GameState, request: DeploymentRequest, origin: Stronghold) -> DeploymentResult:
	var seen_ids: Dictionary[String, bool] = {}
	for vehicle_id: String in request.vehicle_ids:
		if vehicle_id.is_empty():
			return DeploymentResult.failed("empty_vehicle_id", "Deployment failed: a requested vehicle id is empty.")
		if seen_ids.has(vehicle_id):
			return DeploymentResult.failed("duplicate_vehicle_id", "Deployment failed: duplicate vehicle id '%s'." % vehicle_id)
		seen_ids[vehicle_id] = true
		if not game_state.has_vehicle(vehicle_id):
			return DeploymentResult.failed("invalid_vehicle", "Deployment failed: vehicle '%s' does not exist." % vehicle_id)
		var vehicle: Vehicle = game_state.get_vehicle(vehicle_id)
		if vehicle.faction_id != request.faction_id:
			return DeploymentResult.failed("vehicle_wrong_faction", "Deployment failed: vehicle '%s' does not belong to faction '%s'." % [vehicle_id, request.faction_id])
		if vehicle.home_stronghold_id != request.origin_stronghold_id:
			return DeploymentResult.failed("vehicle_wrong_home", "Deployment failed: vehicle '%s' home is not origin '%s'." % [vehicle_id, request.origin_stronghold_id])
		if not origin.has_vehicle_id(vehicle_id):
			return DeploymentResult.failed("vehicle_not_at_origin", "Deployment failed: origin '%s' does not contain vehicle '%s'." % [request.origin_stronghold_id, vehicle_id])
	return DeploymentResult.succeeded("", false, 0.0)


static func _validate_exclusivity(game_state: GameState, request: DeploymentRequest) -> DeploymentResult:
	for soldier_id: String in request.soldier_ids:
		if _is_soldier_in_active_force(game_state, soldier_id):
			return DeploymentResult.failed("soldier_already_deployed", "Deployment failed: soldier '%s' is already deployed in an active force." % soldier_id)
	for vehicle_id: String in request.vehicle_ids:
		if _is_vehicle_in_active_force(game_state, vehicle_id):
			return DeploymentResult.failed("vehicle_already_deployed", "Deployment failed: vehicle '%s' is already deployed in an active force." % vehicle_id)
	return DeploymentResult.succeeded("", false, 0.0)


static func _is_force_active(force: TravelingForce) -> bool:
	if force == null:
		return false
	return force.travel_state != "complete"


static func _is_soldier_in_active_force(game_state: GameState, soldier_id: String) -> bool:
	if game_state == null:
		return false
	return game_state.is_soldier_in_active_traveling_force(soldier_id)


static func _is_vehicle_in_active_force(game_state: GameState, vehicle_id: String) -> bool:
	for force_id: String in game_state.traveling_forces:
		var force: TravelingForce = game_state.get_traveling_force(force_id)
		if not _is_force_active(force):
			continue
		if force.vehicle_group != null and force.vehicle_group.has_vehicle_id(vehicle_id):
			return true
	return false

