class_name DiplomacyService
extends RefCounted

const FactionRelationship := preload("res://campaign/diplomacy/faction_relationship.gd")
const DiplomacyResult := preload("res://campaign/diplomacy/diplomacy_result.gd")


static func are_at_war(
	game_state: GameState,
	faction_one_id: String,
	faction_two_id: String
) -> bool:
	if game_state == null:
		return false
	if faction_one_id.is_empty() or faction_two_id.is_empty():
		return false
	if faction_one_id == faction_two_id:
		return false
	var relationship: FactionRelationship = game_state.get_relationship_between(
		faction_one_id,
		faction_two_id
	)
	if relationship == null:
		return false
	return relationship.is_at_war


static func declare_war(
	game_state: GameState,
	faction_one_id: String,
	faction_two_id: String
) -> DiplomacyResult:
	if game_state == null:
		return DiplomacyResult.failed(
			"null_game_state",
			"Declare war failed: game_state is null."
		)
	if faction_one_id.is_empty():
		return DiplomacyResult.failed(
			"empty_faction_a",
			"Declare war failed: first faction id is empty.",
			faction_one_id,
			faction_two_id
		)
	if faction_two_id.is_empty():
		return DiplomacyResult.failed(
			"empty_faction_b",
			"Declare war failed: second faction id is empty.",
			faction_one_id,
			faction_two_id
		)
	if faction_one_id == faction_two_id:
		return DiplomacyResult.failed(
			"same_faction",
			"Declare war failed: a faction cannot declare war on itself.",
			faction_one_id,
			faction_two_id
		)
	if not game_state.has_faction(faction_one_id):
		return DiplomacyResult.failed(
			"invalid_faction_a",
			"Declare war failed: faction '%s' does not exist." % faction_one_id,
			faction_one_id,
			faction_two_id
		)
	if not game_state.has_faction(faction_two_id):
		return DiplomacyResult.failed(
			"invalid_faction_b",
			"Declare war failed: faction '%s' does not exist." % faction_two_id,
			faction_one_id,
			faction_two_id
		)
	var faction_a: Faction = game_state.get_faction(faction_one_id)
	var faction_b: Faction = game_state.get_faction(faction_two_id)
	if not (faction_a is MajorGang):
		return DiplomacyResult.failed(
			"faction_a_not_major_gang",
			"Declare war failed: faction '%s' is not a MajorGang." % faction_one_id,
			faction_one_id,
			faction_two_id
		)
	if not (faction_b is MajorGang):
		return DiplomacyResult.failed(
			"faction_b_not_major_gang",
			"Declare war failed: faction '%s' is not a MajorGang." % faction_two_id,
			faction_one_id,
			faction_two_id
		)

	var relationship: FactionRelationship = game_state.get_relationship_between(
		faction_one_id,
		faction_two_id
	)
	if relationship == null:
		relationship = FactionRelationship.new(faction_one_id, faction_two_id, true)
		if not game_state.add_relationship(relationship):
			push_error(
				"DiplomacyService.declare_war: failed to add relationship between '%s' and '%s'."
				% [faction_one_id, faction_two_id]
			)
			return DiplomacyResult.failed(
				"relationship_insert_failed",
				"Declare war failed: could not add relationship between '%s' and '%s'."
				% [faction_one_id, faction_two_id],
				faction_one_id,
				faction_two_id
			)
	else:
		relationship.is_at_war = true

	return DiplomacyResult.succeeded(
		relationship.faction_a_id,
		relationship.faction_b_id,
		true
	)

class_name FactionRelationship
extends RefCounted

const KEY_DELIMITER := "|"

var faction_a_id: String = ""
var faction_b_id: String = ""
var is_at_war: bool = false


func _init(
	p_faction_a_id: String = "",
	p_faction_b_id: String = "",
	p_is_at_war: bool = false
) -> void:
	_assign_canonical_pair(p_faction_a_id, p_faction_b_id)
	is_at_war = p_is_at_war


static func make_key(faction_one_id: String, faction_two_id: String) -> String:
	if faction_one_id.is_empty() or faction_two_id.is_empty():
		return ""
	if faction_one_id == faction_two_id:
		return ""
	if faction_one_id < faction_two_id:
		return "%s%s%s" % [faction_one_id, KEY_DELIMITER, faction_two_id]
	return "%s%s%s" % [faction_two_id, KEY_DELIMITER, faction_one_id]


func contains_faction(faction_id: String) -> bool:
	if faction_id.is_empty():
		return false
	return faction_id == faction_a_id or faction_id == faction_b_id


func get_other_faction_id(faction_id: String) -> String:
	if faction_id == faction_a_id:
		return faction_b_id
	if faction_id == faction_b_id:
		return faction_a_id
	return ""


func canonicalize() -> void:
	_assign_canonical_pair(faction_a_id, faction_b_id)


func to_dict() -> Dictionary:
	return {
		"faction_a_id": faction_a_id,
		"faction_b_id": faction_b_id,
		"is_at_war": is_at_war,
	}


func from_dict(data: Dictionary) -> void:
	_assign_canonical_pair(
		str(data.get("faction_a_id", "")),
		str(data.get("faction_b_id", ""))
	)
	is_at_war = bool(data.get("is_at_war", false))


func _assign_canonical_pair(faction_one_id: String, faction_two_id: String) -> void:
	if faction_one_id.is_empty() or faction_two_id.is_empty() or faction_one_id == faction_two_id:
		faction_a_id = ""
		faction_b_id = ""
		return
	if faction_one_id < faction_two_id:
		faction_a_id = faction_one_id
		faction_b_id = faction_two_id
		return
	faction_a_id = faction_two_id
	faction_b_id = faction_one_id

