class_name NeighborhoodHQAttackService
extends RefCounted

const DiplomacyService := preload("res://campaign/diplomacy/diplomacy_service.gd")
const DeploymentRequest := preload("res://campaign/actions/deployment_request.gd")
const ExistingForceMissionRequest := preload("res://campaign/missions/existing_force_mission_request.gd")
const ExistingForceMissionResult := preload("res://campaign/missions/existing_force_mission_result.gd")
const MissionRequest := preload("res://campaign/missions/mission_request.gd")
const MissionResult := preload("res://campaign/missions/mission_result.gd")
const MissionService := preload("res://campaign/missions/mission_service.gd")
const NeighborhoodHQAttackResult := preload("res://campaign/missions/neighborhood_hq_attack_result.gd")

const MISSION_TYPE_CAPTURE_HQ := "capture_neighborhood_hq"


class _Authorization extends RefCounted:
	var ok: bool = false
	var error_code: String = ""
	var error_message: String = ""
	var attacker_faction_id: String = ""
	var defender_faction_id: String = ""
	var neighborhood_id: String = ""
	var hq_location_id: String = ""


static func launch_from_stronghold(
	game_state: GameState,
	mission_request: MissionRequest
) -> NeighborhoodHQAttackResult:
	if game_state == null:
		return NeighborhoodHQAttackResult.failed(
			"null_game_state",
			"Neighborhood HQ attack failed: game_state is null."
		)
	if mission_request == null:
		return NeighborhoodHQAttackResult.failed(
			"null_request",
			"Neighborhood HQ attack failed: request is null."
		)
	if mission_request.mission_type_id != MISSION_TYPE_CAPTURE_HQ:
		return NeighborhoodHQAttackResult.failed(
			"invalid_mission_type",
			"Neighborhood HQ attack failed: mission type is '%s', not capture_neighborhood_hq."
			% mission_request.mission_type_id,
			mission_request.mission_id
		)
	var deployment_request: DeploymentRequest = mission_request.deployment_request
	var attacker_faction_id: String = ""
	var target_location_id: String = ""
	var requested_force_id: String = ""
	if deployment_request != null:
		attacker_faction_id = deployment_request.faction_id
		target_location_id = deployment_request.destination_location_id
		requested_force_id = deployment_request.force_id
	var auth: _Authorization = _authorize_territory(
		game_state,
		attacker_faction_id,
		target_location_id
	)
	if not auth.ok:
		return _result_from_auth_failure(auth, mission_request.mission_id, requested_force_id)
	var mission_result: MissionResult = MissionService.launch(game_state, mission_request)
	return _result_from_mission_launch(mission_result, auth)


static func launch_from_existing_force(
	game_state: GameState,
	request: ExistingForceMissionRequest
) -> NeighborhoodHQAttackResult:
	if game_state == null:
		return NeighborhoodHQAttackResult.failed(
			"null_game_state",
			"Neighborhood HQ attack failed: game_state is null."
		)
	if request == null:
		return NeighborhoodHQAttackResult.failed(
			"null_request",
			"Neighborhood HQ attack failed: request is null."
		)
	if request.mission_type_id != MISSION_TYPE_CAPTURE_HQ:
		return NeighborhoodHQAttackResult.failed(
			"invalid_mission_type",
			"Neighborhood HQ attack failed: mission type is '%s', not capture_neighborhood_hq."
			% request.mission_type_id,
			request.mission_id,
			request.force_id
		)
	var attacker_faction_id: String = ""
	if not request.force_id.is_empty() and game_state.has_traveling_force(request.force_id):
		var force: TravelingForce = game_state.get_traveling_force(request.force_id)
		if force != null:
			attacker_faction_id = force.faction_id
	var auth: _Authorization = _authorize_territory(
		game_state,
		attacker_faction_id,
		request.target_location_id
	)
	if not auth.ok:
		return _result_from_auth_failure(auth, request.mission_id, request.force_id)
	var existing_result: ExistingForceMissionResult = MissionService.launch_from_existing_force(
		game_state,
		request
	)
	return _result_from_existing_force_launch(existing_result, auth)


static func _authorize_territory(
	game_state: GameState,
	attacker_faction_id: String,
	target_location_id: String
) -> _Authorization:
	var auth: _Authorization = _Authorization.new()
	auth.attacker_faction_id = attacker_faction_id
	auth.hq_location_id = target_location_id
	if attacker_faction_id.is_empty() or not game_state.has_faction(attacker_faction_id):
		auth.error_code = "invalid_attacker_faction"
		auth.error_message = (
			"Neighborhood HQ attack failed: attacker faction '%s' does not exist."
			% attacker_faction_id
		)
		return auth
	var attacker: Faction = game_state.get_faction(attacker_faction_id)
	if not (attacker is MajorGang):
		auth.error_code = "attacker_not_major_gang"
		auth.error_message = (
			"Neighborhood HQ attack failed: attacker '%s' is not a MajorGang."
			% attacker_faction_id
		)
		return auth
	if target_location_id.is_empty() or not game_state.has_map_location(target_location_id):
		auth.error_code = "invalid_target_location"
		auth.error_message = (
			"Neighborhood HQ attack failed: target '%s' does not exist."
			% target_location_id
		)
		return auth
	var target_location: MapLocation = game_state.get_map_location(target_location_id)
	if not (target_location is NeighborhoodHQ):
		auth.neighborhood_id = target_location.neighborhood_id
		auth.error_code = "target_not_neighborhood_hq"
		auth.error_message = (
			"Neighborhood HQ attack failed: target '%s' is not a NeighborhoodHQ."
			% target_location_id
		)
		return auth
	var hq: NeighborhoodHQ = target_location as NeighborhoodHQ
	auth.hq_location_id = hq.id
	if hq.neighborhood_id.is_empty():
		auth.error_code = "missing_neighborhood"
		auth.error_message = (
			"Neighborhood HQ attack failed: HQ '%s' has empty neighborhood_id."
			% hq.id
		)
		return auth
	auth.neighborhood_id = hq.neighborhood_id
	if not game_state.has_neighborhood(hq.neighborhood_id):
		auth.error_code = "invalid_neighborhood"
		auth.error_message = (
			"Neighborhood HQ attack failed: neighborhood '%s' does not exist."
			% hq.neighborhood_id
		)
		return auth
	var neighborhood: Neighborhood = game_state.get_neighborhood(hq.neighborhood_id)
	if neighborhood.owner_faction_id != hq.owner_faction_id:
		auth.defender_faction_id = neighborhood.owner_faction_id
		auth.error_code = "territory_owner_mismatch"
		auth.error_message = (
			"Neighborhood HQ attack failed: neighborhood '%s' owner '%s' does not match HQ '%s' owner '%s'."
			% [neighborhood.id, neighborhood.owner_faction_id, hq.id, hq.owner_faction_id]
		)
		return auth
	var defender_faction_id: String = neighborhood.owner_faction_id
	auth.defender_faction_id = defender_faction_id
	if defender_faction_id == attacker_faction_id:
		auth.error_code = "already_controlled"
		auth.error_message = (
			"Neighborhood HQ attack failed: neighborhood '%s' and HQ '%s' are already controlled by '%s'."
			% [neighborhood.id, hq.id, attacker_faction_id]
		)
		return auth
	if not defender_faction_id.is_empty() and not game_state.has_faction(defender_faction_id):
		auth.error_code = "invalid_defender_faction"
		auth.error_message = (
			"Neighborhood HQ attack failed: defender faction '%s' does not exist."
			% defender_faction_id
		)
		return auth
	if not defender_faction_id.is_empty():
		if not DiplomacyService.are_at_war(game_state, attacker_faction_id, defender_faction_id):
			auth.error_code = "formal_war_required"
			auth.error_message = (
				"Neighborhood HQ attack failed: '%s' and '%s' are not formally at war."
				% [attacker_faction_id, defender_faction_id]
			)
			return auth
	auth.ok = true
	return auth


static func _result_from_auth_failure(
	auth: _Authorization,
	mission_id: String,
	force_id: String
) -> NeighborhoodHQAttackResult:
	return NeighborhoodHQAttackResult.failed(
		auth.error_code,
		auth.error_message,
		mission_id,
		force_id,
		auth.attacker_faction_id,
		auth.defender_faction_id,
		auth.neighborhood_id,
		auth.hq_location_id
	)


static func _result_from_mission_launch(
	mission_result: MissionResult,
	auth: _Authorization
) -> NeighborhoodHQAttackResult:
	if mission_result.success:
		return NeighborhoodHQAttackResult.succeeded(
			mission_result.mission_id,
			mission_result.force_id,
			auth.attacker_faction_id,
			auth.defender_faction_id,
			auth.neighborhood_id,
			auth.hq_location_id,
			mission_result.mission_state,
			mission_result.mission_state == "awaiting_resolution"
		)
	return NeighborhoodHQAttackResult.failed(
		mission_result.error_code,
		mission_result.error_message,
		mission_result.mission_id,
		mission_result.force_id,
		auth.attacker_faction_id,
		auth.defender_faction_id,
		auth.neighborhood_id,
		auth.hq_location_id,
		mission_result.mission_state,
		false
	)


static func _result_from_existing_force_launch(
	existing_result: ExistingForceMissionResult,
	auth: _Authorization
) -> NeighborhoodHQAttackResult:
	if existing_result.success:
		return NeighborhoodHQAttackResult.succeeded(
			existing_result.mission_id,
			existing_result.force_id,
			auth.attacker_faction_id,
			auth.defender_faction_id,
			auth.neighborhood_id,
			auth.hq_location_id,
			existing_result.mission_state,
			existing_result.reached_destination
		)
	return NeighborhoodHQAttackResult.failed(
		existing_result.error_code,
		existing_result.error_message,
		existing_result.mission_id,
		existing_result.force_id,
		auth.attacker_faction_id,
		auth.defender_faction_id,
		auth.neighborhood_id,
		auth.hq_location_id,
		existing_result.mission_state,
		false
	)

campaign/travel/force_movement_service.g:
class_name ForceMovementService
extends RefCounted

const ForceMoveRequest := preload("res://campaign/travel/force_move_request.gd")
const ForceMoveResult := preload("res://campaign/travel/force_move_result.gd")
const CampaignMission := preload("res://campaign/missions/campaign_mission.gd")


static func move_to_location(game_state: GameState, request: ForceMoveRequest) -> ForceMoveResult:
	if game_state == null:
		return ForceMoveResult.failed("null_game_state", "Force movement failed: game_state is null.")
	if request == null:
		return ForceMoveResult.failed("null_request", "Force movement failed: request is null.")
	if request.force_id.is_empty():
		return ForceMoveResult.failed("empty_force_id", "Force movement failed: force_id is empty.")
	if request.destination_location_id.is_empty():
		return ForceMoveResult.failed(
			"empty_destination_id",
			"Force movement failed: destination_location_id is empty.",
			request.force_id
		)
	if not game_state.has_traveling_force(request.force_id):
		return ForceMoveResult.failed(
			"invalid_force",
			"Force movement failed: force '%s' does not exist." % request.force_id,
			request.force_id,
			request.destination_location_id
		)
	var force: TravelingForce = game_state.get_traveling_force(request.force_id)
	if force.travel_state == "complete":
		return ForceMoveResult.failed(
			"force_complete",
			"Force movement failed: force '%s' is complete." % force.id,
			force.id,
			request.destination_location_id
		)
	if force.travel_state != "at_destination":
		return ForceMoveResult.failed(
			"force_not_at_node",
			"Force movement failed: force '%s' is '%s', not at a destination node." % [force.id, force.travel_state],
			force.id,
			request.destination_location_id
		)
	if _force_has_unresolved_mission(game_state, force.id):
		return ForceMoveResult.failed(
			"force_has_unresolved_mission",
			"Force movement failed: force '%s' has an unresolved mission." % force.id,
			force.id,
			request.destination_location_id
		)
	var destination: MapLocation = game_state.get_map_location(request.destination_location_id)
	if destination == null:
		return ForceMoveResult.failed(
			"invalid_destination",
			"Force movement failed: destination '%s' does not exist." % request.destination_location_id,
			force.id,
			request.destination_location_id
		)
	if destination.road_node_id.is_empty():
		return ForceMoveResult.failed(
			"destination_missing_road_node",
			"Force movement failed: destination '%s' has no road_node_id." % destination.id,
			force.id,
			destination.id
		)
	var graph: RoadGraph = game_state.road_graph
	if graph == null or not graph.has_node(destination.road_node_id):
		return ForceMoveResult.failed(
			"invalid_destination_road_node",
			"Force movement failed: destination road node '%s' is not in the road graph." % destination.road_node_id,
			force.id,
			destination.id
		)
	var current_node_id: String = force.get_current_road_node_id()
	if current_node_id.is_empty():
		return ForceMoveResult.failed(
			"invalid_current_road_node",
			"Force movement failed: force '%s' has no current road node." % force.id,
			force.id,
			destination.id
		)
	if not graph.has_node(current_node_id):
		return ForceMoveResult.failed(
			"invalid_current_road_node",
			"Force movement failed: current road node '%s' is not in the road graph." % current_node_id,
			force.id,
			destination.id
		)
	var route: Array[String] = graph.find_route(current_node_id, destination.road_node_id)
	if route.is_empty():
		return ForceMoveResult.failed(
			"no_route",
			"Force movement failed: no route from '%s' to '%s'." % [current_node_id, destination.road_node_id],
			force.id,
			destination.id
		)
	if force.movement_remaining < 0.0:
		return ForceMoveResult.failed(
			"invalid_movement_remaining",
			"Force movement failed: force '%s' has negative movement remaining." % force.id,
			force.id,
			destination.id
		)

	force.destination_location_id = destination.id
	force.route_node_ids.clear()
	for node_id: String in route:
		force.route_node_ids.append(node_id)
	force.route_segment_index = 0
	force.distance_into_segment = 0.0
	if route.size() <= 1:
		force.travel_state = "at_destination"
		return ForceMoveResult.succeeded(force.id, destination.id, true, 0.0, force.movement_remaining)

	force.travel_state = "traveling_outbound"
	var movement_before: float = force.movement_remaining
	var unused_movement: float = force.advance(movement_before, graph)
	force.movement_remaining = unused_movement
	var movement_spent: float = movement_before - force.movement_remaining
	if movement_spent < 0.0:
		movement_spent = 0.0
	if movement_spent > movement_before:
		movement_spent = movement_before
	var reached_destination: bool = force.travel_state == "at_destination"
	return ForceMoveResult.succeeded(
		force.id,
		destination.id,
		reached_destination,
		movement_spent,
		force.movement_remaining
	)


static func _force_has_unresolved_mission(game_state: GameState, force_id: String) -> bool:
	var mission_ids: Array[String] = []
	for mission_id: String in game_state.missions:
		mission_ids.append(mission_id)
	mission_ids.sort()
	for mission_id: String in mission_ids:
		var mission: CampaignMission = game_state.get_mission(mission_id)
		if mission == null or mission.force_id != force_id:
			continue
		if (
			mission.mission_state == "resolved_success"
			or mission.mission_state == "resolved_failure"
			or mission.mission_state == "complete"
		):
			continue
		return true
	return false

campaign/travel/traveling_force.gd:
class_name TravelingForce
extends RefCounted

var id: String = ""
var faction_id: String = ""
var origin_location_id: String = ""
var destination_location_id: String = ""
var route_node_ids: Array[String] = []
var route_segment_index: int = 0
var distance_into_segment: float = 0.0
var movement_per_turn: float = 0.0
var movement_remaining: float = 0.0:
	set(value):
		movement_remaining = maxf(value, 0.0)
var travel_state: String = ""
var vehicle_group: VehicleGroup = VehicleGroup.new()
var soldier_group: SoldierGroup = SoldierGroup.new()


func _init(
	p_id: String = "",
	p_faction_id: String = "",
	p_origin_location_id: String = "",
	p_destination_location_id: String = "",
	p_route_node_ids: Array[String] = [],
	p_movement_per_turn: float = 0.0,
	p_travel_state: String = ""
) -> void:
	id = p_id
	faction_id = p_faction_id
	origin_location_id = p_origin_location_id
	destination_location_id = p_destination_location_id
	for node_id in p_route_node_ids:
		route_node_ids.append(str(node_id))
	movement_per_turn = p_movement_per_turn
	travel_state = p_travel_state


func advance(distance_budget: float, road_graph: RoadGraph) -> float:
	if distance_budget < 0.0:
		push_error("TravelingForce.advance: negative movement budget is not allowed (id='%s', budget=%s)." % [id, distance_budget])
		return distance_budget
	if travel_state != "traveling_outbound" and travel_state != "traveling_return":
		return distance_budget
	if route_node_ids.size() <= 1:
		_arrive_at_destination(0.0)
		return distance_budget
	if distance_budget == 0.0:
		return 0.0
	if road_graph == null:
		push_error("TravelingForce.advance: road_graph is null (id='%s')." % id)
		return distance_budget

	var remaining := distance_budget
	while remaining > 0.0:
		var last_segment_index := route_node_ids.size() - 2
		if route_segment_index > last_segment_index:
			_arrive_at_destination(distance_into_segment)
			break
		var from_id := route_node_ids[route_segment_index]
		var to_id := route_node_ids[route_segment_index + 1]
		var segment := road_graph.get_open_segment_between(from_id, to_id)
		if segment == null:
			push_error("TravelingForce.advance: required open segment missing between '%s' and '%s' (force='%s')." % [from_id, to_id, id])
			break
		if distance_into_segment < 0.0:
			distance_into_segment = 0.0
		var remaining_on_segment := segment.distance - distance_into_segment
		if remaining_on_segment <= 0.0:
			if route_segment_index == last_segment_index:
				_arrive_at_destination(segment.distance)
				break
			route_segment_index += 1
			distance_into_segment = 0.0
			continue
		if remaining < remaining_on_segment:
			distance_into_segment += remaining
			remaining = 0.0
			break
		remaining -= remaining_on_segment
		if route_segment_index == last_segment_index:
			_arrive_at_destination(segment.distance)
			break
		route_segment_index += 1
		distance_into_segment = 0.0
	if distance_into_segment < 0.0:
		distance_into_segment = 0.0
	return remaining


func refresh_turn_movement() -> float:
	movement_remaining = maxf(movement_per_turn, 0.0)
	return movement_remaining


func get_current_road_node_id() -> String:
	if route_node_ids.is_empty():
		return ""
	if travel_state == "at_destination":
		return str(route_node_ids[route_node_ids.size() - 1])
	if is_equal_approx(distance_into_segment, 0.0):
		if route_segment_index >= 0 and route_segment_index < route_node_ids.size():
			return str(route_node_ids[route_segment_index])
	return ""


func refresh_movement_from_vehicles(game_state: GameState) -> float:
	if vehicle_group == null:
		vehicle_group = VehicleGroup.new()
	movement_per_turn = vehicle_group.get_movement_per_turn(game_state)
	return movement_per_turn


func get_total_strategic_strength(game_state: GameState) -> float:
	if soldier_group == null:
		soldier_group = SoldierGroup.new()
	return soldier_group.get_total_strategic_strength(game_state)


func get_transport_capacity(game_state: GameState) -> int:
	if vehicle_group == null:
		vehicle_group = VehicleGroup.new()
	return vehicle_group.get_total_passenger_capacity(game_state)


func has_valid_transport_capacity(game_state: GameState) -> bool:
	if soldier_group == null:
		soldier_group = SoldierGroup.new()
	return soldier_group.soldier_ids.size() <= get_transport_capacity(game_state)


func to_dict() -> Dictionary:
	var route_data: Array[String] = []
	for node_id in route_node_ids:
		route_data.append(node_id)
	if vehicle_group == null:
		vehicle_group = VehicleGroup.new()
	if soldier_group == null:
		soldier_group = SoldierGroup.new()
	return {
		"id": id,
		"faction_id": faction_id,
		"origin_location_id": origin_location_id,
		"destination_location_id": destination_location_id,
		"route_node_ids": route_data,
		"route_segment_index": route_segment_index,
		"distance_into_segment": distance_into_segment,
		"movement_per_turn": movement_per_turn,
		"movement_remaining": movement_remaining,
		"travel_state": travel_state,
		"vehicle_group": vehicle_group.to_dict(),
		"soldier_group": soldier_group.to_dict(),
	}


func from_dict(data: Dictionary) -> void:
	id = str(data.get("id", ""))
	faction_id = str(data.get("faction_id", ""))
	origin_location_id = str(data.get("origin_location_id", ""))
	destination_location_id = str(data.get("destination_location_id", ""))
	route_node_ids.clear()
	var route_data: Variant = data.get("route_node_ids", [])
	if route_data is Array:
		for node_id: Variant in route_data:
			route_node_ids.append(str(node_id))
	route_segment_index = maxi(int(data.get("route_segment_index", 0)), 0)
	distance_into_segment = maxf(float(data.get("distance_into_segment", 0.0)), 0.0)
	movement_per_turn = float(data.get("movement_per_turn", 0.0))
	movement_remaining = maxf(float(data.get("movement_remaining", 0.0)), 0.0)
	travel_state = str(data.get("travel_state", ""))
	if vehicle_group == null:
		vehicle_group = VehicleGroup.new()
	var group_data: Variant = data.get("vehicle_group", {})
	if group_data is Dictionary:
		vehicle_group.from_dict(group_data)
	else:
		if data.has("vehicle_group"):
			push_error("TravelingForce.from_dict: vehicle_group is not a Dictionary (id='%s'); loading empty group." % id)
		vehicle_group.from_dict({})
	if soldier_group == null:
		soldier_group = SoldierGroup.new()
	var soldier_group_data: Variant = data.get("soldier_group", {})
	if soldier_group_data is Dictionary:
		soldier_group.from_dict(soldier_group_data)
	else:
		if data.has("soldier_group"):
			push_error("TravelingForce.from_dict: soldier_group is not a Dictionary (id='%s'); loading empty group." % id)
		soldier_group.from_dict({})


func _arrive_at_destination(final_distance_into_segment: float) -> void:
	travel_state = "at_destination"
	var last_segment_index := route_node_ids.size() - 2
	if last_segment_index < 0:
		route_segment_index = 0
		distance_into_segment = 0.0
		return
	route_segment_index = last_segment_index
	distance_into_segment = maxf(final_distance_into_segment, 0.0)

