class_name TurnManager
extends RefCounted

const ForceTurnResult := preload("res://campaign/turns/force_turn_result.gd")
const TurnResult := preload("res://campaign/turns/turn_result.gd")
const MissionService := preload("res://campaign/missions/mission_service.gd")
const MissionResult := preload("res://campaign/missions/mission_result.gd")
const BusinessEconomyCatalog := preload("res://campaign/economy/business_economy_catalog.gd")
const EconomyService := preload("res://campaign/economy/economy_service.gd")
const EconomyTurnResult := preload("res://campaign/economy/economy_turn_result.gd")


static func advance_to_next_turn(
	game_state: GameState,
	business_catalog: BusinessEconomyCatalog = null
) -> TurnResult:
	if game_state == null:
		return TurnResult.failed("null_game_state", "Turn advancement failed: game_state is null.")
	if game_state.current_turn < 1:
		return TurnResult.failed(
			"invalid_current_turn",
			"Turn advancement failed: current_turn '%s' is invalid." % game_state.current_turn,
			game_state.current_turn,
			game_state.current_turn
		)

	var turn_before: int = game_state.current_turn
	game_state.current_turn = turn_before + 1
	var turn_after: int = game_state.current_turn

	# Ordered phases currently implemented:
	# 1. income / upkeep (when a business catalog is supplied)
	# 2. [future police disruption]
	# 3. force movement
	# 4. Mission arrival synchronization
	var economy_result: EconomyTurnResult = null
	if business_catalog != null:
		economy_result = EconomyService.process_turn_start(game_state, business_catalog)
	var force_results: Array[ForceTurnResult] = _process_force_movement(game_state)
	var mission_results: Array[MissionResult] = MissionService.sync_all_arrivals(game_state)
	return TurnResult.succeeded(turn_before, turn_after, force_results, mission_results, economy_result)


static func _process_force_movement(game_state: GameState) -> Array[ForceTurnResult]:
	var results: Array[ForceTurnResult] = []
	var force_ids: Array[String] = []
	for force_id: String in game_state.traveling_forces:
		force_ids.append(force_id)
	force_ids.sort()
	for force_id: String in force_ids:
		var force: TravelingForce = game_state.get_traveling_force(force_id)
		if force == null:
			results.append(
				ForceTurnResult.failed(
					"invalid_force",
					"Turn force processing failed: force '%s' is missing." % force_id,
					force_id
				)
			)
			continue
		results.append(_process_one_force(game_state, force))
	return results


static func _process_one_force(game_state: GameState, force: TravelingForce) -> ForceTurnResult:
	var state_before: String = force.travel_state
	if state_before == "complete":
		return ForceTurnResult.succeeded(
			force.id,
			0.0,
			0.0,
			force.movement_remaining,
			state_before,
			force.travel_state,
			false
		)

	var movement_refreshed: float = force.refresh_turn_movement()
	if state_before != "traveling_outbound" and state_before != "traveling_return":
		return ForceTurnResult.succeeded(
			force.id,
			movement_refreshed,
			0.0,
			force.movement_remaining,
			state_before,
			force.travel_state,
			false
		)

	var unused_movement: float = force.advance(force.movement_remaining, game_state.road_graph)
	force.movement_remaining = unused_movement
	var movement_spent: float = movement_refreshed - force.movement_remaining
	if movement_spent < 0.0:
		movement_spent = 0.0
	if movement_spent > movement_refreshed:
		movement_spent = movement_refreshed
	var reached_destination: bool = force.travel_state == "at_destination"
	var processing_error_code: String = ""
	var processing_error_message: String = ""
	if force.movement_remaining > 0.0 and not reached_destination:
		processing_error_code = _detect_advance_failure(force, game_state.road_graph)
		if processing_error_code == "null_road_graph":
			processing_error_message = "Turn force processing failed: road graph is missing (force='%s')." % force.id
		elif processing_error_code == "missing_open_segment":
			var from_id: String = ""
			var to_id: String = ""
			if force.route_segment_index >= 0 and force.route_segment_index + 1 < force.route_node_ids.size():
				from_id = str(force.route_node_ids[force.route_segment_index])
				to_id = str(force.route_node_ids[force.route_segment_index + 1])
			processing_error_message = (
				"Turn force processing failed: required open segment missing between '%s' and '%s' (force='%s')."
				% [from_id, to_id, force.id]
			)
	if not processing_error_code.is_empty():
		return ForceTurnResult.failed(
			processing_error_code,
			processing_error_message,
			force.id,
			movement_refreshed,
			movement_spent,
			force.movement_remaining,
			state_before,
			force.travel_state,
			reached_destination
		)
	return ForceTurnResult.succeeded(
		force.id,
		movement_refreshed,
		movement_spent,
		force.movement_remaining,
		state_before,
		force.travel_state,
		reached_destination
	)


static func _detect_advance_failure(force: TravelingForce, road_graph: RoadGraph) -> String:
	if force.travel_state != "traveling_outbound" and force.travel_state != "traveling_return":
		return ""
	if force.route_node_ids.size() <= 1:
		return ""
	var last_segment_index: int = force.route_node_ids.size() - 2
	if force.route_segment_index > last_segment_index:
		return ""
	if road_graph == null:
		return "null_road_graph"
	if force.route_segment_index < 0 or force.route_segment_index + 1 >= force.route_node_ids.size():
		return "missing_open_segment"
	var from_id: String = str(force.route_node_ids[force.route_segment_index])
	var to_id: String = str(force.route_node_ids[force.route_segment_index + 1])
	if road_graph.get_open_segment_between(from_id, to_id) == null:
		return "missing_open_segment"
	return ""

campaign/units/soldier_group.gd:
class_name SoldierGroup
extends RefCounted

var soldier_ids: Array[String] = []


func to_dict() -> Dictionary:
	var ids: Array[String] = []
	for soldier_id in soldier_ids:
		ids.append(soldier_id)
	return {
		"soldier_ids": ids,
	}


func from_dict(data: Dictionary) -> void:
	soldier_ids.clear()
	var ids_data: Variant = data.get("soldier_ids", [])
	if not (ids_data is Array):
		return
	for soldier_id: Variant in ids_data:
		add_soldier_id(str(soldier_id))


func add_soldier_id(soldier_id: String) -> bool:
	if soldier_id.is_empty():
		push_error("SoldierGroup.add_soldier_id: soldier id is empty.")
		return false
	if soldier_ids.has(soldier_id):
		push_error("SoldierGroup.add_soldier_id: duplicate soldier id '%s'." % soldier_id)
		return false
	soldier_ids.append(soldier_id)
	return true


func remove_soldier_id(soldier_id: String) -> bool:
	var index := soldier_ids.find(soldier_id)
	if index < 0:
		return false
	soldier_ids.remove_at(index)
	return true


func has_soldier_id(soldier_id: String) -> bool:
	return soldier_ids.has(soldier_id)


func get_total_strategic_strength(game_state: GameState) -> float:
	if game_state == null:
		push_error("SoldierGroup.get_total_strategic_strength: game_state is null.")
		return 0.0
	var total := 0.0
	for soldier_id in soldier_ids:
		var soldier: Soldier = game_state.get_soldier(soldier_id)
		if soldier == null:
			push_error("SoldierGroup.get_total_strategic_strength: missing soldier '%s'." % soldier_id)
			continue
		total += soldier.strategic_strength
	return total

campaign/vehicles/convoy_formation_catal:
extends RefCounted
# Slot packing changes faction logistics only. Every vehicle keeps its own
# capacity, driver, cost and collision body; it never becomes a composite car.
const Models=preload("res://campaign/vehicles/vehicle_model_catalog.gd")
static func motorcycle(id: String) -> bool:
 var m=Models.model(id)
 return m.get("vehicle_class","")=="two_wheelers" and m.get("body","")!="bicycle"
static func packs_motorcycles(faction_id: String) -> bool:
 return faction_id in ["stateline","blacktop","nbpd","trc"]
static func slots(models: Array,faction_id: String) -> Array:
 var result=[]
 for i in range(models.size()):
  var pack=packs_motorcycles(faction_id) and motorcycle(str(models[i]))
  var placed=false
  if pack:
   for group in result:
    if group.motorcycles and group.indices.size()<3:
     group.indices.append(i);placed=true;break
  if not placed:result.append({"indices":[i],"motorcycles":pack})
 return result
static func bed_capacity(model_id: String) -> int:
 return 2 if Models.model(model_id).get("body","") in ["pickup","crew_pickup"] else 0
static func manifest(models: Array,count: int,chosen: Array=[]) -> Dictionary:
 if not Models.convoy(models,count).valid:return {"valid":false,"error":"Convoy needs a driver per vehicle and a seat for every unit."}
 var rows=[]
 if not chosen.is_empty():
  if chosen.size()!=models.size():return {"valid":false,"error":"Passenger assignments must match the convoy vehicles."}
  var total=0
  for i in range(chosen.size()):
   if not chosen[i] is Dictionary:return {"valid":false,"error":"Invalid passenger assignment."}
   var n=chosen[i].get("units",0);var bed=chosen[i].get("bed",0)
   if not (n is int or n is float) or not (bed is int or bed is float):return {"valid":false,"error":"Passenger counts must be whole numbers."}
   if not is_finite(float(n)) or not is_finite(float(bed)) or float(n)!=float(int(n)) or float(bed)!=float(int(bed)):return {"valid":false,"error":"Passenger counts must be whole numbers."}
   if n<1 or n>int(Models.model(models[i]).unit_capacity) or bed<0 or bed>bed_capacity(models[i]) or bed>=n:return {"valid":false,"error":"Invalid capacity, driver or pickup-bed assignment."}
   total+=int(n);rows.append({"units":int(n),"bed":int(bed)})
  if total!=count:return {"valid":false,"error":"Passenger assignments must account for every unit exactly once."}
 else:
  for _id in models:rows.append({"units":1,"bed":0})
  var remaining=count-models.size()
  # Fill enclosed transport before pillion seats; each bike still has a driver.
  var order=[]
  for i in range(models.size()):
   if not motorcycle(models[i]):order.append(i)
  for i in range(models.size()):
   if motorcycle(models[i]):order.append(i)
  for i in order:
   var added=mini(remaining,int(Models.model(models[i]).unit_capacity)-1)
   rows[i].units+=added;remaining-=added
  for i in range(models.size()):rows[i].bed=mini(bed_capacity(models[i]),maxi(0,rows[i].units-1))
 return {"valid":true,"rows":rows,"error":""}

